const supabaseUrl = process.env.EXPO_PUBLIC_SUPABASE_URL;
const supabaseKey = process.env.EXPO_PUBLIC_SUPABASE_ANON_KEY;

const supabase = createClient(supabaseUrl, supabaseKey);

async function seedData() {
  console.log('--- Authenticating... ---');
  const { data: authData, error: authError } = await supabase.auth.signInWithPassword({
    email: 'admin_test99@gmail.com', // Using the admin account we created
    password: 'TestPassword123!',
  });

  if (authError) {
    console.error('Failed to authenticate:', authError);
    return;
  }

  console.log('--- Seeding AI Estimations & Notifications ---');

  // We need to fetch an active project ID for notifications
  const { data: projects, error: pError } = await supabase.from('projects').select('id, name').limit(3);

  let projectId = null;
  if (projects && projects.length > 0) {
    projectId = projects[0].id;
  }

  console.log('Inserting AI Estimations...');
  // 3 estimates spanning different confidence scores and statuses
  const { error: estError } = await supabase.from('estimations').insert([
    {
      project_name: 'Marina Tower',
      estimated_cost: 45000000.00,
      status: 'Approved',
      confidence_score: 85,
    },
    {
      project_name: 'City Mall Phase 2',
      estimated_cost: 22500000.00,
      status: 'Pending',
      confidence_score: 62,
    },
    {
      project_name: 'Green Villas',
      estimated_cost: 8000000.00,
      status: 'Draft',
      confidence_score: 35,
    }
  ]);

  if (estError) {
    console.error('Error inserting estimations:', estError);
  } else {
    console.log('Estimations inserted successfully!');
  }

  if (projectId) {
    console.log('Inserting Notifications...');
    const { error: notifError } = await supabase.from('notifications').insert([
      {
        project_id: projectId,
        title: 'Material Shortage Predicted',
        message: 'Cement inventory is projected to run out in 3 days based on current burn rate.',
        type: 'Warning',
        is_unread: true
      },
      {
        project_id: projectId,
        title: 'Labour Efficiency Peak',
        message: 'Site crew operated at 108% efficiency this week.',
        type: 'Success',
        is_unread: true
      },
      {
        project_id: projectId,
        title: 'Safety Audit Due',
        message: 'Quarterly compliance check is scheduled for tomorrow.',
        type: 'Info',
        is_unread: false
      },
      {
        project_id: projectId,
        title: 'Budget Threshold Warning',
        message: 'Electrical phase has consumed 85% of allocated funds.',
        type: 'Alert',
        is_unread: true
      }
    ]);

    if (notifError) {
      console.error('Error inserting notifications:', notifError);
    } else {
      console.log('Notifications inserted successfully!');
    }
  } else {
    console.log('No active projects found, skipping notifications seed.');
  }

  console.log('--- Done ---');
}

seedData();

import AuthPageLayout from '../components/auth/AuthPageLayout';
import React, { useState, useEffect } from 'react';
import { View, Text, TextInput, Pressable, ActivityIndicator, Image } from 'react-native';
import { Link, useRouter } from 'expo-router';
import { supabase } from '../lib/supabase';
import { MaterialIcons, Ionicons } from '@expo/vector-icons';
import AsyncStorage from '@react-native-async-storage/async-storage';
import { getDashboardForRole } from '../utils/auth';

const REMEMBER_EMAIL_KEY = 'cf_remember_email';

export default function LoginScreen() {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [errorMsg, setErrorMsg] = useState('');
  const [rememberMe, setRememberMe] = useState(false);
  const router = useRouter();

  // On mount: restore saved email if present
  useEffect(() => {
    const restoreEmail = async () => {
      try {
        const saved = await AsyncStorage.getItem(REMEMBER_EMAIL_KEY);
        if (saved) {
          setEmail(saved);
          setRememberMe(true);
        }
      } catch {
        // ignore restore failures
      }
    };
    restoreEmail();
  }, []);

  const handleLogin = async () => {
    if (!email || !password || !confirmPassword) {
      setErrorMsg('Please fill in all fields');
      return;
    }
    if (password !== confirmPassword) {
      setErrorMsg('Passwords do not match');
      return;
    }

    setLoading(true);
    setErrorMsg('');

    const { data, error } = await supabase.auth.signInWithPassword({ email, password });

    if (error) {
      setErrorMsg(error.message);
      setLoading(false);
      return;
    }

    // Handle Remember Me persistence
    try {
      if (rememberMe) {
        await AsyncStorage.setItem(REMEMBER_EMAIL_KEY, email);
      } else {
        await AsyncStorage.removeItem(REMEMBER_EMAIL_KEY);
      }
    } catch {
      // ignore persistence issues and continue with login routing
    }

    // Determine role and redirect to the matching dashboard
    try {
      const signedInUser = data.user;
      let role = signedInUser?.user_metadata?.role as string | undefined;

      if (!role) {
        // Fallback: query profiles table
        const { data: profile } = await supabase
          .from('profiles')
          .select('role')
          .eq('id', signedInUser?.id)
          .single();
        role = profile?.role;
      }

      const destination = getDashboardForRole(role);
      router.replace((destination ?? '/') as any);
    } catch {
      router.replace('/');
    }
  };

  const handleGoogleAuth = async () => {
    try {
      const { error } = await supabase.auth.signInWithOAuth({
        provider: 'google',
      });
      if (error) throw error;
    } catch (error: any) {
      setErrorMsg(error.message);
    }
  };

  return (
    <AuthPageLayout hero={
      <View className="w-1/2 py-12 bg-brand-dark relative overflow-hidden items-center justify-center">
        {/* Background Image with Overlay */}
        <Image 
          source={{ uri: 'https://images.unsplash.com/photo-1541888086925-ebbc14b62db4?q=80&w=1200' }} 
          className="absolute w-full h-full opacity-20"
          resizeMode="cover"
        />
        <View className="absolute inset-0 bg-brand-dark/90" />
        
        {/* Abstract Shapes */}
        <View className="absolute -top-32 -right-32 w-96 h-96 bg-brand-orange/20 rounded-full blur-3xl" />
        <View className="absolute -bottom-32 -left-32 w-96 h-96 bg-blue-500/10 rounded-full blur-3xl" />

        <View className="z-10 w-full px-8 xl:px-16 max-w-xl">
          <Text className="text-brand-orange font-bold tracking-widest text-sm uppercase mb-4">Construction Management Platform</Text>
          <Text className="text-white font-extrabold text-5xl leading-tight mb-6">Effortlessly manage your team and operations.</Text>
          <Text className="text-gray-400 text-lg leading-relaxed mb-12">Login as Admin to access your CRM, manage your team, track materials, and oversee active projects across all your sites in real-time.</Text>
          
          {/* Decorative preview */}
          <View className="bg-white/10 p-6 rounded-3xl border border-white/20 backdrop-blur-md shadow-2xl">
            <View className="flex-row items-center border-b border-white/10 pb-4 mb-4">
               <View className="w-3 h-3 rounded-full bg-red-400 mr-2" />
               <View className="w-3 h-3 rounded-full bg-yellow-400 mr-2" />
               <View className="w-3 h-3 rounded-full bg-green-400" />
            </View>
            <View className="flex-row mb-4">
              <View className="flex-1 bg-white/20 h-24 rounded-xl p-4 justify-end mr-4">
                 <View className="w-8 h-2 bg-white/40 rounded-full mb-2" />
                 <View className="w-20 h-4 bg-brand-orange rounded-full" />
              </View>
              <View className="flex-1 bg-white/20 h-24 rounded-xl p-4 justify-end">
                 <View className="w-12 h-2 bg-white/40 rounded-full mb-2" />
                 <View className="w-16 h-4 bg-white rounded-full" />
              </View>
            </View>
            <View className="w-full bg-white/20 h-32 rounded-xl" />
          </View>
        </View>
      </View>
    }>
          <View className="items-center mb-10">
            {/* ── Construct Ai Logo ── */}
            <Pressable
              onPress={() => router.push('/')}
              style={{ alignSelf: 'flex-start', width: '100%', maxWidth: 280, marginBottom: 24 }}
            >
              <Image 
                source={require('../../assets/images/main-logo.png')} 
                style={{ width: '100%', aspectRatio: 4 }} 
                resizeMode="contain" 
              />
            </Pressable>
            <View className="w-full">
              <Text className="text-3xl md:text-4xl font-extrabold text-brand-text mb-2">Admin Login</Text>
              <Text className="text-gray-500 text-base">Enter your email and password to access your account.</Text>
            </View>
          </View>

          {errorMsg ? (
            <View className="bg-red-50 p-3 rounded-lg border border-red-200 mb-6">
              <Text className="text-red-600 text-sm text-center">{errorMsg}</Text>
            </View>
          ) : null}

          <View className="mb-5">
            <Text className="text-sm font-semibold text-gray-700 mb-2">Email</Text>
            <TextInput
              className="w-full border border-gray-300 rounded-xl p-4 text-brand-text bg-gray-50 focus:border-brand-orange focus:bg-white transition-colors"
              placeholder="name@company.com"
              value={email}
              onChangeText={setEmail}
              autoCapitalize="none"
              keyboardType="email-address"
              returnKeyType="next"
            />
          </View>

          <View className="mb-6">
            <View className="flex-row justify-between items-center mb-2 z-10">
              <Text className="text-sm font-semibold text-gray-700">Password</Text>
              <Link href="/forgot-password" style={{ zIndex: 10 }}>
                <Text className="text-sm font-medium text-brand-orange hover:underline">Forgot password?</Text>
              </Link>
            </View>
            <View className="w-full flex-row items-center border border-gray-300 rounded-xl bg-gray-50 pr-2">
              <TextInput
                className="flex-1 p-4 text-brand-text outline-none"
                placeholder="••••••••"
                value={password}
                onChangeText={setPassword}
                secureTextEntry={!showPassword}
                returnKeyType="next"
              />
              <Pressable onPress={() => setShowPassword(!showPassword)} className="p-2 cursor-pointer min-w-[44px] min-h-[44px] items-center justify-center" accessibilityLabel={showPassword ? "Hide password" : "Show password"}>
                <Ionicons name={showPassword ? "eye-off" : "eye"} size={22} color="#9CA3AF" />
              </Pressable>
            </View>
          </View>

          <View className="mb-6">
            <Text className="text-sm font-semibold text-gray-700 mb-2">Confirm Password</Text>
            <View className="w-full flex-row items-center border border-gray-300 rounded-xl bg-gray-50 pr-2">
              <TextInput
                className="flex-1 p-4 text-brand-text outline-none"
                placeholder="••••••••"
                value={confirmPassword}
                onChangeText={setConfirmPassword}
                secureTextEntry={!showConfirmPassword}
                returnKeyType="done"
                onSubmitEditing={handleLogin}
              />
              <Pressable onPress={() => setShowConfirmPassword(!showConfirmPassword)} className="p-2 cursor-pointer min-w-[44px] min-h-[44px] items-center justify-center" accessibilityLabel={showConfirmPassword ? "Hide password" : "Show password"}>
                <Ionicons name={showConfirmPassword ? "eye-off" : "eye"} size={22} color="#9CA3AF" />
              </Pressable>
            </View>
          </View>
          
          {/* Remember Me — now functional */}
          <Pressable
            onPress={() => setRememberMe(prev => !prev)}
            className="flex-row items-center mb-8"
            accessibilityRole="checkbox"
            accessibilityState={{ checked: rememberMe }}
          >
            <View
              style={{
                width: 20, height: 20, borderRadius: 5,
                borderWidth: 1.5,
                borderColor: rememberMe ? '#F97316' : '#D1D5DB',
                backgroundColor: rememberMe ? '#F97316' : '#F9FAFB',
                alignItems: 'center', justifyContent: 'center',
                marginRight: 10,
              }}
            >
              {rememberMe && <Ionicons name="checkmark" size={13} color="#fff" />}
            </View>
            <Text className="text-gray-600 text-sm">Remember me</Text>
          </Pressable>

          <Pressable 
            onPress={handleLogin}
            disabled={loading}
            className={`w-full bg-brand-orange py-4 rounded-xl items-center justify-center shadow-md hover:bg-orange-600 transition-colors ${loading ? 'opacity-70' : ''}`}
          >
            {loading ? (
              <ActivityIndicator color="white" />
            ) : (
              <Text className="text-white font-bold text-lg">Login as Admin</Text>
            )}
          </Pressable>
          
          <View className="flex-row items-center justify-center my-8">
            <View className="flex-1 h-px bg-gray-200" />
            <Text className="px-4 text-gray-400 font-medium text-sm">Or Login With</Text>
            <View className="flex-1 h-px bg-gray-200" />
          </View>

          <View className="flex-row mb-8">
            <Pressable onPress={handleGoogleAuth} className="w-full flex-row items-center justify-center py-3 border border-gray-300 rounded-xl hover:bg-gray-50 transition-colors">
              <Image 
                source={{ uri: 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/c1/Google_%22G%22_logo.svg/120px-Google_%22G%22_logo.svg.png' }} 
                style={{ width: 20, height: 20, marginRight: 10 }} 
                resizeMode="contain"
              />
              <Text className="text-brand-text font-semibold text-base">Continue with Google</Text>
            </Pressable>
          </View>

          <View className="flex-row flex-wrap justify-center">
            <Text className="text-gray-500">Don&apos;t have an account? </Text>
            <Link href={"/register" as any} asChild>
              <Pressable>
                <Text className="text-brand-orange font-bold hover:underline">Register Now</Text>
              </Pressable>
            </Link>
          </View>
    </AuthPageLayout>
  );
}

import React, { useEffect, useState } from 'react';
import { View, ScrollView, ActivityIndicator, TextInput, Text } from 'react-native';
import { TopNav } from '@/components/common/TopNav';
import { StatCard } from '../../components/common/StatCard';
import { ClientAccountsPanel } from '../../components/client/ClientAccountsPanel';
import { RecentClientActivity } from '../../components/client/RecentClientActivity';
import { SharedDocuments } from '../../components/client/SharedDocuments';
import { InviteClientModal } from '../../components/client/InviteClientModal';
import { FontAwesome5, Ionicons } from '@expo/vector-icons';
import { supabase } from '../../lib/supabase';

import { useResponsive } from '../../hooks/useResponsive';
import { useTableRealtime } from '../../hooks/useTableRealtime';
import { GlobalSearchDropdown } from '@/components/common/GlobalSearchDropdown';

export default function ClientPortalScreen() {
  const [stats, setStats] = useState({
    activeClients: 0,
    sharedProjects: 0,
    pendingInvoices: 0,
  });
  const [loading, setLoading] = useState(true);
  
  const [isModalVisible, setModalVisible] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const { isMobile } = useResponsive();
  
  const { tick, lastUpdated } = useTableRealtime(['profiles', 'projects', 'invoices', 'client_activity', 'shared_documents']);

  useEffect(() => {
    let isMounted = true;
    const loadStats = async () => {
      try {
        const { data: sessionData } = await supabase.auth.getSession();
        if (!sessionData?.session) return;

        // Fetch counts
        const [clientsReq, projectsReq, invoicesReq] = await Promise.all([
          supabase.from('profiles').select('id', { count: 'exact', head: true }).eq('role', 'client'),
          supabase.from('projects').select('id', { count: 'exact', head: true }).eq('status', 'active'),
          supabase.from('invoices').select('id', { count: 'exact', head: true }).in('status', ['Unpaid', 'Overdue'])
        ]);

        if (isMounted) {
          setStats({
            activeClients: clientsReq.count || 0,
            sharedProjects: projectsReq.count || 0,
            pendingInvoices: invoicesReq.count || 0,
          });
        }
      } catch (error) {
        console.warn('Failed to load client stats:', error);
      } finally {
        if (isMounted) setLoading(false);
      }
    };

    loadStats();
    return () => { isMounted = false; };
  }, [tick]);

  const handleInvite = () => {
    setModalVisible(false);
    // tick will naturally update if profiles is updated
  };

  return (
    <View className="flex-1 bg-brand-light">
      <TopNav 
        title="Client Updates" 
        actionLabel="+ Invite Client" 
        onActionPress={() => setModalVisible(true)} 
      />
      
      {loading ? (
        <View className="flex-1 items-center justify-center">
          <ActivityIndicator size="large" color="#3B82F6" />
        </View>
      ) : (
        <ScrollView className={`flex-1 ${isMobile ? 'px-4 py-4' : 'p-6'}`} showsVerticalScrollIndicator={false}>
          
          <View style={{ flexDirection: 'column', marginBottom: 24, gap: 12, zIndex: 50, elevation: 50 }}>
            <Text className="text-2xl font-bold text-brand-text">All Clients</Text>
            <View className="flex-row items-center">
              <View className="w-2 h-2 rounded-full bg-green-500 mr-2" />
              <Text className="text-[11px] text-gray-500">Live{lastUpdated ? ` · updated ${lastUpdated.toLocaleTimeString()}` : ''}</Text>
            </View>
            
            <GlobalSearchDropdown 
              placeholder="Search clients..." 
              value={searchQuery}
              onChangeText={setSearchQuery}
              className={isMobile ? "w-full" : "w-64"}
              config={{
                table: 'profiles',
                searchColumn: 'full_name',
                secondaryColumn: 'email',
                titleColumn: 'full_name',
                subtitleColumn: 'email',
                routePrefix: '/admin/users/',
                filterColumn: 'role',
                filterValue: 'client'
              }}
            />
          </View>

          {/* Top Stat Cards Row */}
          <View style={isMobile ? { flexDirection: 'row', flexWrap: 'wrap', justifyContent: 'space-between', marginBottom: 16 } : { flexDirection: 'row', justifyContent: 'space-between', marginBottom: 24, marginHorizontal: -8 }}>
            <StatCard 
              label="Active Clients" 
              value={stats.activeClients.toString()} 
              indicatorText="" 
              icon={<FontAwesome5 name="user-friends" size={16} color="#9CA3AF" />}
            />
            <StatCard 
              label="Shared Projects" 
              value={stats.sharedProjects.toString()} 
              indicatorText="" 
              icon={<FontAwesome5 name="folder-open" size={16} color="#9CA3AF" />}
            />
            <StatCard 
              label="Pending Invoices" 
              value={stats.pendingInvoices.toString()}
              indicatorText="Requires client sign-off" 
              indicatorType="warning"
              icon={<Ionicons name="time" size={16} color="#F97316" />}
            />
          </View>

          {/* Main Content Layout */}
          <View style={isMobile ? { flexDirection: 'column', gap: 16 } : { flexDirection: 'row' }}>
            {/* Main Content Area (Client Accounts) */}
            <View style={isMobile ? { width: '100%' } : { flex: 2, marginRight: 24 }}>
              <ClientAccountsPanel refreshTrigger={tick} searchQuery={searchQuery} />
            </View>
            
            {/* Side Panel (Activity & Documents) */}
            <View style={isMobile ? { width: '100%', gap: 16 } : { flex: 1, flexDirection: 'column', gap: 24 }}>
              <RecentClientActivity refreshTrigger={tick} />
              <SharedDocuments refreshTrigger={tick} />
            </View>
          </View>
        </ScrollView>
      )}

      <InviteClientModal 
        visible={isModalVisible} 
        onClose={() => setModalVisible(false)} 
        onSuccess={handleInvite} 
      />
    </View>
  );
}

import React, { useEffect, useState } from 'react';
import { View, ScrollView, ActivityIndicator, Text, TextInput } from 'react-native';
import { TopNav } from '@/components/common/TopNav';
import { StatCard } from '../../components/common/StatCard';
import { CostTimelineChart } from '../../components/dashboard/CostTimelineChart';
import { BudgetUtilizationChart } from '../../components/dashboard/BudgetUtilizationChart';
import { MaterialsStockChart } from '../../components/dashboard/MaterialsStockChart';
import { PurchaseOrderPipelineChart } from '../../components/dashboard/PurchaseOrderPipelineChart';
import { MonthlyAttendanceChart } from '../../components/dashboard/MonthlyAttendanceChart';
import { DelayRiskPanel } from '../../components/dashboard/DelayRiskPanel';
import { ActiveProjectsTable } from '../../components/dashboard/ActiveProjectsTable';
import { RecentAlertsPanel } from '../../components/dashboard/RecentAlertsPanel';
import { NewProjectModal } from '../../components/dashboard/NewProjectModal';
import { supabase } from '../../lib/supabase';
import { GlobalSearchDropdown } from '../../components/common/GlobalSearchDropdown';
import { AnimatedCard } from '../../components/common/AnimatedCard';
import { Ionicons } from '@expo/vector-icons';
import { useResponsive } from '../../hooks/useResponsive';

export default function DashboardScreen() {
  const { isMobile } = useResponsive();
  const [stats, setStats] = useState({
    activeProjects: 0,
    workersOnSite: 0,
    lowStockAlerts: 0,
    totalBudget: 0,
  });
  const [loading, setLoading] = useState(true);
  
  const [isModalVisible, setModalVisible] = useState(false);
  const [refreshTrigger, setRefreshTrigger] = useState(0);
  const [searchQuery, setSearchQuery] = useState('');

  useEffect(() => {
    let isMounted = true;
    const loadStats = async () => {
      try {
        const { data: sessionData } = await supabase.auth.getSession();
        if (!sessionData?.session) return;

        // Fetch counts from various tables
        const today = new Date().toISOString().split('T')[0];
        const [projectsReq, labourReq, materialsReq, budgetReq] = await Promise.all([
          supabase.from('projects').select('*', { count: 'exact', head: true }).in('status', ['active', 'Active', 'In Progress', 'in progress']),
          supabase.from('attendance').select('*', { count: 'exact', head: true }).eq('date', today).eq('status', 'Present').is('check_out_time', null),
          // Assuming materials has current_stock and minimum_threshold. Since we can't do raw sql in select, we can fetch them.
          // Wait, the prompt said: .lt('current_stock', supabase.raw('minimum_threshold')) - supabase.raw doesn't exist in JS client.
          // A better way is to fetch all and filter in JS if there's no SQL function, or call an RPC. For now, fetch all materials and filter:
          supabase.from('materials').select('current_stock, minimum_threshold'),
          supabase.from('projects').select('total_budget').in('status', ['active', 'Active', 'In Progress', 'in progress'])
        ]);

        let lowStockCount = 0;
        if (materialsReq.data) {
          lowStockCount = materialsReq.data.filter(m => (m.current_stock || 0) < (m.minimum_threshold || 0)).length;
        }

        let totalBudget = 0;
        if (budgetReq.data) {
          totalBudget = budgetReq.data.reduce((sum, item) => sum + (Number(item.total_budget) || 0), 0);
        }

        if (isMounted) {
          setStats({
            activeProjects: projectsReq.count || 0,
            workersOnSite: labourReq.count || 0,
            lowStockAlerts: lowStockCount,
            totalBudget: totalBudget,
          });
        }
      } catch (error) {
        console.warn('Failed to load dashboard stats:', error);
      } finally {
        if (isMounted) setLoading(false);
      }
    };

    loadStats();
    
    // Realtime subscription for Bug 9
    const channel = supabase
      .channel('admin-dashboard-stats')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'attendance' }, () => setRefreshTrigger(prev => prev + 1))
      .on('postgres_changes', { event: '*', schema: 'public', table: 'projects' }, () => setRefreshTrigger(prev => prev + 1))
      .subscribe();

    return () => { 
      isMounted = false; 
      supabase.removeChannel(channel);
    };
  }, [refreshTrigger]);

  const handleProjectCreated = () => {
    setModalVisible(false);
    // Incrementing this triggers useEffect here and in ActiveProjectsTable
    setRefreshTrigger(prev => prev + 1);
  };

  const formatCurrency = (amount: number) => {
    if (amount >= 1000000) return `Rs. ${(amount / 1000000).toFixed(1)}M`;
    if (amount >= 1000) return `Rs. ${(amount / 1000).toFixed(1)}K`;
    return `Rs. ${amount}`;
  };

  return (
    <View className="flex-1 bg-brand-light">
      <TopNav 
        title="Admin Dashboard" 
        actionLabel="+ New Project" 
        onActionPress={() => setModalVisible(true)} 
      />
      
      {loading ? (
        <View className="flex-1 items-center justify-center">
          <ActivityIndicator size="large" color="#F97316" />
        </View>
      ) : (
        <ScrollView className="flex-1 p-6" showsVerticalScrollIndicator={false}>
          <View style={{ flexDirection: 'column', marginBottom: 24, gap: 12, zIndex: 50, elevation: 50 }}>
            <Text className="text-2xl font-bold text-brand-text">Admin Dashboard</Text>
            
            <GlobalSearchDropdown 
              placeholder="Search projects..." 
              value={searchQuery} 
              onChangeText={setSearchQuery} 
              className={isMobile ? "w-full" : "w-64"}
              config={{
                table: 'projects',
                searchColumn: 'name',
                secondaryColumn: 'location',
                titleColumn: 'name',
                subtitleColumn: 'location',
                routePrefix: '/admin/projects/'
              }}
            />
          </View>

          {/* Top Stat Cards Row */}
          <View style={isMobile ? { flexDirection: 'row', flexWrap: 'wrap', justifyContent: 'space-between', marginBottom: 16 } : { flexDirection: 'row', justifyContent: 'space-between', marginBottom: 24, marginHorizontal: -8 }}>
            <AnimatedCard delay={100} style={isMobile ? { width: '48%', marginBottom: 16 } : { flex: 1 }}>
              <StatCard 
                label="Active Projects" 
                value={stats.activeProjects.toString()} 
                indicatorText="Live tracking" 
                indicatorType="success" 
                fullWidth
              />
            </AnimatedCard>
            <AnimatedCard delay={200} style={isMobile ? { width: '48%', marginBottom: 16 } : { flex: 1 }}>
              <StatCard 
                label="Workers On Site" 
                value={stats.workersOnSite.toString()} 
                indicatorText="Currently checked in" 
                fullWidth
              />
            </AnimatedCard>
            <AnimatedCard delay={300} style={isMobile ? { width: '48%', marginBottom: 16 } : { flex: 1 }}>
              <StatCard 
                label="Low Stock Alerts" 
                value={stats.lowStockAlerts.toString()} 
                indicatorText="Requires ordering" 
                indicatorType={stats.lowStockAlerts > 0 ? "danger" : "success"} 
                fullWidth
              />
            </AnimatedCard>
            <AnimatedCard delay={400} style={isMobile ? { width: '48%', marginBottom: 16 } : { flex: 1 }}>
              <StatCard 
                label="Total Budget" 
                value={formatCurrency(stats.totalBudget)} 
                indicatorText="Approved estimates" 
                fullWidth
              />
            </AnimatedCard>
          </View>

          {/* Center Row: Chart & Delay Risk */}
          <View className={`mb-6 gap-6 ${isMobile ? 'flex-col' : 'flex-row'}`}>
            {/* Main Content Area (Chart) */}
            <View className="flex-[2] w-full">
              <CostTimelineChart />
            </View>
            
            {/* Side Panel (Delay Risk) */}
            <View className="flex-[1] w-full">
              <DelayRiskPanel />
            </View>
          </View>

          {/* New Charts Grid Row 1 */}
          <View className={`mb-6 gap-6 ${isMobile ? 'flex-col' : 'flex-row'}`}>
            <View className="flex-1 w-full">
              <BudgetUtilizationChart />
            </View>
            <View className="flex-1 w-full">
              <MaterialsStockChart />
            </View>
          </View>

          {/* New Charts Grid Row 2 */}
          <View className={`mb-6 gap-6 ${isMobile ? 'flex-col' : 'flex-row'}`}>
            <View className="flex-1 w-full">
              <PurchaseOrderPipelineChart />
            </View>
            <View className="flex-1 w-full">
              <MonthlyAttendanceChart />
            </View>
          </View>

          {/* Bottom Row: Active Projects & Recent Alerts */}
          <View className={`pb-6 gap-6 ${isMobile ? 'flex-col' : 'flex-row'}`}>
            <View className="flex-[2] w-full">
              <ActiveProjectsTable refreshTrigger={refreshTrigger} searchQuery={searchQuery} />
            </View>
            
            <View className="flex-[1] w-full">
              <RecentAlertsPanel />
            </View>
          </View>
          
        </ScrollView>
      )}

      <NewProjectModal 
        visible={isModalVisible} 
        onClose={() => setModalVisible(false)} 
        onSuccess={handleProjectCreated} 
      />
    </View>
  );
}

import React, { useEffect, useState } from 'react';
import { View, ScrollView, ActivityIndicator, Pressable, Text, TextInput } from 'react-native';
import { useRouter } from 'expo-router';
import { Ionicons } from '@expo/vector-icons';
import { TopNav } from '@/components/common/TopNav';
import { StatCard } from '../../../components/common/StatCard';
import { AttendanceTable } from '../../../components/labour/AttendanceTable';
import { PayrollSummary } from '../../../components/labour/PayrollSummary';
import { LabourDistributionChart } from '../../../components/labour/LabourDistributionChart';
import { CheckInWorkerModal } from '../../../components/labour/CheckInWorkerModal';
import { supabase } from '../../../lib/supabase';
import { GlobalSearchDropdown } from '@/components/common/GlobalSearchDropdown';

import { useResponsive } from '../../../hooks/useResponsive';
import { useTableRealtime } from '../../../hooks/useTableRealtime';

export default function LabourForceScreen() {
  const router = useRouter();
  const [stats, setStats] = useState({
    totalWorkers: 0,
    checkedInToday: 0,
    activeSites: 0,
    pendingPayroll: 0,
  });
  const [loading, setLoading] = useState(true);
  
  const [isModalVisible, setModalVisible] = useState(false);
  const [refreshTrigger, setRefreshTrigger] = useState(0);
  const [searchQuery, setSearchQuery] = useState('');
  const { isMobile } = useResponsive();
  const { tick, lastUpdated } = useTableRealtime(['legacy_labour', 'profiles', 'projects', 'salary_slips']);
  const liveTrigger = refreshTrigger + tick;

  useEffect(() => {
    let isMounted = true;
    const loadStats = async () => {
      try {
        const { data: sessionData } = await supabase.auth.getSession();
        if (!sessionData?.session) return;

        const today = new Date().toISOString().split('T')[0];

        const [workersReq, checkinsReq, sitesReq, labourReq] = await Promise.all([
          supabase.from('profiles').select('id', { count: 'exact', head: true }).eq('role', 'worker'),
          supabase.from('legacy_labour').select('id', { count: 'exact', head: true }).eq('date', today).eq('status', 'Present'),
          supabase.from('projects').select('id', { count: 'exact', head: true }).eq('status', 'active'),
          supabase.from('legacy_labour').select('hours_worked').eq('date', today).eq('status', 'Present')
        ]);
        
        let overtimeHrs = 0;
        if (labourReq.data) {
          labourReq.data.forEach((r: any) => {
             const hrs = Number(r.hours_worked) || 0;
             if (hrs > 8) overtimeHrs += (hrs - 8);
          });
        }

        if (isMounted) {
          setStats({
            totalWorkers: workersReq.count || 0,
            checkedInToday: checkinsReq.count || 0,
            activeSites: sitesReq.count || 0, 
            pendingPayroll: Math.round(overtimeHrs), 
          });
        }
      } catch (error) {
        console.warn('Failed to load labour stats:', error);
      } finally {
        if (isMounted) setLoading(false);
      }
    };

    loadStats();
    return () => { isMounted = false; };
  }, [liveTrigger]);

  const handleWorkerCreated = () => {
    setModalVisible(false);
    setRefreshTrigger(prev => prev + 1);
  };

  return (
    <View className="flex-1 bg-brand-light">
      <TopNav 
        title="Labour Force" 
        actionLabel="+ Add Worker" 
        onActionPress={() => router.push('/admin/users/create')} 
      />
      
      {loading ? (
        <View className="flex-1 items-center justify-center">
          <ActivityIndicator size="large" color="#3B82F6" />
        </View>
      ) : (
        <ScrollView className={`flex-1 ${isMobile ? 'px-4 py-4' : 'p-6'}`} showsVerticalScrollIndicator={false}>
          
          <View style={{ flexDirection: 'column', marginBottom: 24, gap: 12, zIndex: 50, elevation: 50 }}>
            <Text className="text-2xl font-bold text-brand-text">All Workers</Text>
            <View className="flex-row items-center">
              <View className="w-2 h-2 rounded-full bg-green-500 mr-2" />
              <Text className="text-[11px] text-gray-500">Live{lastUpdated ? ` · updated ${lastUpdated.toLocaleTimeString()}` : ''}</Text>
            </View>
            
            <GlobalSearchDropdown 
              placeholder="Search workers..." 
              value={searchQuery} 
              onChangeText={setSearchQuery} 
              className={isMobile ? "w-full" : "w-64"}
              config={{
                table: 'profiles',
                searchColumn: 'full_name',
                secondaryColumn: 'email',
                titleColumn: 'full_name',
                subtitleColumn: 'email',
                routePrefix: '/admin/users/',
                filterColumn: 'role',
                filterValue: 'worker'
              }}
            />
          </View>

          {/* Top Stat Cards Row */}
          <View style={isMobile ? { flexDirection: 'row', flexWrap: 'wrap', justifyContent: 'space-between', marginBottom: 16 } : { flexDirection: 'row', justifyContent: 'space-between', marginBottom: 24, marginHorizontal: -8 }}>
            <StatCard 
              label="Total Workers" 
              value={stats.totalWorkers.toString()} 
              indicatorText="" 
            />
            <StatCard 
              label="Checked In Today" 
              value={stats.checkedInToday.toString()} 
              indicatorText="" 
            />
            <StatCard 
              label="Today's Overtime" 
              value={`${stats.pendingPayroll} hrs`} 
              indicatorText="Additional hours" 
              indicatorType="warning" 
            />
            <StatCard 
              label="Active Sites" 
              value={stats.activeSites.toString()} 
              indicatorText="" 
            />
          </View>

          {/* Quick Actions */}
          <View style={{ flexDirection: isMobile ? 'column' : 'row', gap: 12, marginBottom: 24 }}>
            <Pressable onPress={() => router.push('/admin/attendance')} className="bg-indigo-50 px-4 py-3 rounded-lg border border-indigo-100 flex-row items-center">
              <Ionicons name="time-outline" size={20} color="#4F46E5" />
              <Text className="text-indigo-700 font-bold ml-2">Attendance Logs</Text>
            </Pressable>
            <Pressable onPress={() => router.push('/admin/payroll')} className="bg-green-50 px-4 py-3 rounded-lg border border-green-100 flex-row items-center">
              <Ionicons name="cash-outline" size={20} color="#10B981" />
              <Text className="text-green-700 font-bold ml-2">Payroll Generation</Text>
            </Pressable>
          </View>

          {/* Main Content Layout */}
          <View style={isMobile ? { flexDirection: 'column', gap: 16 } : { flexDirection: 'row' }}>
            {/* Main Content Area (Attendance Table) */}
            <View style={isMobile ? { width: '100%' } : { flex: 2, marginRight: 24 }}>
              <AttendanceTable refreshTrigger={liveTrigger} searchQuery={searchQuery} />
            </View>
            
            {/* Side Panel (Payroll & Chart) */}
            <View style={isMobile ? { width: '100%', gap: 16 } : { flex: 1, flexDirection: 'column', gap: 24 }}>
              <PayrollSummary refreshTrigger={liveTrigger} />
              <View style={isMobile ? { height: 256, marginTop: 16 } : { height: 256 }}>
                <LabourDistributionChart refreshTrigger={liveTrigger} />
              </View>
            </View>
          </View>
        </ScrollView>
      )}

      <CheckInWorkerModal 
        visible={isModalVisible} 
        onClose={() => setModalVisible(false)} 
        onSuccess={handleWorkerCreated} 
      />
    </View>
  );
}

import React, { useEffect, useState } from 'react';
import { View, ScrollView, ActivityIndicator, Pressable, Text, TextInput } from 'react-native';
import { useRouter } from 'expo-router';
import { TopNav } from '@/components/common/TopNav';
import { StatCard } from '../../../components/common/StatCard';
import { InventoryTable } from '../../../components/materials/InventoryTable';
import { LowStockAlerts } from '../../../components/materials/LowStockAlerts';
import { PendingOrders } from '../../../components/materials/PendingOrders';
import { PendingDeliveries } from '../../../components/materials/PendingDeliveries';
import { RecentDeliveries } from '../../../components/materials/RecentDeliveries';
import { NewMaterialModal } from '../../../components/materials/NewMaterialModal';
import { Ionicons } from '@expo/vector-icons';
import { supabase } from '../../../lib/supabase';
import { GlobalSearchDropdown } from '@/components/common/GlobalSearchDropdown';

import { useResponsive } from '../../../hooks/useResponsive';

export default function MaterialsScreen() {
  const router = useRouter();
  const [stats, setStats] = useState({
    totalMaterials: 0,
    pendingDeliveries: 0,
    lowStockAlerts: 0,
    totalValue: 0,
  });
  const [loading, setLoading] = useState(true);
  
  const [isModalVisible, setModalVisible] = useState(false);
  const [refreshTrigger, setRefreshTrigger] = useState(0);
  const [searchQuery, setSearchQuery] = useState('');
  const [projects, setProjects] = useState<any[]>([]);
  const [selectedProjectId, setSelectedProjectId] = useState<string>('');
  const [showProjectDrop, setShowProjectDrop] = useState(false);
  const { isMobile } = useResponsive();

  useEffect(() => {
    let isMounted = true;
    const loadStats = async () => {
      try {
        const { data: sessionData } = await supabase.auth.getSession();
        if (!sessionData?.session) return;

        const [materialsReq, ordersReq, projectsReq] = await Promise.all([
          supabase.from('materials').select('current_stock, minimum_threshold, unit_price'),
          supabase.from('purchase_orders').select('*', { count: 'exact', head: true }).in('status', ['Pending Delivery', 'Confirmed']),
          supabase.from('projects').select('id, name').eq('status', 'active').order('name')
        ]);

        let totalMaterials = 0;
        let lowStockAlerts = 0;
        let totalValue = 0;

        if (materialsReq.data) {
          totalMaterials = materialsReq.data.length;
          lowStockAlerts = materialsReq.data.filter(m => (m.current_stock || 0) < (m.minimum_threshold || 1)).length;
          totalValue = materialsReq.data.reduce((sum, m) => sum + ((m.current_stock || 0) * (m.unit_price || 0)), 0);
        }

        if (isMounted) {
          setStats({
            totalMaterials,
            pendingDeliveries: ordersReq.count || 0,
            lowStockAlerts,
            totalValue,
          });
          if (projectsReq.data) {
            setProjects(projectsReq.data);
          }
        }
      } catch (error) {
        console.warn('Failed to load material stats:', error);
      } finally {
        if (isMounted) setLoading(false);
      }
    };

    loadStats();

    const chan1 = supabase.channel('admin-materials')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'materials' }, loadStats)
      .subscribe();
    
    const chan2 = supabase.channel('admin-po')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'purchase_orders' }, loadStats)
      .subscribe();

    return () => { 
      isMounted = false; 
      supabase.removeChannel(chan1);
      supabase.removeChannel(chan2);
    };
  }, [refreshTrigger]);

  const handleOrderCreated = () => {
    setModalVisible(false);
    setRefreshTrigger(prev => prev + 1);
  };

  return (
    <View className="flex-1 bg-brand-light">
      <TopNav 
        title="Materials" 
        actionLabel="+ New Order" 
        onActionPress={() => router.push('/admin/materials/orders/create')} 
      />
      
      {loading ? (
        <View className="flex-1 items-center justify-center">
          <ActivityIndicator size="large" color="#F97316" />
        </View>
      ) : (
        <ScrollView className={`flex-1 ${isMobile ? 'px-4 py-4' : 'p-6'}`} showsVerticalScrollIndicator={false}>
          
          <View style={{ flexDirection: isMobile ? 'column' : 'row', justifyContent: 'space-between', alignItems: isMobile ? 'flex-start' : 'center', marginBottom: 24, gap: 12, zIndex: 50, elevation: 50 }}>
            <Text className="text-2xl font-bold text-brand-text">All Materials</Text>
            
            <View style={{ flexDirection: isMobile ? 'column' : 'row', gap: 12, width: isMobile ? '100%' : 'auto', zIndex: 50 }}>
              {/* Project Filter */}
              <View className="relative w-full" style={!isMobile ? { width: 220 } : {}}>
                <Pressable 
                  onPress={() => setShowProjectDrop(!showProjectDrop)}
                  className="flex-row justify-between items-center bg-white border border-gray-200 rounded-lg px-4 py-2 shadow-sm h-10"
                >
                  <Text className={selectedProjectId ? "text-brand-text text-sm" : "text-gray-400 text-sm"} numberOfLines={1}>
                    {selectedProjectId ? projects.find(p => p.id === selectedProjectId)?.name : 'All Projects'}
                  </Text>
                  <Ionicons name="chevron-down" size={16} color="#9CA3AF" />
                </Pressable>
                
                {showProjectDrop && (
                  <View className="absolute top-full left-0 right-0 bg-white border border-gray-200 mt-1 rounded-lg shadow-lg max-h-48 z-[60]">
                    <ScrollView nestedScrollEnabled={true}>
                      <Pressable 
                        onPress={() => { setSelectedProjectId(''); setShowProjectDrop(false); }}
                        className="px-4 py-3 border-b border-gray-100 hover:bg-gray-50"
                      >
                        <Text className="text-gray-800 font-bold">All Projects</Text>
                      </Pressable>
                      {projects.map(proj => (
                        <Pressable 
                          key={proj.id} 
                          onPress={() => { setSelectedProjectId(proj.id); setShowProjectDrop(false); }}
                          className="px-4 py-3 border-b border-gray-100 hover:bg-gray-50"
                        >
                          <Text className="text-gray-800 text-sm">{proj.name}</Text>
                        </Pressable>
                      ))}
                    </ScrollView>
                  </View>
                )}
              </View>

              {/* Search */}
              <GlobalSearchDropdown 
                placeholder="Search materials..." 
                value={searchQuery} 
                onChangeText={setSearchQuery} 
                className={isMobile ? "w-full" : "w-[220px]"}
                config={{
                  table: 'materials',
                  searchColumn: 'name',
                  secondaryColumn: 'category',
                  titleColumn: 'name',
                  subtitleColumn: 'category'
                }}
              />
            </View>
          </View>

          {/* Top Stat Cards Row */}
          <View style={isMobile ? { flexDirection: 'row', flexWrap: 'wrap', justifyContent: 'space-between', marginBottom: 16 } : { flexDirection: 'row', justifyContent: 'space-between', marginBottom: 24, marginHorizontal: -8 }}>
            <StatCard 
              label="Total Materials" 
              value={stats.totalMaterials.toString()} 
              indicatorText={`Items in inventory`} 
            />
            <StatCard 
              label="Low Stock Alerts" 
              value={stats.lowStockAlerts.toString()} 
              indicatorText={stats.lowStockAlerts > 0 ? "Requires ordering" : "All stock healthy"} 
              indicatorType={stats.lowStockAlerts > 0 ? "warning" : "success"} 
              icon={<Ionicons name={stats.lowStockAlerts > 0 ? "warning" : "checkmark-circle"} size={16} color={stats.lowStockAlerts > 0 ? "#F97316" : "#22C55E"} />}
            />
            <StatCard 
              label="Pending Deliveries" 
              value={stats.pendingDeliveries.toString()}
              indicatorText="Arriving soon" 
            />
            <StatCard 
              label="Total Inventory Value" 
              value={`Rs. ${(stats.totalValue / 1000000).toFixed(1)}M`}
              indicatorText="Value across all sites" 
              indicatorType="neutral" 
            />
          </View>

          {/* Quick Actions */}
          <View style={{ flexDirection: isMobile ? 'column' : 'row', gap: 12, marginBottom: 24 }}>
            <Pressable onPress={() => router.push('/admin/materials/orders')} className="bg-emerald-50 px-4 py-3 rounded-lg border border-emerald-100 flex-row items-center">
              <Ionicons name="cart-outline" size={20} color="#10B981" />
              <Text className="text-emerald-700 font-bold ml-2">All Purchase Orders</Text>
            </Pressable>
            <Pressable onPress={() => router.push('/admin/materials/stock')} className="bg-blue-50 px-4 py-3 rounded-lg border border-blue-100 flex-row items-center">
              <Ionicons name="cube-outline" size={20} color="#3B82F6" />
              <Text className="text-blue-700 font-bold ml-2">Site Stock Levels</Text>
            </Pressable>
          </View>

          {/* Main Content Layout */}
          <View style={isMobile ? { flexDirection: 'column', gap: 16 } : { flexDirection: 'row' }}>
            {/* Main Content Area (Inventory Table) */}
            <View style={isMobile ? { width: '100%', zIndex: 10 } : { flex: 2, marginRight: 24, zIndex: 10 }}>
              <InventoryTable refreshTrigger={refreshTrigger} searchQuery={searchQuery} projectId={selectedProjectId} />
            </View>
            
            {/* Side Panel (Alerts & Deliveries) */}
            <View style={isMobile ? { width: '100%', gap: 16 } : { flex: 1 }}>
              <LowStockAlerts refreshTrigger={refreshTrigger} />
              <PendingDeliveries refreshTrigger={refreshTrigger} />
              <PendingOrders refreshTrigger={refreshTrigger} onRefreshNeeded={() => setRefreshTrigger(p=>p+1)} />
              <RecentDeliveries refreshTrigger={refreshTrigger} />
            </View>
          </View>
        </ScrollView>
      )}

      <NewMaterialModal 
        visible={isModalVisible} 
        onClose={() => setModalVisible(false)} 
        onSuccess={handleOrderCreated} 
      />
    </View>
  );
}

