import { firstRelation } from '@/utils/relations';
import { ModalViewport } from '@/components/common/ModalViewport';
import React, { useEffect, useState } from 'react';
import { View, Text, ScrollView, ActivityIndicator, Pressable, TextInput, Platform } from 'react-native';
import { useRouter } from 'expo-router';
import { supabase } from '../../../../lib/supabase';
import { TopNav } from '@/components/common/TopNav';
import { Ionicons } from '@expo/vector-icons';
import { format } from 'date-fns';
import { Modal } from 'react-native';
import { useResponsive } from '../../../../hooks/useResponsive';

export default function AdminStockLevels() {
  const router = useRouter();
  const { isMobile } = useResponsive();
  const [materials, setMaterials] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState('All');

  useEffect(() => {
    let isMounted = true;
    const fetchStock = async () => {
      try {
        let query = supabase.from('materials').select(`
          id, name, unit, current_stock, minimum_threshold, last_updated, project_id,
          project:projects(name)
        `).order('last_updated', { ascending: false });
        
        const { data, error } = await query;
        if (error) throw error;
        
        let filteredData = (data || []).map(material => ({ ...material, project: firstRelation(material.project) }));
        
        if (statusFilter !== 'All') {
          filteredData = filteredData.filter(m => {
            const currentStock = m.current_stock || 0;
            const minThreshold = m.minimum_threshold || 1;
            let calcStatus = 'In Stock';
            if (currentStock === 0) calcStatus = 'Out of Stock';
            else if (currentStock < minThreshold) calcStatus = 'Low Stock';
            return calcStatus === statusFilter;
          });
        }

        if (search) {
          filteredData = filteredData.filter(m => 
            m.name?.toLowerCase().includes(search.toLowerCase()) || 
            m.project?.name?.toLowerCase().includes(search.toLowerCase())
          );
        }
        
        if (isMounted) setMaterials(filteredData);
      } catch (err: any) {
        if (Platform.OS === 'web') console.error('Error fetching stock', err.message);
      } finally {
        if (isMounted) setLoading(false);
      }
    };
    
    fetchStock();
    return () => { isMounted = false; };
  }, [search, statusFilter, loading]); // Added loading to dependency array so it refreshes on assign

  const statuses = ['All', 'In Stock', 'Low Stock', 'Out of Stock'];

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'In Stock': return 'bg-green-100 text-green-700';
      case 'Low Stock': return 'bg-yellow-100 text-yellow-700';
      case 'Out of Stock': return 'bg-red-100 text-red-700';
      default: return 'bg-gray-100 text-gray-700';
    }
  };

  const [assignModalVisible, setAssignModalVisible] = useState(false);
  const [selectedMaterialId, setSelectedMaterialId] = useState<string | null>(null);
  const [projects, setProjects] = useState<any[]>([]);

  useEffect(() => {
    if (assignModalVisible) {
      supabase.from('projects').select('id, name').eq('status', 'active').then(({ data }) => {
        if (data) setProjects(data);
      });
    }
  }, [assignModalVisible]);

  const handleAssign = async (projectId: string) => {
    if (!selectedMaterialId) return;
    try {
      await supabase.from('materials').update({ project_id: projectId }).eq('id', selectedMaterialId);
      setAssignModalVisible(false);
      setLoading(true); // Trigger a refresh
    } catch (e) {
      console.error(e);
    }
  };

  return (
    <View className="flex-1 flex-col bg-gray-50">
      <TopNav 
        title="Materials Inventory" 
        actionLabel="+ New Order" 
        onActionPress={() => router.push('/admin/materials/orders/create')} 
      />
      
      <ScrollView className="flex-1 px-4 py-4 md:px-6 md:py-6 lg:px-8" showsVerticalScrollIndicator={false}>
        <Pressable onPress={() => router.push('/admin/materials')} className="flex-row items-center mb-6 self-start">
          <Ionicons name="arrow-back" size={20} color="#6B7280" />
          <Text className="text-gray-500 font-semibold ml-2">Back to Dashboard</Text>
        </Pressable>

        <View style={{ flexDirection: isMobile ? 'column' : 'row', justifyContent: isMobile ? 'flex-start' : 'space-between', alignItems: isMobile ? 'flex-start' : 'center', marginBottom: 24, gap: isMobile ? 12 : 0 }}>
          <Text className="text-2xl font-bold text-brand-text">Site Inventory</Text>
          
          <View style={{ flexDirection: isMobile ? 'column' : 'row', gap: 16, width: isMobile ? '100%' : 'auto' }}>
            <View className="flex-row border border-gray-200 rounded-lg overflow-hidden bg-white">
              <ScrollView horizontal showsHorizontalScrollIndicator={false}>
                {statuses.map(s => (
                  <Pressable 
                    key={s}
                    onPress={() => setStatusFilter(s)}
                    className={`px-4 py-2 ${statusFilter === s ? 'bg-brand-orange' : 'hover:bg-gray-50'}`}
                  >
                    <Text className={`font-semibold text-xs ${statusFilter === s ? 'text-white' : 'text-gray-500'}`}>{s}</Text>
                  </Pressable>
                ))}
              </ScrollView>
            </View>

            <View style={{ flexDirection: 'row', alignItems: 'center', backgroundColor: '#fff', borderWidth: 1, borderColor: '#E5E7EB', borderRadius: 8, paddingHorizontal: 12, paddingVertical: 8, width: isMobile ? '100%' : 256, shadowColor: '#000', shadowOffset: { width: 0, height: 1 }, shadowOpacity: 0.05, shadowRadius: 2 }}>
              <Ionicons name="search" size={16} color="#9CA3AF" />
              <TextInput 
                className="flex-1 ml-2 text-sm text-brand-text outline-none"
                placeholder="Search material or site..."
                placeholderTextColor="#9CA3AF"
                value={search}
                onChangeText={setSearch}
              />
            </View>
          </View>
        </View>

        <View style={isMobile ? {} : { backgroundColor: '#fff', borderRadius: 12, padding: 24, minHeight: 400, borderWidth: 1, borderColor: '#F3F4F6' }}>
          {!isMobile && (
            <View className="flex-row items-center bg-gray-50 py-4 border-b border-gray-200">
              <View className="w-[25%] px-6"><Text className="text-xs font-bold text-gray-500 uppercase">Material Name</Text></View>
              <View className="w-[25%]"><Text className="text-xs font-bold text-gray-500 uppercase">Project Site</Text></View>
              <View className="w-[15%]"><Text className="text-xs font-bold text-gray-500 uppercase">Quantity</Text></View>
              <View className="w-[20%]"><Text className="text-xs font-bold text-gray-500 uppercase">Stock Level</Text></View>
              <View className="w-[15%] pr-6"><Text className="text-xs font-bold text-gray-500 uppercase text-right">Status</Text></View>
            </View>
          )}

          {/* Table Body */}
          {loading ? (
            <View className="py-20 items-center justify-center">
              <ActivityIndicator color="#F97316" />
            </View>
          ) : materials.length === 0 ? (
            <View className="py-20 items-center justify-center">
              <Ionicons name="layers-outline" size={48} color="#D1D5DB" className="mb-4" />
              <Text className="text-gray-400 text-lg font-medium">No materials found.</Text>
            </View>
          ) : (
            materials.map(m => {
              const currentStock = m.current_stock || 0;
              const minThreshold = m.minimum_threshold || 1;
              const pct = Math.min(100, Math.round((currentStock / minThreshold) * 100));
              let calcStatus = 'In Stock';
              if (currentStock === 0) calcStatus = 'Out of Stock';
              else if (currentStock < minThreshold) calcStatus = 'Low Stock';

              return isMobile ? (
                <View key={m.id} style={{ flexDirection: 'column', backgroundColor: '#fff', borderRadius: 12, padding: 16, marginBottom: 16, borderWidth: 1, borderColor: '#F3F4F6', shadowColor: '#000', shadowOffset: { width: 0, height: 1 }, shadowOpacity: 0.05, shadowRadius: 2 }}>
                  <View style={{ flexDirection: 'row', justifyContent: 'space-between', marginBottom: 12 }}>
                    <View style={{ flex: 1 }}>
                      <Text style={{ color: '#111827', fontWeight: 'bold', fontSize: 16 }}>{m.name || 'Unnamed Material'}</Text>
                      {m.project_id ? (
                        <Text style={{ color: '#6B7280', fontSize: 12 }}>Project: {m.project?.name}</Text>
                      ) : (
                        <Pressable onPress={() => { setSelectedMaterialId(m.id); setAssignModalVisible(true); }} className="bg-brand-orange/10 self-start px-2 py-1 rounded mt-1">
                          <Text className="text-brand-orange text-xs font-bold">Assign to Project</Text>
                        </Pressable>
                      )}
                    </View>
                    <View style={{ alignItems: 'flex-end' }}>
                      <View className={`px-2 py-1 rounded ${getStatusColor(calcStatus)}`}>
                        <Text style={{ fontSize: 10, fontWeight: 'bold', textTransform: 'uppercase' }}>{calcStatus}</Text>
                      </View>
                    </View>
                  </View>
                  
                  <View style={{ flexDirection: 'row', justifyContent: 'space-between', marginBottom: 16 }}>
                    <View>
                      <Text style={{ color: '#9CA3AF', fontSize: 12, marginBottom: 4 }}>Quantity</Text>
                      <Text style={{ color: '#374151', fontWeight: 'bold', fontSize: 14 }}>{currentStock} {m.unit || 'units'}</Text>
                    </View>
                    <View style={{ alignItems: 'flex-end', width: '40%' }}>
                      <Text style={{ color: '#9CA3AF', fontSize: 12, marginBottom: 4 }}>Stock Level: {pct}%</Text>
                      <View style={{ width: '100%', height: 6, backgroundColor: '#E5E7EB', borderRadius: 3, overflow: 'hidden' }}>
                        <View 
                          style={{ height: '100%', width: `${pct}%`, backgroundColor: pct < 25 ? '#EF4444' : pct < 50 ? '#FACC15' : '#22C55E' }} 
                        />
                      </View>
                    </View>
                  </View>
                </View>
              ) : (
                <View key={m.id} className="flex-row items-center py-4 border-b border-gray-100 hover:bg-gray-50 transition-colors">
                  <View className="w-[25%] px-6">
                    <Text className="text-brand-text font-bold text-sm truncate">{m.name || 'Unnamed Material'}</Text>
                    <Text className="text-gray-400 text-[10px]">Updated: {format(new Date(m.last_updated), 'MMM dd, yyyy')}</Text>
                  </View>
                  
                  <View className="w-[25%] pr-2">
                    {m.project_id ? (
                      <Text className="text-gray-600 text-sm truncate font-medium">{m.project?.name}</Text>
                    ) : (
                      <Pressable onPress={() => { setSelectedMaterialId(m.id); setAssignModalVisible(true); }} className="bg-brand-orange/10 px-3 py-1.5 rounded-lg self-start">
                        <Text className="text-brand-orange text-xs font-bold">Assign</Text>
                      </Pressable>
                    )}
                  </View>
  
                  <View className="w-[15%] pr-2">
                    <Text className="text-gray-800 text-sm font-bold">{currentStock} {m.unit || 'units'}</Text>
                  </View>
                  
                  <View className="w-[20%] pr-4">
                    <View className="flex-row items-center">
                      <View className="flex-1 h-2 bg-gray-200 rounded-full overflow-hidden mr-3">
                        <View 
                          className={`h-full ${pct < 25 ? 'bg-red-500' : pct < 50 ? 'bg-yellow-400' : 'bg-green-500'}`} 
                          style={{ width: `${pct}%` }}
                        />
                      </View>
                      <Text className="text-gray-600 text-xs font-bold w-8 text-right">{pct}%</Text>
                    </View>
                  </View>
                  
                  <View className="w-[15%] pr-6 items-end">
                    <View className={`px-2 py-1 rounded ${getStatusColor(calcStatus)}`}>
                      <Text className="text-[10px] font-bold uppercase">{calcStatus}</Text>
                    </View>
                  </View>
                </View>
              );
            })
          )}
        </View>
      </ScrollView>

      <Modal visible={assignModalVisible} transparent animationType="fade" onRequestClose={() => setAssignModalVisible(false)}>
        <ModalViewport>
          <ScrollView keyboardShouldPersistTaps="handled" nestedScrollEnabled style={{ flexGrow: 0, flexShrink: 1 }} contentContainerStyle={{ padding: 24 }} className="bg-white rounded-2xl w-full max-w-md max-h-full">
            <Text className="text-xl font-bold text-brand-text mb-4">Assign Material to Project</Text>
            <Text className="text-gray-500 mb-4 text-sm">Select an active project to assign this material to.</Text>
            
            <ScrollView style={{ maxHeight: 300 }} showsVerticalScrollIndicator={false}>
              {projects.map(p => (
                <Pressable 
                  key={p.id}
                  onPress={() => handleAssign(p.id)}
                  className="py-3 px-4 border-b border-gray-100 hover:bg-gray-50 flex-row justify-between items-center"
                >
                  <Text className="text-brand-text font-semibold">{p.name}</Text>
                  <Ionicons name="chevron-forward" size={16} color="#D1D5DB" />
                </Pressable>
              ))}
              {projects.length === 0 && (
                <Text className="text-gray-400 text-center py-4">No active projects found.</Text>
              )}
            </ScrollView>

            <Pressable onPress={() => setAssignModalVisible(false)} className="mt-4 py-3 bg-gray-100 rounded-lg items-center">
              <Text className="text-gray-600 font-bold">Cancel</Text>
            </Pressable>
          </ScrollView>
        </ModalViewport>
      </Modal>

    </View>
  );
}

import React, { useEffect, useState } from 'react';
import { View, Text, ScrollView, Pressable, ActivityIndicator } from 'react-native';
import { TopNav } from '@/components/common/TopNav';
import { NotificationCard } from '../../components/notifications/NotificationCard';
import { FontAwesome5, Ionicons, MaterialIcons } from '@expo/vector-icons';
import { useRealtimeNotifications } from '../../hooks/useRealtimeNotifications';
import { useResponsive } from '../../hooks/useResponsive';

export default function NotificationsScreen() {
  const { notifications, loading, markAsRead, markAllAsRead } = useRealtimeNotifications();
  const { isMobile } = useResponsive();

  const getIconProps = (action: string) => {
    if (action.toLowerCase().includes('download')) return { iconFamily: FontAwesome5, iconName: 'download', iconColor: '#3B82F6' };
    if (action.toLowerCase().includes('comment')) return { iconFamily: FontAwesome5, iconName: 'comment-alt', iconColor: '#10B981' };
    if (action.toLowerCase().includes('approval')) return { iconFamily: Ionicons, iconName: 'time', iconColor: '#F59E0B' };
    return { iconFamily: MaterialIcons, iconName: 'notifications', iconColor: '#F97316' };
  };

  const getTimeAgo = (dateString: string) => {
    const date = new Date(dateString);
    const now = new Date();
    const diffInMinutes = Math.floor((now.getTime() - date.getTime()) / 60000);
    
    if (diffInMinutes < 60) return `${diffInMinutes} mins ago`;
    const diffInHours = Math.floor(diffInMinutes / 60);
    if (diffInHours < 24) return `${diffInHours} hrs ago`;
    const diffInDays = Math.floor(diffInHours / 24);
    if (diffInDays === 1) return `Yesterday`;
    return `${diffInDays} days ago`;
  };

  return (
    <View className="flex-1 bg-brand-light">
      <TopNav title="Notifications" showAction={false} />
      
      <ScrollView className={`flex-1 ${isMobile ? 'px-4 py-4' : 'px-8 py-6 max-w-4xl mx-auto w-full'}`} showsVerticalScrollIndicator={false}>
        
        {/* Header Controls */}
        <View style={{ flexDirection: isMobile ? 'column' : 'row', justifyContent: isMobile ? 'flex-start' : 'space-between', alignItems: isMobile ? 'flex-start' : 'center', marginBottom: 24, gap: isMobile ? 12 : 0 }}>
          <Text className="text-2xl font-bold text-brand-text">All Notifications</Text>
          <View style={{ flexDirection: 'row', alignItems: 'center', width: isMobile ? '100%' : undefined, justifyContent: isMobile ? 'space-between' : 'flex-end' }}>
            <Pressable className="mr-6" onPress={markAllAsRead}>
              <Text className="text-brand-orange text-sm font-semibold">Mark all as read</Text>
            </Pressable>
            <View className="border border-gray-200 bg-white rounded-lg px-4 py-2 flex-row items-center">
              <Text className="text-brand-text text-sm font-medium mr-2">All</Text>
              <Ionicons name="chevron-down" size={14} color="#6B7280" />
            </View>
          </View>
        </View>

        <View className="mb-12">
          {loading ? (
            <View className="py-10 items-center">
              <ActivityIndicator color="#F97316" />
            </View>
          ) : notifications.length === 0 ? (
            <View className="py-10 items-center">
              <Text className="text-gray-400">No notifications.</Text>
            </View>
          ) : (
            notifications.map((n) => {
              const props = getIconProps(n.title || '');
              return (
                <Pressable key={n.id} onPress={() => !n.is_read && markAsRead(n.id)}>
                  <NotificationCard 
                    title={n.title}
                    subtitle={`${n.message} · ${getTimeAgo(n.created_at)}`}
                    iconFamily={props.iconFamily}
                    iconName={props.iconName}
                    iconColor={props.iconColor}
                    isUnread={!n.is_read}
                  />
                </Pressable>
              );
            })
          )}
        </View>
        
      </ScrollView>
    </View>
  );
}

import React, { useState } from 'react';
import { View, Text, TextInput, Pressable, ActivityIndicator, Alert, ScrollView } from 'react-native';
import { useLocalSearchParams, useRouter } from 'expo-router';
import { supabase } from '../../../../../lib/supabase';
import { TopNav } from '@/components/common/TopNav';
import { Ionicons } from '@expo/vector-icons';
import { toast } from '../../../../../lib/toast';

export default function AdminCreateExpensePage() {
  const { id: projectId } = useLocalSearchParams();
  const router = useRouter();

  const [form, setForm] = useState({
    title: '',
    description: '',
    amount: '',
    expense_date: new Date().toISOString().split('T')[0]
  });
  const [loading, setLoading] = useState(false);

  const handleSubmit = async () => {
    if (!form.title || !form.amount) {
      toast.error('Title and Amount are required');
      return;
    }

    try {
      setLoading(true);
      const { data: sessionData } = await supabase.auth.getSession();

      const payload = {
        project_id: projectId,
        title: form.title,
        description: form.description || null,
        amount: parseFloat(form.amount),
        expense_date: form.expense_date
      };

      const response = await fetch(`${process.env.EXPO_PUBLIC_API_URL}/projects/${projectId}/expenses`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${sessionData.session?.access_token}`
        },
        body: JSON.stringify(payload)
      });

      if (!response.ok) {
        const err = await response.json();
        throw new Error(err.detail || "Failed to create expense");
      }

      toast.success('Expense added successfully');
      router.back();
    } catch (err: any) {
      toast.error(err.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <View className="flex-1 bg-brand-dark">
      <TopNav title="Add Expense" showBackButton />

      <ScrollView className="flex-1 p-6">
        <View className="bg-white rounded-3xl p-6 shadow-sm mb-10">

          <View className="mb-4">
            <Text className="text-gray-700 font-bold mb-2">Expense Title *</Text>
            <View className="flex-row items-center bg-gray-50 border border-gray-200 rounded-xl px-4 py-3">
              <Ionicons name="pricetag-outline" size={20} color="#9CA3AF" className="mr-3" />
              <TextInput
                className="flex-1 text-gray-800 font-medium"
                placeholder="e.g., Cement Bags, Site Equipment"
                placeholderTextColor="#9CA3AF"
                value={form.title}
                onChangeText={(t) => setForm({...form, title: t})}
              />
            </View>
          </View>

          <View className="mb-4">
            <Text className="text-gray-700 font-bold mb-2">Amount (Rs.) *</Text>
            <View className="flex-row items-center bg-gray-50 border border-gray-200 rounded-xl px-4 py-3">
              <Ionicons name="cash-outline" size={20} color="#EF4444" className="mr-3" />
              <TextInput
                className="flex-1 text-gray-800 font-medium"
                placeholder="0.00"
                placeholderTextColor="#9CA3AF"
                keyboardType="numeric"
                value={form.amount}
                onChangeText={(t) => setForm({...form, amount: t})}
              />
            </View>
          </View>

          <View className="mb-4">
            <Text className="text-gray-700 font-bold mb-2">Expense Date *</Text>
            <View className="flex-row items-center bg-gray-50 border border-gray-200 rounded-xl px-4 py-3">
              <Ionicons name="calendar-outline" size={20} color="#9CA3AF" className="mr-3" />
              <TextInput
                className="flex-1 text-gray-800 font-medium"
                placeholder="YYYY-MM-DD"
                placeholderTextColor="#9CA3AF"
                value={form.expense_date}
                onChangeText={(t) => setForm({...form, expense_date: t})}
              />
            </View>
          </View>

          <View className="mb-6">
            <Text className="text-gray-700 font-bold mb-2">Description (Optional)</Text>
            <View className="bg-gray-50 border border-gray-200 rounded-xl px-4 py-3 min-h-[100px]">
              <TextInput
                className="flex-1 text-gray-800 font-medium text-left align-top"
                placeholder="Add any extra details about this expense..."
                placeholderTextColor="#9CA3AF"
                multiline
                numberOfLines={4}
                value={form.description}
                onChangeText={(t) => setForm({...form, description: t})}
                style={{ textAlignVertical: 'top' }}
              />
            </View>
          </View>

          <Pressable
            onPress={handleSubmit}
            disabled={loading}
            className={`py-4 rounded-xl items-center flex-row justify-center ${loading ? 'bg-brand-orange/70' : 'bg-brand-orange'}`}
          >
            {loading ? (
              <ActivityIndicator color="white" className="mr-2" />
            ) : (
              <Ionicons name="checkmark-circle-outline" size={24} color="white" className="mr-2" />
            )}
            <Text className="text-white font-bold text-lg">Save Expense</Text>
          </Pressable>
        </View>
      </ScrollView>
    </View>
  );
}

import React, { useEffect, useState } from 'react';
import { View, Text, ScrollView, ActivityIndicator, Pressable, Alert } from 'react-native';
import { useLocalSearchParams, useRouter } from 'expo-router';
import { supabase } from '../../../../../lib/supabase';
import { TopNav } from '@/components/common/TopNav';
import { Ionicons } from '@expo/vector-icons';

export default function AdminExpensesIndexPage() {
  const { id: projectId } = useLocalSearchParams();
  const router = useRouter();
  const [loading, setLoading] = useState(true);
  const [expenses, setExpenses] = useState<any[]>([]);
  const [project, setProject] = useState<any>(null);

  const fetchExpenses = async () => {
    try {
      setLoading(true);

      // Fetch project
      if (!project) {
        const { data: pData } = await supabase.from('projects').select('name, total_budget, spent_cost').eq('id', projectId).single();
        if (pData) setProject(pData);
      }

      const { data: sessionData } = await supabase.auth.getSession();
      const response = await fetch(`${process.env.EXPO_PUBLIC_API_URL}/projects/${projectId}/expenses`, {
        headers: {
          'Authorization': `Bearer ${sessionData.session?.access_token}`
        }
      });

      if (!response.ok) throw new Error("Failed to fetch expenses");
      const data = await response.json();
      setExpenses(data || []);
    } catch (err: any) {
      Alert.alert("Error fetching expenses", err.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (projectId) fetchExpenses();
  }, [projectId]);

  const totalSpent = expenses.reduce((sum, e) => sum + Number(e.amount), 0);

  return (
    <View className="flex-1 bg-brand-dark">
      <TopNav title={project ? `${project.name} Expenses` : 'Project Expenses'} showBackButton />

      <ScrollView className="flex-1 p-6">
        <View className="flex-row justify-between items-center mb-6">
          <View>
            <Text className="text-2xl font-bold text-white mb-1">Expenses Log</Text>
            <Text className="text-gray-400">Total Logged: Rs. {totalSpent.toLocaleString()}</Text>
          </View>
          <Pressable 
            onPress={() => router.push(`/admin/projects/${projectId}/expenses/create`)}
            className="bg-brand-orange px-4 py-2.5 rounded-xl flex-row items-center"
          >
            <Ionicons name="add" size={20} color="white" className="mr-2" />
            <Text className="text-white font-bold">Add Expense</Text>
          </Pressable>
        </View>

        {loading ? (
          <ActivityIndicator size="large" color="#F97316" className="mt-10" />
        ) : expenses.length === 0 ? (
          <View className="bg-white/5 rounded-2xl p-10 items-center justify-center mt-4 border border-white/10">
            <Ionicons name="receipt-outline" size={48} color="#9CA3AF" className="mb-4" />
            <Text className="text-white font-bold text-lg mb-2">No expenses logged yet</Text>
            <Text className="text-gray-400 text-center">Track your project costs by adding individual expenses here.</Text>
          </View>
        ) : (
          <View className="space-y-4">
            {expenses.map((expense) => (
              <View key={expense.id} className="bg-white rounded-2xl p-5 shadow-sm border border-gray-100 mb-4">
                <View className="flex-row justify-between items-start mb-2">
                  <View className="flex-1">
                    <Text className="font-bold text-lg text-gray-900">{expense.title}</Text>
                    <Text className="text-gray-500 text-xs mt-1">
                      {new Date(expense.expense_date).toLocaleDateString()}
                    </Text>
                  </View>
                  <View className="bg-red-50 px-3 py-1.5 rounded-lg border border-red-100">
                    <Text className="text-red-600 font-bold">
                      Rs. {Number(expense.amount).toLocaleString()}
                    </Text>
                  </View>
                </View>
                {expense.description ? (
                  <Text className="text-gray-600 text-sm mt-2">{expense.description}</Text>
                ) : null}
              </View>
            ))}
          </View>
        )}
      </ScrollView>
    </View>
  );
}

import React, { useState } from 'react';
import { View, Text, ScrollView, TextInput, TouchableOpacity, ActivityIndicator, Alert } from 'react-native';
import { useLocalSearchParams, useRouter } from 'expo-router';
import { TopNav } from '@/components/common/TopNav';
import { supabase } from '../../../../../lib/supabase';

export default function AdminMilestoneCreatePage() {
  const { id: projectId } = useLocalSearchParams();
  const router = useRouter();
  const [loading, setLoading] = useState(false);
  
  const [formData, setFormData] = useState({
    title: '',
    description: '',
    due_date: new Date(new Date().setMonth(new Date().getMonth() + 1)).toISOString().split('T')[0]
  });

  const handleSubmit = async () => {
    if (!formData.title || !formData.due_date) {
      alert('Title and Due Date are required');
      return;
    }
    
    setLoading(true);
    try {
      const { data: sessionData } = await supabase.auth.getSession();
      const token = sessionData.session?.access_token;
      
      const response = await fetch(`${process.env.EXPO_PUBLIC_API_URL}/projects/${projectId}/milestones`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify(formData)
      });
      
      if (!response.ok) {
        const err = await response.json();
        throw new Error(err.detail || 'Failed to create milestone');
      }
      
      alert('Milestone created successfully!');
      router.back();
    } catch (err: any) {
      alert(err.message || 'Error creating milestone');
    } finally {
      setLoading(false);
    }
  };

  return (
    <View className="flex-1 bg-brand-light">
      <TopNav title="Add New Milestone" showAction={false} />
      <ScrollView className="flex-1 p-6">
        <View className="bg-white rounded-2xl shadow-sm border border-gray-100 p-8 max-w-xl mx-auto w-full">
          <Text className="text-xl font-bold text-gray-800 mb-6">Milestone Details</Text>
          
          <View className="mb-4">
            <Text className="text-gray-700 font-medium mb-2">Title *</Text>
            <TextInput 
              className="bg-gray-50 border border-gray-200 rounded-lg px-4 py-3 text-gray-800"
              placeholder="e.g. Foundation Complete"
              value={formData.title}
              onChangeText={(t) => setFormData({...formData, title: t})}
            />
          </View>
          
          <View className="mb-4">
            <Text className="text-gray-700 font-medium mb-2">Description</Text>
            <TextInput 
              className="bg-gray-50 border border-gray-200 rounded-lg px-4 py-3 text-gray-800"
              placeholder="Detailed description..."
              multiline
              numberOfLines={4}
              value={formData.description}
              onChangeText={(t) => setFormData({...formData, description: t})}
            />
          </View>

          <View className="mb-8">
            <Text className="text-gray-700 font-medium mb-2">Target Date (YYYY-MM-DD) *</Text>
            <TextInput 
              className="bg-gray-50 border border-gray-200 rounded-lg px-4 py-3 text-gray-800"
              placeholder="2025-06-01"
              value={formData.due_date}
              onChangeText={(t) => setFormData({...formData, due_date: t})}
            />
          </View>

          <TouchableOpacity 
            onPress={handleSubmit}
            disabled={loading}
            className="bg-brand-orange py-4 rounded-xl items-center flex-row justify-center"
          >
            {loading ? <ActivityIndicator color="#fff" /> : <Text className="text-white font-bold text-lg">Add Milestone</Text>}
          </TouchableOpacity>
        </View>
      </ScrollView>
    </View>
  );
}

import React, { useEffect, useState } from 'react';
import { View, Text, ScrollView, ActivityIndicator, Pressable, Alert } from 'react-native';
import { useLocalSearchParams, useRouter } from 'expo-router';
import { supabase } from '../../../../../lib/supabase';
import { TopNav } from '@/components/common/TopNav';
import { Ionicons } from '@expo/vector-icons';

export default function AdminMilestonesIndexPage() {
  const { id: projectId } = useLocalSearchParams();
  const router = useRouter();
  const [loading, setLoading] = useState(true);
  const [milestones, setMilestones] = useState<any[]>([]);
  const [project, setProject] = useState<any>(null);

  const fetchMilestones = async () => {
    try {
      setLoading(true);
      
      // Fetch project name for header
      if (!project) {
        const { data: pData } = await supabase.from('projects').select('name').eq('id', projectId).single();
        if (pData) setProject(pData);
      }

      const { data, error } = await supabase
        .from('milestones')
        .select('*, milestone_media(*)')
        .eq('project_id', projectId)
        .order('due_date', { ascending: true });
        
      if (error) throw error;
      setMilestones(data || []);
    } catch (err: any) {
      Alert.alert("Error fetching milestones", err.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (projectId) fetchMilestones();
  }, [projectId]);

  const markComplete = async (milestoneId: string) => {
    try {
      const { data: sessionData } = await supabase.auth.getSession();
      const response = await fetch(`${process.env.EXPO_PUBLIC_API_URL}/projects/${projectId}/milestones/${milestoneId}`, {
        method: 'PATCH',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${sessionData.session?.access_token}`
        },
        body: JSON.stringify({ status: 'Completed' })
      });
      if (!response.ok) throw new Error("Failed to update milestone");
      
      fetchMilestones();
      Alert.alert("Success", "Milestone marked as complete!");
    } catch (err: any) {
      Alert.alert("Error", err.message);
    }
  };

  return (
    <View className="flex-1 bg-brand-light">
      <TopNav 
        title={project ? `${project.name} - Milestones` : "Project Milestones"} 
        actionLabel="+ Add Milestone" 
        onActionPress={() => router.push(`/admin/projects/${projectId}/milestones/create`)} 
      />
      
      <ScrollView className="flex-1 p-6">
        {loading ? (
          <View className="py-20 items-center justify-center">
            <ActivityIndicator size="large" color="#F97316" />
          </View>
        ) : (
          <View className="max-w-4xl mx-auto w-full">
            <View className="flex-row justify-between items-center mb-6">
              <Text className="text-2xl font-bold text-gray-800">Timeline Tracking</Text>
            </View>

            {milestones.length === 0 ? (
              <View className="bg-white rounded-2xl p-10 items-center justify-center border border-gray-100 shadow-sm">
                <Ionicons name="flag-outline" size={48} color="#D1D5DB" />
                <Text className="text-gray-400 mt-4 text-center font-medium">No milestones created for this project yet.</Text>
                <Pressable 
                  onPress={() => router.push(`/admin/projects/${projectId}/milestones/create`)}
                  className="mt-6 bg-brand-orange px-6 py-3 rounded-xl shadow-sm"
                >
                  <Text className="text-white font-bold">Create First Milestone</Text>
                </Pressable>
              </View>
            ) : (
              <View className="bg-white rounded-3xl shadow-sm border border-gray-100 p-8">
                {milestones.map((ms, idx) => (
                  <View key={ms.id} className={`flex-row ${idx !== milestones.length - 1 ? 'border-b border-gray-100 mb-6 pb-6' : ''}`}>
                    <View className="mr-6 items-center">
                      <View className={`w-11 h-11 rounded-full items-center justify-center ${ms.status === 'Completed' ? 'bg-green-100' : 'bg-orange-100'}`}>
                        <Ionicons name={ms.status === 'Completed' ? "checkmark" : "time"} size={20} color={ms.status === 'Completed' ? "#16A34A" : "#EA580C"} />
                      </View>
                      {idx !== milestones.length - 1 && (
                        <View className="w-0.5 h-full bg-gray-100 mt-2" />
                      )}
                    </View>
                    
                    <View className="flex-1 pt-1">
                      <View className="flex-row justify-between items-start">
                        <View className="flex-1 pr-4">
                          <Text className="text-xl font-bold text-gray-800">{ms.title}</Text>
                          <Text className="text-gray-500 text-sm mt-1 mb-3">{ms.description}</Text>
                        </View>
                        <View className={`px-3 py-1.5 rounded-lg ${ms.status === 'Completed' ? 'bg-[#DCFCE7]' : 'bg-orange-50'}`}>
                           <Text className={`text-xs font-bold uppercase tracking-wider ${ms.status === 'Completed' ? 'text-green-600' : 'text-orange-600'}`}>{ms.status}</Text>
                        </View>
                      </View>
                      
                      <View className="flex-row items-center justify-between mt-2 bg-gray-50 p-4 rounded-xl border border-gray-100">
                         <View className="flex-row items-center">
                           <Ionicons name="calendar-outline" size={16} color="#6B7280" className="mr-2" />
                           <Text className="text-sm font-bold text-gray-600">Target Date: {new Date(ms.due_date).toDateString()}</Text>
                         </View>
                         
                         {ms.status !== 'Completed' && (
                           <Pressable 
                             onPress={() => markComplete(ms.id)}
                             className="bg-[#DCFCE7] border border-[#BBF7D0] min-h-[44px] justify-center px-4 rounded-lg shadow-sm active:bg-[#BBF7D0]"
                           >
                             <Text className="text-[#15803D] text-sm font-bold">Mark Complete</Text>
                           </Pressable>
                         )}
                      </View>
                      
                      {/* Media Display */}
                      {ms.milestone_media && ms.milestone_media.length > 0 && (
                        <View className="flex-row flex-wrap mt-4">
                           {ms.milestone_media.map((media: any) => (
                              <View key={media.id} className="w-20 h-20 bg-gray-100 rounded-xl overflow-hidden mr-3 mb-3 border border-gray-200">
                                <View className="flex-1 items-center justify-center">
                                   <Ionicons name="image" size={28} color="#D1D5DB" />
                                </View>
                              </View>
                           ))}
                        </View>
                      )}
                    </View>
                  </View>
                ))}
              </View>
            )}
          </View>
        )}
      </ScrollView>
    </View>
  );
}

import React, { useState, useEffect } from 'react';
import { View, Text, ScrollView, TextInput, TouchableOpacity, ActivityIndicator, Alert } from 'react-native';
import { useRouter } from 'expo-router';
import { TopNav } from '@/components/common/TopNav';
import { supabase } from '../../../lib/supabase';
import { api } from '../../../services/api';
import { ProjectAssignmentDropdown } from '../../../components/common/ProjectAssignmentDropdown';

export default function AdminProjectsCreatePage() {
  const router = useRouter();
  const [loading, setLoading] = useState(false);
  const [pms, setPms] = useState<any[]>([]);
  const [clients, setClients] = useState<any[]>([]);
  const [siteManagers, setSiteManagers] = useState<any[]>([]);
  const [availableWorkers, setAvailableWorkers] = useState<any[]>([]);
  const [suppliers, setSuppliers] = useState<any[]>([]);
  const [admins, setAdmins] = useState<any[]>([]);
  
  const [formData, setFormData] = useState({
    name: '',
    location: '',
    address: '',
    status: 'Planning',
    start_date: new Date().toISOString().split('T')[0],
    end_date: new Date(new Date().setMonth(new Date().getMonth() + 6)).toISOString().split('T')[0],
    pm_id: '',
    client_id: '',
    site_managers: [] as string[],
    workers: [] as string[],
    suppliers: [] as string[],
    admins: [] as string[],
    latitude: '',
    longitude: ''
  });

  useEffect(() => {
    let isMounted = true;
    
    const fetchUsers = async () => {
      try {
        const { data: pmData } = await supabase.from('profiles').select('*').in('role', ['pm', 'Project Manager', 'project_manager']);
        const { data: clientData } = await supabase.from('profiles').select('*').in('role', ['client', 'Client']);
        const { data: smData } = await supabase.from('profiles').select('*').in('role', ['site_manager', 'Site Manager', 'site manager']);
        const { data: workerData } = await supabase.from('profiles').select('*').in('role', ['worker', 'Worker']);
        const { data: supplierData } = await supabase.from('profiles').select('*').in('role', ['supplier', 'Supplier']);
        const { data: adminData } = await supabase.from('profiles').select('*').in('role', ['admin', 'Admin', 'super_admin', 'Super Admin']);
        
        if (isMounted) {
          if (pmData) setPms(pmData);
          if (clientData) setClients(clientData);
          if (smData) setSiteManagers(smData);
          if (workerData) setAvailableWorkers(workerData);
          if (supplierData) setSuppliers(supplierData);
          if (adminData) setAdmins(adminData);
        }
      } catch (err) {
        console.error("Failed to fetch users", err);
      }
    };
    
    fetchUsers();
    return () => { isMounted = false; };
  }, []);

  const handleSubmit = async () => {
    if (!formData.name || !formData.location || !formData.start_date || !formData.end_date) {
      alert('Please fill out all required fields');
      return;
    }
    
    setLoading(true);
    try {
      const payload = {
        name: formData.name,
        location: formData.location,
        address: formData.address || null,
        status: formData.status,
        start_date: formData.start_date,
        end_date: formData.end_date,
        pm_id: formData.pm_id || null,
        client_id: formData.client_id || null,
        site_managers: formData.site_managers,
        workers: formData.workers,
        suppliers: formData.suppliers,
        admins: formData.admins,
        latitude: formData.latitude ? parseFloat(formData.latitude) : null,
        longitude: formData.longitude ? parseFloat(formData.longitude) : null,
      };
      
      const response = await fetch(`${process.env.EXPO_PUBLIC_API_URL}/projects`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${(await supabase.auth.getSession()).data.session?.access_token}`
        },
        body: JSON.stringify(payload)
      });
      
      if (!response.ok) {
        const err = await response.json();
        throw new Error(err.detail || 'Failed to create project');
      }
      
      const newProject = await response.json();
      
      Alert.alert('Success', 'Project created successfully!');
      router.push(`/admin/projects/${newProject.id}`);
    } catch (err: any) {
      Alert.alert('Error', err.message || 'Error creating project');
    } finally {
      setLoading(false);
    }
  };

  return (
    <View className="flex-1 bg-brand-light">
      <TopNav title="Create New Project" showAction={false} />
      <ScrollView className="flex-1 p-6">
        <View className="bg-white rounded-2xl shadow-sm border border-gray-100 p-8 max-w-3xl mx-auto w-full">
          
          <Text className="text-xl font-bold text-gray-800 mb-6">Project Details</Text>
          
          {/* Form Fields */}
          <View className="mb-4">
            <Text className="text-gray-700 font-medium mb-2">Project Name *</Text>
            <TextInput 
              className="bg-gray-50 border border-gray-200 rounded-lg px-4 py-3 text-gray-800"
              placeholder="e.g. Skyline Towers"
              value={formData.name}
              onChangeText={(t) => setFormData({...formData, name: t})}
            />
          </View>
          
          <View className="mb-4">
            <Text className="text-gray-700 font-medium mb-2">Short Location *</Text>
            <TextInput 
              className="bg-gray-50 border border-gray-200 rounded-lg px-4 py-3 text-gray-800"
              placeholder="e.g. Colombo 03"
              value={formData.location}
              onChangeText={(t) => setFormData({...formData, location: t})}
            />
          </View>
          
          <View className="mb-4">
            <Text className="text-gray-700 font-medium mb-2">Full Address</Text>
            <TextInput 
              className="bg-gray-50 border border-gray-200 rounded-lg px-4 py-3 text-gray-800"
              placeholder="e.g. 123 Galle Rd, Colombo"
              value={formData.address}
              onChangeText={(t) => setFormData({...formData, address: t})}
            />
          </View>

          <View className="flex-row space-x-4 mb-4">
            <View className="flex-1">
              <Text className="text-gray-700 font-medium mb-2">Start Date (YYYY-MM-DD) *</Text>
              <TextInput 
                className="bg-gray-50 border border-gray-200 rounded-lg px-4 py-3 text-gray-800"
                placeholder="2025-01-01"
                value={formData.start_date}
                onChangeText={(t) => setFormData({...formData, start_date: t})}
              />
            </View>
            <View className="flex-1">
              <Text className="text-gray-700 font-medium mb-2">End Date (YYYY-MM-DD) *</Text>
              <TextInput 
                className="bg-gray-50 border border-gray-200 rounded-lg px-4 py-3 text-gray-800"
                placeholder="2026-01-01"
                value={formData.end_date}
                onChangeText={(t) => setFormData({...formData, end_date: t})}
              />
            </View>
          </View>

          <Text className="text-xl font-bold text-gray-800 mb-6 mt-4">Assignments</Text>
          <ProjectAssignmentDropdown label="Assign Administrators" users={admins} multiple selectedIds={formData.admins} onChange={(admins) => setFormData({ ...formData, admins })} />
          <ProjectAssignmentDropdown label="Assign Project Manager" users={pms} selectedIds={formData.pm_id ? [formData.pm_id] : []} onChange={(ids) => setFormData({ ...formData, pm_id: ids[0] || '' })} />
          <ProjectAssignmentDropdown label="Assign Client" users={clients} selectedIds={formData.client_id ? [formData.client_id] : []} onChange={(ids) => setFormData({ ...formData, client_id: ids[0] || '' })} />
          <ProjectAssignmentDropdown label="Assign Site Managers" users={siteManagers} multiple selectedIds={formData.site_managers} onChange={(site_managers) => setFormData({ ...formData, site_managers })} />
          <ProjectAssignmentDropdown label="Assign Workers" users={availableWorkers} multiple selectedIds={formData.workers} onChange={(workers) => setFormData({ ...formData, workers })} />
          <ProjectAssignmentDropdown label="Assign Suppliers" users={suppliers} multiple selectedIds={formData.suppliers} onChange={(suppliers) => setFormData({ ...formData, suppliers })} />

          <TouchableOpacity 
            onPress={handleSubmit}
            disabled={loading}
            className="bg-brand-orange py-4 rounded-xl items-center flex-row justify-center"
          >
            {loading ? <ActivityIndicator color="#fff" /> : <Text className="text-white font-bold text-lg">Create Project</Text>}
          </TouchableOpacity>
          
        </View>
      </ScrollView>
    </View>
  );
}

import React, { useEffect, useState } from 'react';
import { View, Text, ScrollView, ActivityIndicator, Pressable, TextInput } from 'react-native';
import { useRouter, Link } from 'expo-router';
import { supabase } from '../../../lib/supabase';
import { TopNav } from '@/components/common/TopNav';
import { Ionicons } from '@expo/vector-icons';
import { GlobalSearchDropdown } from '@/components/common/GlobalSearchDropdown';
import { useDebounce } from '@/hooks/useDebounce';

import { useResponsive } from '../../../hooks/useResponsive';
import { formatMoney } from '../../../utils/format';

export default function AdminProjectsList() {
  const router = useRouter();
  const [projects, setProjects] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const { isMobile } = useResponsive();
  const debouncedSearch = useDebounce(search, 300);

  useEffect(() => {
    let isMounted = true;
    const fetchProjects = async () => {
      try {
        let query = supabase.from('projects').select('*').order('created_at', { ascending: false });
        if (debouncedSearch) {
          query = query.or(`name.ilike.%${debouncedSearch}%,location.ilike.%${debouncedSearch}%`);
        }
        const { data, error } = await query;
        if (error) throw error;
        
        if (data && data.length > 0) {
          // Collect unique user IDs for PMs and Clients
          const userIds = new Set<string>();
          data.forEach(p => {
            if (p.pm_id) userIds.add(p.pm_id);
            if (p.client_id) userIds.add(p.client_id);
          });
          
          if (userIds.size > 0) {
            const { data: profilesData } = await supabase
              .from('profiles')
              .select('id, full_name')
              .in('id', Array.from(userIds));
              
            if (profilesData) {
              const profileMap = Object.fromEntries(profilesData.map(p => [p.id, p.full_name]));
              data.forEach(p => {
                if (p.pm_id) p.pm_name = profileMap[p.pm_id];
                if (p.client_id) p.client_name = profileMap[p.client_id];
              });
            }
          }
        }
        
        if (isMounted) setProjects(data || []);
      } catch (err) {
        console.error('Error fetching projects', err);
      } finally {
        if (isMounted) setLoading(false);
      }
    };
    
    fetchProjects();

    const channel = supabase
      .channel('admin-projects-list')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'projects' }, () => {
        fetchProjects();
      })
      .subscribe();

    return () => { 
      isMounted = false; 
      supabase.removeChannel(channel);
    };
  }, [debouncedSearch]);

  return (
    <View className="flex-1 bg-gray-50">
      <View className="flex-1 flex-col min-h-0 overflow-hidden">
        <TopNav title="Projects" actionLabel="+ New Project" onActionPress={() => router.push('/admin/projects/create')} />
        
        <ScrollView className={`flex-1 ${isMobile ? 'px-4 py-4' : 'px-8 py-6'}`} showsVerticalScrollIndicator={false}>
          <View style={{ flexDirection: isMobile ? 'column' : 'row', justifyContent: isMobile ? 'flex-start' : 'space-between', alignItems: isMobile ? 'flex-start' : 'center', marginBottom: 24, gap: isMobile ? 12 : 0, zIndex: 50, elevation: 50 }}>
            <Text className="text-2xl font-bold text-brand-text">All Projects</Text>
            
            <GlobalSearchDropdown 
              placeholder="Search projects..." 
              value={search} 
              onChangeText={setSearch} 
              className={isMobile ? "w-full" : "w-64"}
              config={{
                table: 'projects',
                searchColumn: 'name',
                secondaryColumn: 'location',
                titleColumn: 'name',
                subtitleColumn: 'location',
                routePrefix: '/admin/projects/'
              }}
            />
          </View>
          
          <View className={`bg-white shadow-sm border border-gray-100 min-h-[400px] ${isMobile ? 'rounded-none border-0 bg-transparent shadow-none' : 'rounded-xl p-6'}`}>
            {!isMobile && (
              <View className="flex-row py-3 border-b border-gray-200 pr-2">
                <Text className="w-[25%] text-xs font-semibold text-gray-500 uppercase">Project Name</Text>
                <Text className="w-[15%] text-xs font-semibold text-gray-500 uppercase">Location</Text>
                <Text className="w-[15%] text-xs font-semibold text-gray-500 uppercase">Personnel</Text>
                <Text className="w-[15%] text-xs font-semibold text-gray-500 uppercase">Budget</Text>
                <Text className="w-[15%] text-xs font-semibold text-gray-500 uppercase">Status</Text>
                <Text className="flex-1 text-xs font-semibold text-gray-500 uppercase text-right">Action</Text>
              </View>
            )}

            {loading ? (
              <View className="py-20 items-center justify-center">
                <ActivityIndicator color="#F97316" />
              </View>
            ) : projects.length === 0 ? (
              <View className="py-20 items-center justify-center">
                <Ionicons name="folder-open-outline" size={48} color="#D1D5DB" className="mb-4" />
                <Text className="text-gray-400 text-lg font-medium">No projects found.</Text>
              </View>
            ) : isMobile ? (
              projects.map(p => (
                <View key={p.id} className="bg-white rounded-xl border border-gray-200 p-4 mb-4 shadow-sm">
                  <View className="flex-row items-center mb-3">
                    <View className="w-11 h-11 rounded-full bg-orange-50 items-center justify-center mr-3">
                      <Text className="text-brand-orange font-bold text-lg">{p.name.charAt(0).toUpperCase()}</Text>
                    </View>
                    <View className="flex-1">
                      <Text className="text-brand-text font-bold text-base" numberOfLines={1}>{p.name}</Text>
                      <Text className="text-gray-500 text-xs font-medium">{formatMoney(p.total_budget)}</Text>
                    </View>
                  </View>
                  <View className="flex-row items-center mb-4 pl-[52px]">
                    <View className="flex-row items-center flex-1">
                      <Ionicons name="location-outline" size={14} color="#6B7280" />
                      <Text className="text-gray-500 text-xs ml-1" numberOfLines={1}>{p.location || 'N/A'}</Text>
                    </View>
                    <View className={`px-2 py-1 rounded-full ${p.status === 'active' ? 'bg-[#DCFCE7]' : p.status === 'completed' ? 'bg-blue-100' : 'bg-gray-100'}`}>
                      <Text className={`text-[10px] font-bold uppercase ${p.status === 'active' ? 'text-brand-success' : p.status === 'completed' ? 'text-blue-600' : 'text-gray-500'}`}>
                        {p.status}
                      </Text>
                    </View>
                  </View>
                  <View className="flex-col mb-4 pl-[52px]">
                    <Text className="text-xs text-gray-500 mb-1"><Text className="font-semibold text-gray-700">PM:</Text> {p.pm_name || 'Unassigned'}</Text>
                    <Text className="text-xs text-gray-500"><Text className="font-semibold text-gray-700">Client:</Text> {p.client_name || 'Unassigned'}</Text>
                  </View>
                  <Link href={`/admin/projects/${p.id}` as any} asChild>
                    <Pressable className="bg-brand-orange py-3 rounded-lg items-center">
                      <Text className="text-white text-sm font-bold">View Details</Text>
