              ))
            ) : (
              projects.map(p => (
                <View key={p.id} className="flex-row items-center py-4 border-b border-gray-100">
                  <View className="w-[25%] flex-row items-center pr-4">
                    <View className="w-8 h-8 bg-orange-100 rounded items-center justify-center mr-3">
