                      <Pressable className="bg-brand-orange px-3 py-1.5 rounded-md shadow-sm">
                        <Text className="text-white text-xs font-bold">View Details</Text>
                      </Pressable>
                    </Link>
                  </View>
                </View>
              ))
            )}
          </View>
        </ScrollView>
      </View>
    </View>
  );
}

import React, { useEffect, useState } from 'react';
import { View, Text, ScrollView, ActivityIndicator, Pressable, TextInput } from 'react-native';
import { useRouter } from 'expo-router';
import { supabase } from '../../../lib/supabase';
import { TopNav } from '@/components/common/TopNav';
import { Ionicons, MaterialCommunityIcons } from '@expo/vector-icons';
import { format } from 'date-fns';
import { useResponsive } from '../../../hooks/useResponsive';
import { formatMoney } from '../../../utils/format';
import { GlobalSearchDropdown } from '@/components/common/GlobalSearchDropdown';
import { useDebounce } from '@/hooks/useDebounce';

export default function AdminSuppliersIndex() {
  const router = useRouter();
  const { isMobile } = useResponsive();
  const [suppliers, setSuppliers] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const debouncedSearch = useDebounce(search, 300);
  
  const [stats, setStats] = useState({ total: 0, activeOrders: 0, recentDeliveries: 0 });
  const [refreshTrigger, setRefreshTrigger] = useState(0);

  useEffect(() => {
    // Setup Realtime subscriptions
    const subProfiles = supabase.channel('admin-suppliers-profiles')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'profiles', filter: "role=eq.supplier" }, () => {
        setRefreshTrigger(prev => prev + 1);
      }).subscribe();
      
    const subOrders = supabase.channel('admin-suppliers-orders')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'purchase_orders' }, () => {
        setRefreshTrigger(prev => prev + 1);
      }).subscribe();

    return () => {
      supabase.removeChannel(subProfiles);
      supabase.removeChannel(subOrders);
    };
  }, []);

  useEffect(() => {
    let isMounted = true;
    const fetchData = async () => {
      try {
        // Fetch users with role 'supplier'
        const { data: sups, error: supErr } = await supabase
          .from('profiles')
          .select('id, full_name, role, created_at, email')
          .eq('role', 'supplier');
          
        if (supErr) throw supErr;
        
        // Fetch order stats for these suppliers
        const { data: orders, error: ordErr } = await supabase
          .from('purchase_orders')
          .select('id, supplier_id, status, total_price, created_at');
          
        if (ordErr) throw ordErr;
        
        const activeStatuses = ['Pending Delivery', 'Suggested', 'Confirmed'];
        const recentDeliveries = orders?.filter(o => o.status === 'Delivered' && new Date(o.created_at).getTime() > Date.now() - (7 * 24 * 60 * 60 * 1000)).length || 0;
        
        if (isMounted) {
          setStats({
            total: sups?.length || 0,
            activeOrders: orders?.filter(o => activeStatuses.includes(o.status)).length || 0,
            recentDeliveries
          });
          
          const enrichedSuppliers = sups?.map(s => {
            const supplierOrders = orders?.filter(o => o.supplier_id === s.id) || [];
            return {
              ...s,
              totalOrders: supplierOrders.length,
              activeOrders: supplierOrders.filter(o => activeStatuses.includes(o.status)).length,
              totalSpent: supplierOrders.filter(o => o.status === 'Delivered').reduce((sum, o) => sum + (o.total_price || 0), 0)
            };
          }) || [];
          
          setSuppliers(enrichedSuppliers);
        }
      } catch (err) {
        console.error('Error fetching suppliers', err);
      } finally {
        if (isMounted) setLoading(false);
      }
    };
    
    fetchData();
    return () => { isMounted = false; };
  }, [refreshTrigger]);

  const filteredSuppliers = suppliers.filter(s => {
    if (!debouncedSearch) return true;
    const searchLower = debouncedSearch.toLowerCase();
    return s.full_name?.toLowerCase().includes(searchLower) ||
           s.email?.toLowerCase().includes(searchLower);
  });

  return (
    <View className="flex-1 flex-col bg-gray-50">
      <TopNav title="Suppliers Directory" />
      
      <ScrollView className="flex-1 px-4 py-4 md:px-6 md:py-6 lg:px-8" showsVerticalScrollIndicator={false}>
        
        {/* Stat Cards */}
        <View style={{ flexDirection: isMobile ? 'column' : 'row', gap: 24, marginBottom: 32 }}>
          <View className="flex-1 bg-white p-6 rounded-xl border border-gray-100 shadow-sm flex-row items-center">
            <View className="w-12 h-12 bg-blue-50 rounded-full items-center justify-center mr-4">
              <Ionicons name="business" size={24} color="#3B82F6" />
            </View>
            <View>
              <Text className="text-3xl font-extrabold text-brand-text mb-1">{stats.total}</Text>
              <Text className="text-gray-500 font-semibold text-sm">Registered Suppliers</Text>
            </View>
          </View>
          
          <View className="flex-1 bg-white p-6 rounded-xl border border-gray-100 shadow-sm flex-row items-center">
            <View className="w-12 h-12 bg-orange-50 rounded-full items-center justify-center mr-4">
              <Ionicons name="cart" size={24} color="#F97316" />
            </View>
            <View>
              <Text className="text-3xl font-extrabold text-brand-text mb-1">{stats.activeOrders}</Text>
              <Text className="text-gray-500 font-semibold text-sm">Active Orders</Text>
            </View>
          </View>
          
          <View className="flex-1 bg-white p-6 rounded-xl border border-gray-100 shadow-sm flex-row items-center">
            <View className="w-12 h-12 bg-green-50 rounded-full items-center justify-center mr-4">
              <MaterialCommunityIcons name="truck-check" size={24} color="#10B981" />
            </View>
            <View>
              <Text className="text-3xl font-extrabold text-brand-text mb-1">{stats.recentDeliveries}</Text>
              <Text className="text-gray-500 font-semibold text-sm">Deliveries this Week</Text>
            </View>
          </View>
        </View>

        <View style={{ flexDirection: isMobile ? 'column' : 'row', justifyContent: isMobile ? 'flex-start' : 'space-between', alignItems: isMobile ? 'flex-start' : 'center', marginBottom: 24, gap: isMobile ? 12 : 0, zIndex: 50, elevation: 50 }}>
          <Text className="text-2xl font-bold text-brand-text">Supplier Database</Text>
          <GlobalSearchDropdown 
            placeholder="Search by name or email..." 
            value={search} 
            onChangeText={setSearch} 
            className={isMobile ? "w-full" : "w-64"}
            config={{
              table: 'profiles',
              searchColumn: 'full_name',
              secondaryColumn: 'email',
              titleColumn: 'full_name',
              subtitleColumn: 'email',
              routePrefix: '/admin/suppliers/',
              filterColumn: 'role',
              filterValue: 'supplier'
            }}
          />
        </View>

        <View className="bg-white rounded-xl shadow-sm border border-gray-100 p-6 min-h-[400px]">
          {!isMobile && (
            <View className="flex-row py-3 border-b border-gray-200 pr-2">
              <Text className="w-[30%] text-xs font-semibold text-gray-500 uppercase">Supplier Name</Text>
              <Text className="w-[20%] text-xs font-semibold text-gray-500 uppercase">Contact</Text>
              <Text className="w-[15%] text-xs font-semibold text-gray-500 uppercase text-center">Active Orders</Text>
              <Text className="w-[15%] text-xs font-semibold text-gray-500 uppercase text-right">Total Spent</Text>
              <Text className="flex-1 text-xs font-semibold text-gray-500 uppercase text-right">Action</Text>
            </View>
          )}

          {loading ? (
            <View className="py-20 items-center justify-center">
              <ActivityIndicator color="#F97316" />
            </View>
          ) : filteredSuppliers.length === 0 ? (
            <View className="py-20 items-center justify-center">
              <Ionicons name="people-outline" size={48} color="#D1D5DB" className="mb-4" />
              <Text className="text-gray-400 text-lg font-medium">No suppliers found.</Text>
            </View>
          ) : (
            filteredSuppliers.map((sup, idx) => (
              isMobile ? (
                <View key={sup.id} style={{ flexDirection: 'column', backgroundColor: '#fff', borderRadius: 12, padding: 16, marginBottom: 16, borderWidth: 1, borderColor: '#F3F4F6', shadowColor: '#000', shadowOffset: { width: 0, height: 1 }, shadowOpacity: 0.05, shadowRadius: 2 }}>
                  <View style={{ flexDirection: 'row', alignItems: 'center', marginBottom: 12 }}>
                    <View style={{ width: 40, height: 40, borderRadius: 20, backgroundColor: '#EFF6FF', alignItems: 'center', justifyContent: 'center', marginRight: 12 }}>
                      <Text style={{ color: '#1D4ED8', fontWeight: 'bold' }}>{sup.full_name?.charAt(0) || 'S'}</Text>
                    </View>
                    <View style={{ flex: 1 }}>
                      <Text style={{ color: '#111827', fontWeight: 'bold', fontSize: 16 }}>{sup.full_name || 'Unnamed'}</Text>
                      <Text style={{ color: '#6B7280', fontSize: 12 }}>{sup.email || 'No email provided'}</Text>
                    </View>
                  </View>
                  
                  <View style={{ flexDirection: 'row', justifyContent: 'space-between', marginBottom: 16 }}>
                    <View>
                      <Text style={{ color: '#9CA3AF', fontSize: 12, marginBottom: 4 }}>Active Orders</Text>
                      <View style={{ backgroundColor: sup.activeOrders > 0 ? '#FFEDD5' : '#F3F4F6', alignSelf: 'flex-start', paddingHorizontal: 8, paddingVertical: 4, borderRadius: 999 }}>
                        <Text style={{ fontSize: 12, fontWeight: 'bold', color: sup.activeOrders > 0 ? '#C2410C' : '#6B7280' }}>
                          {sup.activeOrders} Pending
                        </Text>
                      </View>
                    </View>
                    <View style={{ alignItems: 'flex-end' }}>
                      <Text style={{ color: '#9CA3AF', fontSize: 12, marginBottom: 4 }}>Total Spent</Text>
                      <Text style={{ color: '#111827', fontWeight: 'bold', fontSize: 14 }}>
                        {formatMoney(sup.totalSpent || 0)}
                      </Text>
                    </View>
                  </View>
                  
                  <Pressable 
                    onPress={() => router.push(`/admin/suppliers/${sup.id}/orders`)} 
                    style={{ backgroundColor: '#111827', paddingVertical: 10, borderRadius: 8, alignItems: 'center' }}
                  >
                    <Text style={{ color: '#fff', fontSize: 14, fontWeight: 'bold' }}>View Profile</Text>
                  </Pressable>
                </View>
              ) : (
                <View key={sup.id} className="flex-row items-center py-4 border-b border-gray-50">
                  <View className="w-[30%] pr-2 flex-row items-center">
                    <View className="w-11 h-11 rounded-full bg-blue-100 items-center justify-center mr-3">
                      <Text className="text-blue-700 font-bold">{sup.full_name?.charAt(0) || 'S'}</Text>
                    </View>
                    <View>
                      <Text className="text-brand-text font-bold text-sm truncate">{sup.full_name || 'Unnamed'}</Text>
                      <Text className="text-gray-400 text-[10px]">Joined {format(new Date(sup.created_at), 'MMM yyyy')}</Text>
                    </View>
                  </View>
                  
                  <View className="w-[20%] pr-2">
                    <Text className="text-gray-600 text-xs truncate">{sup.email || 'No email provided'}</Text>
                  </View>
  
                  <View className="w-[15%] flex-row justify-center">
                    <View className={`px-2 py-1 rounded-full ${sup.activeOrders > 0 ? 'bg-orange-100' : 'bg-gray-100'}`}>
                      <Text className={`text-xs font-bold ${sup.activeOrders > 0 ? 'text-orange-700' : 'text-gray-500'}`}>
                        {sup.activeOrders} Pending
                      </Text>
                    </View>
                  </View>
                  
                  <View className="w-[15%]">
                    <Text className="text-brand-text font-bold text-right text-sm">
                      {formatMoney(sup.totalSpent || 0)}
                    </Text>
                  </View>
                  
                  <View className="flex-1 flex-row justify-end pl-1">
                    <Pressable 
                      onPress={() => router.push(`/admin/suppliers/${sup.id}/orders`)} 
                      className="bg-brand-dark px-4 py-1.5 rounded-md shadow-sm hover:bg-gray-800"
                    >
                      <Text className="text-white text-xs font-bold">Profile</Text>
                    </Pressable>
                  </View>
                </View>
              )
            ))
          )}
        </View>
      </ScrollView>
    </View>
  );
}

import React, { useState } from 'react';
import { View, Text, ScrollView, TextInput, Pressable, ActivityIndicator, Alert } from 'react-native';
import { useRouter } from 'expo-router';
import { TopNav } from '@/components/common/TopNav';
import { supabase } from '@/lib/supabase';
import { createClient } from '@supabase/supabase-js';
import { Ionicons } from '@expo/vector-icons';

const ROLES = [
  { label: 'Admin', value: 'super_admin' },
  { label: 'Project Manager', value: 'pm' },
  { label: 'Site Manager', value: 'site_manager' },
  { label: 'Client', value: 'client' },
  { label: 'Worker', value: 'worker' },
  { label: 'Supplier', value: 'supplier' },
];

const WORKER_TYPES = ['Mason', 'Carpenter', 'Electrician', 'Plumber', 'General Laborer'];

export default function AdminUsersCreatePage() {
  const router = useRouter();
  const [loading, setLoading] = useState(false);

  const [fullName, setFullName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [selectedRole, setSelectedRole] = useState('pm');
  const [contactNumber, setContactNumber] = useState('');
  const [workerType, setWorkerType] = useState('General Laborer');
  const [dailyRate, setDailyRate] = useState('');

  const handleCreate = async () => {
    if (!fullName || !email || !password) {
      Alert.alert('Error', 'Name, email and password are required.');
      return;
    }
    if (password.length < 6) {
      Alert.alert('Error', 'Password must be at least 6 characters.');
      return;
    }
    if (password !== confirmPassword) {
      Alert.alert('Error', 'Passwords do not match.');
      return;
    }

    setLoading(true);
    try {
      const token = (await supabase.auth.getSession()).data.session?.access_token;
      
      const payload = {
        email: email.trim(),
        full_name: fullName.trim(),
        password,
        role: selectedRole,
        send_email: true,
        worker_type: selectedRole === 'worker' ? workerType : null,
        daily_rate: selectedRole === 'worker' ? (parseFloat(dailyRate) || 0) : null
      };

      const apiUrl = process.env.EXPO_PUBLIC_API_URL || 'http://localhost:8000/api';
      console.log('Sending request to:', `${apiUrl}/admin/users`);
      console.log('Payload:', payload);

      const response = await fetch(`${apiUrl}/admin/users`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify(payload)
      });

      console.log('Response status:', response.status);

      if (!response.ok) {
        let errorData = {};
        try {
          errorData = await response.json();
        } catch (e) {
          const text = await response.text();
          console.error('Failed to parse error JSON, text was:', text);
        }
        console.error('API Error Response:', errorData);
        throw new Error((errorData as any).detail || `Server returned ${response.status}`);
      }

      // Also update contact number since it's not in the main payload
      const responseData = await response.json();
      if (contactNumber) {
        await supabase
          .from('profiles')
          .update({ contact_number: contactNumber })
          .eq('id', responseData.id);
      }

      Alert.alert('Success', `${fullName} account created successfully! Credentials emailed.`);
      router.back();

    } catch (err: any) {
      console.error('Create User Error:', err);
      Alert.alert('Error', err.message || 'Something went wrong. Check console for details.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <View className="flex-1 bg-brand-light">
      <TopNav title="Create New User" showAction={false} />
      <ScrollView className="flex-1 p-6" showsVerticalScrollIndicator={false}>
        <View className="max-w-[600px] w-full mx-auto">

          {/* Basic Info */}
          <View className="bg-white rounded-2xl shadow-sm border border-gray-100 p-6 mb-4">
            <Text className="text-lg font-bold text-gray-800 mb-4">Basic Information</Text>

            <Text className="text-xs font-semibold text-gray-500 uppercase mb-1">Full Name</Text>
            <TextInput
              className="border border-gray-200 rounded-lg px-4 py-3 text-sm text-gray-800 mb-4 bg-gray-50"
              placeholder="Enter full name"
              value={fullName}
              onChangeText={setFullName}
            />

            <Text className="text-xs font-semibold text-gray-500 uppercase mb-1">Email</Text>
            <TextInput
              className="border border-gray-200 rounded-lg px-4 py-3 text-sm text-gray-800 mb-4 bg-gray-50"
              placeholder="Enter email address"
              value={email}
              onChangeText={setEmail}
              keyboardType="email-address"
              autoCapitalize="none"
            />

            <Text className="text-xs font-semibold text-gray-500 uppercase mb-1">Password</Text>
            <View className="flex-row items-center border border-gray-200 rounded-lg bg-gray-50 mb-4 pr-3">
              <TextInput
                className="flex-1 px-4 py-3 text-sm text-gray-800 outline-none"
                placeholder="Min 6 characters"
                value={password}
                onChangeText={setPassword}
                secureTextEntry={!showPassword}
              />
              <Pressable 
                onPress={() => setShowPassword(!showPassword)}
                className="p-2 min-w-[44px] min-h-[44px] items-center justify-center"
                accessibilityLabel={showPassword ? "Hide password" : "Show password"}
              >
                <Ionicons name={showPassword ? 'eye-off' : 'eye'} size={20} color="#9CA3AF" />
              </Pressable>
            </View>

            <Text className="text-xs font-semibold text-gray-500 uppercase mb-1">Confirm Password</Text>
            <View className="flex-row items-center border border-gray-200 rounded-lg bg-gray-50 mb-4 pr-3">
              <TextInput
                className="flex-1 px-4 py-3 text-sm text-gray-800 outline-none"
                placeholder="Repeat password"
                value={confirmPassword}
                onChangeText={setConfirmPassword}
                secureTextEntry={!showConfirmPassword}
              />
              <Pressable 
                onPress={() => setShowConfirmPassword(!showConfirmPassword)}
                className="p-2 min-w-[44px] min-h-[44px] items-center justify-center"
                accessibilityLabel={showConfirmPassword ? "Hide password" : "Show password"}
              >
                <Ionicons name={showConfirmPassword ? 'eye-off' : 'eye'} size={20} color="#9CA3AF" />
              </Pressable>
            </View>

            <Text className="text-xs font-semibold text-gray-500 uppercase mb-1">Contact Number</Text>
            <TextInput
              className="border border-gray-200 rounded-lg px-4 py-3 text-sm text-gray-800 bg-gray-50"
              placeholder="Enter contact number (optional)"
              value={contactNumber}
              onChangeText={setContactNumber}
              keyboardType="phone-pad"
            />
          </View>

          {/* Role Selection */}
          <View className="bg-white rounded-2xl shadow-sm border border-gray-100 p-6 mb-4">
            <Text className="text-lg font-bold text-gray-800 mb-4">Assign Role</Text>
            <View className="flex-row flex-wrap gap-2">
              {ROLES.map(role => (
                <Pressable
                  key={role.value}
                  onPress={() => setSelectedRole(role.value)}
                  className={`px-4 py-2 rounded-lg border ${
                    selectedRole === role.value
                      ? 'bg-brand-orange border-brand-orange'
                      : 'bg-white border-gray-200'
                  }`}
                >
                  <Text className={`text-sm font-semibold ${
                    selectedRole === role.value ? 'text-white' : 'text-gray-600'
                  }`}>
                    {role.label}
                  </Text>
                </Pressable>
              ))}
            </View>
          </View>

          {/* Worker Specific Fields */}
          {selectedRole === 'worker' && (
            <View className="bg-white rounded-2xl shadow-sm border border-gray-100 p-6 mb-4">
              <Text className="text-lg font-bold text-gray-800 mb-4">Worker Details</Text>

              <Text className="text-xs font-semibold text-gray-500 uppercase mb-2">Worker Type</Text>
              <View className="flex-row flex-wrap gap-2 mb-4">
                {WORKER_TYPES.map(type => (
                  <Pressable
                    key={type}
                    onPress={() => setWorkerType(type)}
                    className={`px-3 py-2 rounded-lg border ${
                      workerType === type
                        ? 'bg-brand-orange border-brand-orange'
                        : 'bg-white border-gray-200'
                    }`}
                  >
                    <Text className={`text-xs font-semibold ${
                      workerType === type ? 'text-white' : 'text-gray-600'
                    }`}>
                      {type}
                    </Text>
                  </Pressable>
                ))}
              </View>

              <Text className="text-xs font-semibold text-gray-500 uppercase mb-1">Daily Rate (LKR)</Text>
              <TextInput
                className="border border-gray-200 rounded-lg px-4 py-3 text-sm text-gray-800 bg-gray-50"
                placeholder="e.g. 2500"
                value={dailyRate}
                onChangeText={setDailyRate}
                keyboardType="numeric"
              />
            </View>
          )}

          {/* Submit */}
          <Pressable
            onPress={handleCreate}
            disabled={loading}
            className="bg-brand-orange rounded-xl py-4 items-center mb-8 shadow-sm"
          >
            {loading
              ? <ActivityIndicator color="white" />
              : <Text className="text-white font-bold text-base">Create User</Text>
            }
          </Pressable>
        
        </View>
      </ScrollView>
    </View>
  );
}

import React, { useEffect, useState } from 'react';
import { View, Text, ScrollView, ActivityIndicator, Pressable, TextInput } from 'react-native';
import { useRouter } from 'expo-router';
import { supabase } from '../../../lib/supabase';
import { TopNav } from '@/components/common/TopNav';
import { Ionicons } from '@expo/vector-icons';
import { GlobalSearchDropdown } from '@/components/common/GlobalSearchDropdown';
import { useDebounce } from '@/hooks/useDebounce';
import { useResponsive } from '../../../hooks/useResponsive';

export default function AdminUsersList() {
  const router = useRouter();
  const [users, setUsers] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [roleFilter, setRoleFilter] = useState('All');
  const [refreshTrigger, setRefreshTrigger] = useState(0);
  const { isMobile } = useResponsive();
  const debouncedSearch = useDebounce(search, 300);

  useEffect(() => {
    // @ts-ignore
    const sub = supabase.channel('profiles-changes')
      // @ts-ignore
      .on('postgres_changes', { event: '*', schema: 'public', table: 'profiles' }, () => {
         setRefreshTrigger(prev => prev + 1);
      })
      .subscribe();
    return () => { supabase.removeChannel(sub as any); };
  }, []);

  useEffect(() => {
    let isMounted = true;
    const fetchUsers = async () => {
      try {
        let query = supabase.from('profiles').select('*').order('created_at', { ascending: false });
        
        if (debouncedSearch) {
          query = query.or(`full_name.ilike.%${debouncedSearch}%,email.ilike.%${debouncedSearch}%`);
        }
        
        if (roleFilter !== 'All') {
          query = query.eq('role', roleFilter);
        }

        const { data, error } = await query;
        if (error) throw error;
        if (isMounted) setUsers(data || []);
      } catch (err) {
        console.error('Error fetching users', err);
      } finally {
        if (isMounted) setLoading(false);
      }
    };
    
    fetchUsers();
    return () => { isMounted = false; };
  }, [debouncedSearch, roleFilter, refreshTrigger]);

  const roles = ['All', 'admin', 'pm', 'site_manager', 'client', 'supplier', 'worker'];
  
  const formatRoleDisplay = (role: string) => {
    if (role === 'All') return 'All';
    if (role === 'admin') return 'Admin';
    if (role === 'pm') return 'Project Manager';
    if (role === 'site_manager') return 'Site Manager';
    return role.charAt(0).toUpperCase() + role.slice(1);
  };

  const getRoleColor = (role: string) => {
    if (role === 'admin') return { bg: 'bg-red-50', text: 'text-red-700' };
    if (role === 'pm') return { bg: 'bg-purple-50', text: 'text-purple-700' };
    if (role === 'site_manager') return { bg: 'bg-blue-50', text: 'text-blue-700' };
    if (role === 'worker') return { bg: 'bg-orange-50', text: 'text-orange-700' };
    if (role === 'client') return { bg: 'bg-emerald-50', text: 'text-emerald-700' };
    if (role === 'supplier') return { bg: 'bg-pink-50', text: 'text-pink-700' };
    return { bg: 'bg-gray-100', text: 'text-gray-700' };
  };

  return (
    <View className="flex-1 bg-gray-50">
      <View className="flex-1 flex-col min-h-0 overflow-hidden">
        <TopNav title="Users Directory" actionLabel="+ New User" onActionPress={() => router.push('/admin/users/create')} />
        
        <ScrollView className={`flex-1 ${isMobile ? 'px-4 py-4' : 'px-8 py-6'}`} showsVerticalScrollIndicator={false}>
          <View style={{ flexDirection: 'column', marginBottom: 24, gap: 16, zIndex: 50, elevation: 50 }}>
            <Text className="text-2xl font-bold text-brand-text">All Users</Text>
            
            <GlobalSearchDropdown 
              placeholder="Search users..." 
              value={search} 
              onChangeText={setSearch} 
              className={isMobile ? "w-full" : "w-64"}
              config={{
                table: 'profiles',
                searchColumn: 'full_name',
                secondaryColumn: 'email',
                titleColumn: 'full_name',
                subtitleColumn: 'email',
                routePrefix: '/admin/users/'
              }}
            />

            <ScrollView horizontal showsHorizontalScrollIndicator={false} className={isMobile ? "pb-2" : "pb-2 max-w-[700px]"} contentContainerStyle={{ gap: 8 }}>
              {roles.map(role => (
                <Pressable 
                  key={role}
                  onPress={() => setRoleFilter(role)}
                  className={`px-4 py-2 rounded-full border ${roleFilter === role ? 'bg-brand-orange border-brand-orange' : 'bg-white border-gray-200'}`}
                >
                  <Text className={`font-semibold text-sm ${roleFilter === role ? 'text-white' : 'text-gray-600'}`}>
                    {formatRoleDisplay(role)}
                  </Text>
                </Pressable>
              ))}
            </ScrollView>
          </View>
          
          <View className={`bg-white shadow-sm border border-gray-100 min-h-[400px] ${isMobile ? 'rounded-none border-0 bg-transparent shadow-none' : 'rounded-xl p-6'}`}>
            {!isMobile && (
              <View className="flex-row py-3 border-b border-gray-200 pr-2">
                <Text className="w-[30%] text-xs font-semibold text-gray-500 uppercase">User</Text>
                <Text className="w-[20%] text-xs font-semibold text-gray-500 uppercase">Role</Text>
                <Text className="w-[25%] text-xs font-semibold text-gray-500 uppercase">Contact</Text>
                <Text className="w-[15%] text-xs font-semibold text-gray-500 uppercase">Status</Text>
                <Text className="flex-1 text-xs font-semibold text-gray-500 uppercase text-right">Action</Text>
              </View>
            )}

            {loading ? (
              <View className="py-20 items-center justify-center">
                <ActivityIndicator color="#F97316" />
              </View>
            ) : users.length === 0 ? (
              <View className="py-20 items-center justify-center">
                <Ionicons name="people-outline" size={48} color="#D1D5DB" className="mb-4" />
                <Text className="text-gray-400 text-lg font-medium">No users found.</Text>
              </View>
            ) : isMobile ? (
              users.map(u => {
                const colors = getRoleColor(u.role);
                return (
                  <View key={u.id} className="bg-white rounded-xl border border-gray-200 p-4 mb-4 shadow-sm">
                    <View className="flex-row items-center mb-3">
                      <View className="w-11 h-11 rounded-full bg-indigo-50 items-center justify-center mr-3">
                        <Text className="text-indigo-600 font-bold text-lg">{u.full_name?.charAt(0) || '?'}</Text>
                      </View>
                      <View className="flex-1">
                        <Text className="text-brand-text font-bold text-base" numberOfLines={1}>{u.full_name || 'Unnamed User'}</Text>
                        <Text className="text-gray-500 text-xs font-medium">{u.email}</Text>
                      </View>
                      <View className={`px-3 py-1 rounded-full ${colors.bg}`}>
                        <Text className={`text-[10px] font-bold uppercase ${colors.text}`}>
                          {formatRoleDisplay(u.role)}
                        </Text>
                      </View>
                    </View>
                    <View className="flex-row items-center mb-4 pl-[52px]">
                      <Ionicons name="call-outline" size={14} color="#6B7280" />
                      <Text className="text-gray-500 text-xs ml-2">{u.phone || 'No phone'}</Text>
                    </View>
                    <Pressable 
                      // @ts-ignore
                      onPress={() => router.push(`/admin/users/${u.id}`)} 
                      className="bg-gray-50 border border-gray-200 py-2.5 rounded-lg items-center"
                    >
                      <Text className="text-gray-700 text-sm font-semibold">Edit User</Text>
                    </Pressable>
                  </View>
                );
              })
            ) : (
              users.map(u => (
                <View key={u.id} className="flex-row items-center py-4 border-b border-gray-100">
                  <View className="w-[30%] flex-row items-center pr-4">
                    <View className="w-8 h-8 bg-indigo-100 rounded-full items-center justify-center mr-3">
                      <Text className="text-indigo-600 font-bold text-xs">{u.full_name?.charAt(0) || '?'}</Text>
                    </View>
                    <View>
                      <Text className="text-brand-text font-semibold text-sm truncate">{u.full_name || 'Unnamed User'}</Text>
                      <Text className="text-gray-400 text-[10px]">ID: {u.id.slice(0, 8)}...</Text>
                    </View>
                  </View>
                  
                  <View className="w-[20%] pr-2">
                    <View className={`px-2 py-1 rounded self-start ${getRoleColor(u.role).bg}`}>
                      <Text className={`text-xs font-bold ${getRoleColor(u.role).text}`}>{formatRoleDisplay(u.role)}</Text>
                    </View>
                  </View>
                  
                  <View className="w-[25%]">
                    <Text className="text-gray-500 text-xs truncate">{u.email || u.phone || 'Database Linked'}</Text>
                  </View>
                  
                  <View className="w-[15%]">
                    <Text className="text-green-500 text-xs font-bold">Active</Text>
                  </View>
                  
                  <View className="flex-1 flex-row justify-end pl-1">
                    <Pressable 
                      // @ts-ignore
                      onPress={() => router.push(`/admin/users/${u.id}`)} 
                      className="bg-gray-100 px-3 py-1.5 rounded-md hover:bg-gray-200"
                    >
                      <Text className="text-brand-text text-xs font-semibold">Manage</Text>
                    </Pressable>
                  </View>
                </View>
              ))
            )}
          </View>
        </ScrollView>
      </View>
    </View>
  );
}

import { firstRelation } from '@/utils/relations';
import React, { useEffect, useState, useCallback } from 'react';
import { View, Text, ScrollView, ActivityIndicator, Pressable, Image } from 'react-native';
import { TopNav } from '@/components/common/TopNav';
import { Ionicons } from '@expo/vector-icons';
import { useLocalSearchParams } from 'expo-router';
import { supabase } from '../../../../lib/supabase';

type SiteReport = {
  id: string;
  project_id: string;
  date: string;
  work_completed: string;
  workers_present_count: number | null;
  blockers: string | null;
  photos: string[] | null;
  created_at: string;
  site_manager?: { full_name: string; avatar_url: string | null };
};

export default function ClientProjectSiteReports() {
  const { id: projectId } = useLocalSearchParams<{ id: string }>();
  const [loading, setLoading] = useState(true);
  const [reports, setReports] = useState<SiteReport[]>([]);

  const loadData = useCallback(async () => {
    if (!projectId) return;
    try {
      setLoading(true);
      const { data: reportsData } = await supabase
        .from('site_reports')
        .select(`
          id, project_id, date, work_completed, workers_present_count, blockers, photos, created_at,
          site_manager:profiles!site_manager_id(full_name, avatar_url)
        `)
        .eq('project_id', projectId)
        .order('date', { ascending: false });
      setReports((reportsData || []).map(report => ({ ...report, site_manager: firstRelation(report.site_manager) })));
    } catch (error) {
      console.error('Failed to load site reports:', error);
    } finally {
      setLoading(false);
    }
  }, [projectId]);

  useEffect(() => { loadData(); }, [loadData]);

  // Realtime: refresh when a new report is submitted.
  useEffect(() => {
    if (!projectId) return;
    const channel = supabase
      .channel(`client-site-reports:${projectId}`)
      .on('postgres_changes', {
        event: 'INSERT',
        schema: 'public',
        table: 'site_reports',
        filter: `project_id=eq.${projectId}`,
      }, () => loadData())
      .subscribe();
    return () => { supabase.removeChannel(channel); };
  }, [projectId, loadData]);

  const formatDate = (dateStr: string) =>
    new Date(dateStr).toLocaleDateString('en-LK', { weekday: 'short', year: 'numeric', month: 'short', day: 'numeric' });

  return (
    <View className="flex-1 bg-brand-light">
      <TopNav title="Daily Site Reports" showAction={false} />

      <ScrollView className="flex-1 p-6" showsVerticalScrollIndicator={false}>
        <Text className="text-2xl font-bold text-gray-800 mb-6">Site Reports History</Text>
        
        {loading ? (
          <View className="py-10 items-center justify-center">
            <ActivityIndicator color="#F97316" size="large" />
          </View>
        ) : reports.length === 0 ? (
          <View className="bg-white border border-gray-100 rounded-2xl p-10 items-center justify-center">
            <Ionicons name="document-text-outline" size={48} color="#D1D5DB" />
            <Text className="text-gray-400 font-bold mt-4 text-center">No reports yet</Text>
            <Text className="text-gray-400 text-sm mt-2 text-center">Your site manager hasn&apos;t submitted any daily reports.</Text>
          </View>
        ) : (
          reports.map(report => (
            <View key={report.id} className="bg-white border border-gray-100 rounded-2xl p-6 mb-6 shadow-sm">
              <View className="flex-row justify-between items-start border-b border-gray-50 pb-4 mb-4">
                <View>
                  <Text className="text-gray-800 font-bold text-lg">{formatDate(report.date)}</Text>
                  {report.site_manager && (
                    <Text className="text-gray-500 mt-1 text-xs">Submitted by: {report.site_manager.full_name}</Text>
                  )}
                </View>
                {report.workers_present_count !== null && (
                  <View className="bg-orange-50 px-3 py-1.5 rounded-lg flex-row items-center">
                    <Ionicons name="people" size={14} color="#F97316" />
                    <Text className="text-brand-orange font-bold text-xs ml-1.5">{report.workers_present_count} Workers</Text>
                  </View>
                )}
              </View>

              <View className="mb-4">
                <Text className="text-gray-400 text-xs font-bold uppercase mb-2 tracking-wider">Work Completed</Text>
                <Text className="text-gray-700 leading-relaxed">{report.work_completed}</Text>
              </View>

              {report.blockers ? (
                <View className="bg-red-50 p-4 rounded-xl border border-red-100 mb-4 flex-row">
                  <Ionicons name="warning" size={16} color="#DC2626" className="mt-0.5 mr-2" />
                  <View className="flex-1">
                    <Text className="text-red-800 font-bold text-xs uppercase mb-1">Blockers / Issues</Text>
                    <Text className="text-red-700 text-sm leading-relaxed">{report.blockers}</Text>
                  </View>
                </View>
              ) : null}

              {report.photos && report.photos.length > 0 && (
                <View>
                  <Text className="text-gray-400 text-xs font-bold uppercase mb-2 tracking-wider">Attachments</Text>
                  <ScrollView horizontal showsHorizontalScrollIndicator={false} className="flex-row">
                    {report.photos.map((photo, index) => (
                      <View key={index} className="w-24 h-24 mr-3 bg-gray-100 rounded-xl overflow-hidden border border-gray-200">
                        <Image source={{ uri: photo }} className="w-full h-full" resizeMode="cover" />
                      </View>
                    ))}
                  </ScrollView>
                </View>
              )}
            </View>
          ))
        )}
      </ScrollView>
    </View>
  );
}

import AuthPageLayout from '../components/auth/AuthPageLayout';
import React, { useState } from 'react';
import { View, Text, TextInput, Pressable, ActivityIndicator, Image } from 'react-native';
import { Link, useRouter } from 'expo-router';
import { supabase } from '../lib/supabase';
import { MaterialIcons, Ionicons } from '@expo/vector-icons';

export default function ForgotPasswordScreen() {
  const [email, setEmail] = useState('');
  const [loading, setLoading] = useState(false);
  const [errorMsg, setErrorMsg] = useState('');
  const [successMsg, setSuccessMsg] = useState('');
  const router = useRouter();

  const handleResetPassword = async () => {
    if (!email) {
      setErrorMsg('Please enter your email address');
      return;
    }

    setLoading(true);
    setErrorMsg('');
    setSuccessMsg('');

    const redirectTo = typeof window !== 'undefined'
      ? `${window.location.origin}/reset-password`
      : undefined;

    const { error } = await supabase.auth.resetPasswordForEmail(email, { redirectTo });

    if (error) {
      setErrorMsg(error.message);
    } else {
      setSuccessMsg('A password reset link has been sent to your email.');
    }
    setLoading(false);
  };

  return (
    <AuthPageLayout hero={
      <View className="w-1/2 py-12 bg-brand-dark relative overflow-hidden items-center justify-center">
        {/* Background Image with Overlay */}
        <Image 
          source={{ uri: 'https://images.unsplash.com/photo-1504307651254-35680f356dfd?q=80&w=1200' }} 
          className="absolute w-full h-full opacity-20"
          resizeMode="cover"
        />
        <View className="absolute inset-0 bg-brand-dark/90" />
        
        {/* Abstract Shapes */}
        <View className="absolute -top-32 -right-32 w-96 h-96 bg-brand-orange/20 rounded-full blur-3xl" />
        <View className="absolute -bottom-32 -left-32 w-96 h-96 bg-blue-500/10 rounded-full blur-3xl" />

        <View className="z-10 w-full px-8 xl:px-16 max-w-xl">
          <View className="w-16 h-16 bg-brand-orange/20 rounded-2xl items-center justify-center mb-8 border border-brand-orange/30">
            <Ionicons name="lock-closed" size={32} color="#F97316" />
          </View>
          <Text className="text-brand-orange font-bold tracking-widest text-sm uppercase mb-4">Secure Recovery</Text>
          <Text className="text-white font-extrabold text-5xl leading-tight mb-6">Regain access to your workspace.</Text>
          <Text className="text-gray-400 text-lg leading-relaxed mb-12">Your data is secured with enterprise-grade encryption. Once verified, you can quickly get back to managing your projects and team.</Text>
        </View>
      </View>
    }>
          <View className="items-center mb-10">
            {/* ── Construct Ai Logo ── */}
            <Pressable
              onPress={() => router.push('/')}
              style={{ alignSelf: 'flex-start', width: '100%', maxWidth: 280, marginBottom: 24 }}
            >
              <Image 
                source={require('../../assets/images/main-logo.png')} 
                style={{ width: '100%', aspectRatio: 4 }} 
                resizeMode="contain" 
              />
            </Pressable>
            <View className="w-full">
              <Text className="text-3xl md:text-4xl font-extrabold text-brand-text mb-2">Reset Password</Text>
              <Text className="text-gray-500 text-base leading-relaxed">Enter your email address and we&apos;ll send you a secure link to reset your password.</Text>
            </View>
          </View>

          {errorMsg ? (
            <View className="bg-red-50 p-3 rounded-lg border border-red-200 mb-6">
              <Text className="text-red-600 text-sm text-center">{errorMsg}</Text>
            </View>
          ) : null}

          {successMsg ? (
            <View className="bg-green-50 p-4 rounded-lg border border-green-200 mb-6">
              <Text className="text-green-700 text-sm text-center font-medium">{successMsg}</Text>
            </View>
          ) : null}

          <View className="mb-8">
            <Text className="text-sm font-semibold text-gray-700 mb-2">Email Address</Text>
            <TextInput
              className="w-full border border-gray-300 rounded-xl p-4 text-brand-text bg-gray-50 focus:border-brand-orange focus:bg-white transition-colors"
              placeholder="name@company.com"
              value={email}
              onChangeText={setEmail}
              autoCapitalize="none"
              keyboardType="email-address"
            />
          </View>

          <Pressable 
            onPress={handleResetPassword}
            disabled={loading || !!successMsg}
            className={`w-full bg-brand-orange py-4 rounded-xl items-center justify-center shadow-md hover:bg-orange-600 transition-colors mb-8 ${loading || !!successMsg ? 'opacity-70' : ''}`}
          >
            {loading ? (
              <ActivityIndicator color="white" />
            ) : (
              <Text className="text-white font-bold text-lg">Send Reset Link</Text>
            )}
          </Pressable>

          <View className="flex-row flex-wrap justify-center">
            <Text className="text-gray-500">Remember your password? </Text>
            <Link href="/login" asChild>
              <Pressable>
                <Text className="text-brand-orange font-bold hover:underline">Back to Login</Text>
              </Pressable>
            </Link>
          </View>
    </AuthPageLayout>
  );
}

/**
 * ConstructAi — Home / Landing Page (rewritten)
 *
 * SCROLL-DRIVEN VIDEO BACKGROUND
 * ─────────────────────────────────
 * injectVideoBackground() (web-only, called in useEffect) creates a fixed
 * <video> element behind all content and drives it with a requestAnimationFrame
 * loop that maps scroll progress (0→1) to video.currentTime (0→duration).
 * Lerp easing (LERP_FACTOR) makes forward and reverse scrubbing feel smooth.
 *
 * TUNEABLE constants at the top of this file:
 *   BLUR          — video layer backdrop blur        (default "10px")
 *   DIM           — dark overlay opacity, 0–1        (default "0.45")
 *   SCROLL_LENGTH — scroll height for one full orbit (default "600vh")
 *   LERP_FACTOR   — easing smoothness, lower=smoother (default 0.10)
 *
 * VIDEO ASSET
 * ───────────
 * Place homepage.mp4 (or homepage_scroll.mp4) at:
 *   frontend/assets/images/homepage.mp4
 *
 * For smooth reverse scrubbing, re-encode with ffmpeg (all-keyframe):
 *   ffmpeg -i homepage.mp4 -c:v libx264 -g 1 -crf 23 -an
 *          -movflags +faststart -vf "scale=1920:-2" homepage_scroll.mp4
 *
 * ffmpeg install on Windows (if missing):
 *   winget install Gyan.FFmpeg
 */

