import React, { useState, useEffect } from 'react';
import { View, Text, TextInput, Pressable, ActivityIndicator, Image } from 'react-native';
import { Link, useRouter, useLocalSearchParams } from 'expo-router';
import { supabase } from '../lib/supabase';
import AuthPageLayout from '../components/auth/AuthPageLayout';
import { MaterialIcons, Ionicons } from '@expo/vector-icons';
import AsyncStorage from '@react-native-async-storage/async-storage';


const REMEMBER_EMAIL_KEY = 'cf_remember_email';

export default function LoginScreen() {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [errorMsg, setErrorMsg] = useState('');
  const [rememberMe, setRememberMe] = useState(false);
  const router = useRouter();
  const { error: portalError } = useLocalSearchParams<{ error?: string }>();

  // Show error passed via URL (e.g. wrong portal)
  useEffect(() => {
    if (portalError === 'wrong_portal') {
      setErrorMsg('This portal is for partners only. Team members must use the Team Portal.');
    }
  }, [portalError]);

  useEffect(() => {
    const restoreEmail = async () => {
      try {
        const saved = await AsyncStorage.getItem(REMEMBER_EMAIL_KEY);
        if (saved) {
          setEmail(saved);
          setRememberMe(true);
        }
      } catch {
        // ignore restore failures
      }
    };
    restoreEmail();
  }, []);

  const handleLogin = async () => {
    if (!email || !password || !confirmPassword) {
      setErrorMsg('Please fill in all fields');
      return;
    }
    if (password !== confirmPassword) {
      setErrorMsg('Passwords do not match');
      return;
    }

    setLoading(true);
    setErrorMsg('');

    const { data, error } = await supabase.auth.signInWithPassword({ email, password });

    if (error) {
      setErrorMsg(error.message);
      setLoading(false);
      return;
    }

    // Handle Remember Me persistence
    try {
      if (rememberMe) {
        await AsyncStorage.setItem(REMEMBER_EMAIL_KEY, email);
      } else {
        await AsyncStorage.removeItem(REMEMBER_EMAIL_KEY);
      }
    } catch {
      // ignore persistence issues
    }

    // Auth succeeded — _layout.tsx enforces portal rules and routes to dashboard.
    // Keep loading so the user sees a spinner until _layout.tsx redirects.

  };

  const handleGoogleAuth = async () => {
    try {
      const { error } = await supabase.auth.signInWithOAuth({
        provider: 'google',
      });
      if (error) throw error;
    } catch (error: any) {
      setErrorMsg(error.message);
    }
  };

  return (
    <AuthPageLayout hero={
      <View className="bg-brand-dark relative overflow-hidden items-center justify-center"
        style={{ width: '50%', flexShrink: 0, paddingVertical: 48 }}>
        {/* Background Image with Overlay */}
        <Image
          source={{ uri: 'https://images.unsplash.com/photo-1541888086925-ebbc14b62db4?q=80&w=1200' }}
          className="absolute w-full h-full opacity-20"
          resizeMode="cover"
        />
        <View className="absolute inset-0 bg-brand-dark/90" />

        {/* Abstract Shapes */}
        <View className="absolute -top-32 -right-32 w-96 h-96 bg-brand-orange/20 rounded-full blur-3xl" />
        <View className="absolute -bottom-32 -left-32 w-96 h-96 bg-blue-500/10 rounded-full blur-3xl" />

        <View className="z-10 w-full px-8 xl:px-16 max-w-xl">
          <Text className="text-brand-orange font-bold tracking-widest text-sm uppercase mb-4">Construction Management Platform</Text>
          <Text className="text-white font-extrabold text-5xl leading-tight mb-6">Effortlessly manage your team and operations.</Text>
          <Text className="text-gray-400 text-lg leading-relaxed mb-12">Log in to access your CRM, manage your team, track materials, and oversee active projects across all your sites in real-time.</Text>

          {/* Decorative preview */}
          <View className="bg-white/10 p-6 rounded-3xl border border-white/20 backdrop-blur-md shadow-2xl">
            <View className="flex-row items-center border-b border-white/10 pb-4 mb-4">
               <View className="w-3 h-3 rounded-full bg-red-400 mr-2" />
               <View className="w-3 h-3 rounded-full bg-yellow-400 mr-2" />
               <View className="w-3 h-3 rounded-full bg-green-400" />
            </View>
            <View className="flex-row mb-4">
              <View className="flex-1 bg-white/20 h-24 rounded-xl p-4 justify-end mr-4">
                 <View className="w-8 h-2 bg-white/40 rounded-full mb-2" />
                 <View className="w-20 h-4 bg-brand-orange rounded-full" />
              </View>
              <View className="flex-1 bg-white/20 h-24 rounded-xl p-4 justify-end">
                 <View className="w-12 h-2 bg-white/40 rounded-full mb-2" />
                 <View className="w-16 h-4 bg-white rounded-full" />
              </View>
            </View>
            <View className="w-full bg-white/20 h-32 rounded-xl" />
          </View>
        </View>
      </View>
    }>
      <View className="items-center mb-10">
        {/* ── Construct Ai Logo ── */}
        <Pressable
          onPress={() => router.push('/')}
          style={{ alignSelf: 'flex-start', width: '100%', maxWidth: 280, marginBottom: 24 }}
          accessibilityLabel="ConstructAi home"
        >
          <Image
            source={require('../../assets/images/main-logo.png')}
            style={{ width: '100%', aspectRatio: 4 }}
            resizeMode="contain"
          />
        </Pressable>
        <View className="w-full">
          <Text className="text-3xl md:text-4xl font-extrabold text-brand-text mb-2">Partner Login</Text>
          <Text className="text-gray-500 text-base">Enter your email and password to access your account.</Text>
        </View>
      </View>

      {errorMsg ? (
        <View className="bg-red-50 p-3 rounded-lg border border-red-200 mb-6">
          <Text className="text-red-600 text-sm text-center">{errorMsg}</Text>
        </View>
      ) : null}

      <View className="mb-5">
        <Text className="text-sm font-semibold text-gray-700 mb-2">Email</Text>
        <TextInput
          className="w-full border border-gray-300 rounded-xl p-4 text-brand-text bg-gray-50 focus:border-brand-orange focus:bg-white transition-colors"
          placeholder="name@company.com"
          value={email}
          onChangeText={setEmail}
          autoCapitalize="none"
          keyboardType="email-address"
          returnKeyType="next"
        />
      </View>

      <View className="mb-6">
        <View className="flex-row justify-between items-center mb-2 z-10">
          <Text className="text-sm font-semibold text-gray-700">Password</Text>
          <Link href="/forgot-password" style={{ zIndex: 10 }}>
            <Text className="text-sm font-medium text-brand-orange hover:underline">Forgot password?</Text>
          </Link>
        </View>
        <View className="w-full flex-row items-center border border-gray-300 rounded-xl bg-gray-50 pr-2">
          <TextInput
            className="flex-1 p-4 text-brand-text outline-none"
            placeholder="••••••••"
            value={password}
            onChangeText={setPassword}
            secureTextEntry={!showPassword}
            returnKeyType="next"
          />
          <Pressable onPress={() => setShowPassword(!showPassword)} className="p-2 cursor-pointer min-w-[44px] min-h-[44px] items-center justify-center" accessibilityLabel={showPassword ? "Hide password" : "Show password"}>
            <Ionicons name={showPassword ? "eye-off" : "eye"} size={22} color="#9CA3AF" />
          </Pressable>
        </View>
      </View>

      <View className="mb-6">
        <Text className="text-sm font-semibold text-gray-700 mb-2">Confirm Password</Text>
        <View className="w-full flex-row items-center border border-gray-300 rounded-xl bg-gray-50 pr-2">
          <TextInput
            className="flex-1 p-4 text-brand-text outline-none"
            placeholder="••••••••"
            value={confirmPassword}
            onChangeText={setConfirmPassword}
            secureTextEntry={!showConfirmPassword}
            returnKeyType="done"
            onSubmitEditing={handleLogin}
          />
          <Pressable onPress={() => setShowConfirmPassword(!showConfirmPassword)} className="p-2 cursor-pointer min-w-[44px] min-h-[44px] items-center justify-center" accessibilityLabel={showConfirmPassword ? "Hide password" : "Show password"}>
            <Ionicons name={showConfirmPassword ? "eye-off" : "eye"} size={22} color="#9CA3AF" />
          </Pressable>
        </View>
      </View>

      {/* Remember Me — now functional */}
      <Pressable
        onPress={() => setRememberMe(prev => !prev)}
        className="flex-row items-center mb-8"
        accessibilityRole="checkbox"
        accessibilityState={{ checked: rememberMe }}
      >
        <View
          style={{
            width: 20, height: 20, borderRadius: 5,
            borderWidth: 1.5,
            borderColor: rememberMe ? '#F97316' : '#D1D5DB',
            backgroundColor: rememberMe ? '#F97316' : '#F9FAFB',
            alignItems: 'center', justifyContent: 'center',
            marginRight: 10,
          }}
        >
          {rememberMe && <Ionicons name="checkmark" size={13} color="#fff" />}
        </View>
        <Text className="text-gray-600 text-sm">Remember me</Text>
      </Pressable>

      <Pressable
        onPress={handleLogin}
        disabled={loading}
        className={`w-full bg-brand-orange py-4 rounded-xl items-center justify-center shadow-md hover:bg-orange-600 transition-colors ${loading ? 'opacity-70' : ''}`}
      >
        {loading ? (
          <ActivityIndicator color="white" />
        ) : (
          <Text className="text-white font-bold text-lg">Log In</Text>
        )}
      </Pressable>

      <View className="flex-row items-center justify-center my-8">
        <View className="flex-1 h-px bg-gray-200" />
        <Text className="px-4 text-gray-400 font-medium text-sm">Or Login With</Text>
        <View className="flex-1 h-px bg-gray-200" />
      </View>

      <View className="flex-row mb-8">
        <Pressable onPress={handleGoogleAuth} className="w-full flex-row items-center justify-center py-3 border border-gray-300 rounded-xl hover:bg-gray-50 transition-colors">
          <Image
            source={{ uri: 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/c1/Google_%22G%22_logo.svg/120px-Google_%22G%22_logo.svg.png' }}
            style={{ width: 20, height: 20, marginRight: 10 }}
            resizeMode="contain"
          />
          <Text className="text-brand-text font-semibold text-base">Continue with Google</Text>
        </Pressable>
      </View>

      <View className="flex-row flex-wrap justify-center">
        <Text className="text-gray-500">Don&apos;t have an account? </Text>
        <Link href="/partner-register" asChild>
          <Pressable>
            <Text className="text-brand-orange font-bold hover:underline">Register Now</Text>
          </Pressable>
        </Link>
      </View>
    </AuthPageLayout>
  );
}

import React, { useState } from 'react';
import { View, Text, TextInput, Pressable, ActivityIndicator, Image } from 'react-native';
import { Link, useRouter } from 'expo-router';
import { supabase } from '../lib/supabase';
import AuthPageLayout from '../components/auth/AuthPageLayout';
import { MaterialIcons, FontAwesome5, Ionicons } from '@expo/vector-icons';

export default function RegisterScreen() {
  const [fullName, setFullName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [role, setRole] = useState('client');

  const [loading, setLoading] = useState(false);
  const [errorMsg, setErrorMsg] = useState('');
  const router = useRouter();

  const handleRegister = async () => {
    if (!fullName || !email || !password || !confirmPassword) {
      setErrorMsg('Please fill in all fields');
      return;
    }
    if (password !== confirmPassword) {
      setErrorMsg('Passwords do not match');
      return;
    }

    setLoading(true);
    setErrorMsg('');

    const { data, error } = await supabase.auth.signUp({
      email,
      password,
      options: {
        data: {
          full_name: fullName,
          role: role,
        }
      }
    });

    if (error) {
      console.error('SUPABASE RAW ERROR:', error);
      let displayError = error.message;
      if (typeof displayError === 'object' || displayError === '{}' || !displayError) {
        displayError = JSON.stringify(error);
      }
      setErrorMsg(displayError);
      setLoading(false);
    } else {
      // Sign out immediately to prevent auto-login
      if (data.session) {
        await supabase.auth.signOut();
      }
      // Force them to the login screen
      router.replace('/partner-login');
    }
  };

  const handleGoogleAuth = async () => {
    try {
      const { error } = await supabase.auth.signInWithOAuth({
        provider: 'google',
      });
      if (error) throw error;
    } catch (error: any) {
      setErrorMsg(error.message);
    }
  };

  return (
    <AuthPageLayout hero={
      <View className="bg-brand-dark relative overflow-hidden items-center justify-center"
        style={{ width: '50%', flexShrink: 0, paddingVertical: 48 }}>
        {/* Background Image with Overlay */}
        <Image
          source={{ uri: 'https://images.unsplash.com/photo-1503387762-592deb58ef4e?q=80&w=1200' }}
          className="absolute w-full h-full opacity-20"
          resizeMode="cover"
        />
        <View className="absolute inset-0 bg-brand-dark/90" />

        {/* Abstract Shapes */}
        <View className="absolute -top-32 -right-32 w-96 h-96 bg-brand-orange/20 rounded-full blur-3xl" />
        <View className="absolute -bottom-32 -left-32 w-96 h-96 bg-blue-500/10 rounded-full blur-3xl" />

        <View className="z-10 w-full px-8 xl:px-16 max-w-xl">
          <Text className="text-brand-orange font-bold tracking-widest text-sm uppercase mb-4">Start Building Today</Text>
          <Text className="text-white font-extrabold text-5xl leading-tight mb-6">Gain complete control over your projects.</Text>

          <View className="mb-6 flex-row items-center bg-white/5 p-4 rounded-2xl border border-white/10 backdrop-blur-sm">
            <View className="w-12 h-12 bg-orange-500/20 rounded-full items-center justify-center mr-4">
               <FontAwesome5 name="chart-line" size={20} color="#F97316" />
            </View>
            <View className="flex-1">
              <Text className="text-white font-bold text-lg">Real-Time Tracking</Text>
              <Text className="text-gray-400 text-sm">Monitor costs, labor, and materials.</Text>
            </View>
          </View>

          <View className="mb-6 flex-row items-center bg-white/5 p-4 rounded-2xl border border-white/10 backdrop-blur-sm">
            <View className="w-12 h-12 bg-blue-500/20 rounded-full items-center justify-center mr-4">
               <FontAwesome5 name="users-cog" size={20} color="#3B82F6" />
            </View>
            <View className="flex-1">
              <Text className="text-white font-bold text-lg">Role-Based Access</Text>
              <Text className="text-gray-400 text-sm">Separate views for admins, managers & clients.</Text>
            </View>
          </View>

          <View className="flex-row items-center bg-white/5 p-4 rounded-2xl border border-white/10 backdrop-blur-sm">
            <View className="w-12 h-12 bg-green-500/20 rounded-full items-center justify-center mr-4">
               <FontAwesome5 name="robot" size={20} color="#10B981" />
            </View>
            <View className="flex-1">
              <Text className="text-white font-bold text-lg">AI Estimations</Text>
              <Text className="text-gray-400 text-sm">Generate quick, accurate quotes using AI.</Text>
            </View>
          </View>

        </View>
      </View>
    }>
      <View className="items-center mb-8">
        {/* ── Construct Ai Logo ── */}
        <Pressable
          onPress={() => router.push('/')}
          style={{ alignSelf: 'flex-start', width: '100%', maxWidth: 280, marginBottom: 24 }}
          accessibilityLabel="ConstructAi home"
        >
          <Image
            source={require('../../assets/images/main-logo.png')}
            style={{ width: '100%', aspectRatio: 4 }}
            resizeMode="contain"
          />
        </Pressable>
        <View className="w-full">
          <Text className="text-3xl md:text-4xl font-extrabold text-brand-text mb-2">Partner Registration</Text>
          <Text className="text-gray-500 text-base">Join ConstructAi today to manage your team.</Text>
        </View>
      </View>

      {errorMsg ? (
        <View className="bg-red-50 p-3 rounded-lg border border-red-200 mb-6">
          <Text className="text-red-600 text-sm text-center">{errorMsg}</Text>
        </View>
      ) : null}

      <View className="mb-4">
        <Text className="text-sm font-semibold text-gray-700 mb-2">Full Name</Text>
        <TextInput
          className="w-full border border-gray-300 rounded-xl p-4 text-brand-text bg-gray-50 focus:border-brand-orange focus:bg-white transition-colors"
          placeholder="John Doe"
          value={fullName}
          onChangeText={setFullName}
        />
      </View>

      <View className="mb-4">
        <Text className="text-sm font-semibold text-gray-700 mb-2">Email</Text>
        <TextInput
          className="w-full border border-gray-300 rounded-xl p-4 text-brand-text bg-gray-50 focus:border-brand-orange focus:bg-white transition-colors"
          placeholder="name@company.com"
          value={email}
          onChangeText={setEmail}
          autoCapitalize="none"
          keyboardType="email-address"
        />
      </View>

      <View className="mb-4">
        <Text className="text-sm font-semibold text-gray-700 mb-2">Password</Text>
        <View className="w-full flex-row items-center border border-gray-300 rounded-xl bg-gray-50 pr-2">
          <TextInput
            className="flex-1 p-4 text-brand-text outline-none"
            placeholder="••••••••"
            value={password}
            onChangeText={setPassword}
            secureTextEntry={!showPassword}
            returnKeyType="next"
          />
          <Pressable onPress={() => setShowPassword(!showPassword)} className="p-2 cursor-pointer min-w-[44px] min-h-[44px] items-center justify-center" accessibilityLabel={showPassword ? "Hide password" : "Show password"}>
            <Ionicons name={showPassword ? "eye-off" : "eye"} size={22} color="#9CA3AF" />
          </Pressable>
        </View>
      </View>

      <View className="mb-4">
        <Text className="text-sm font-semibold text-gray-700 mb-2">Confirm Password</Text>
        <View className="w-full flex-row items-center border border-gray-300 rounded-xl bg-gray-50 pr-2">
          <TextInput
            className="flex-1 p-4 text-brand-text outline-none"
            placeholder="••••••••"
            value={confirmPassword}
            onChangeText={setConfirmPassword}
            secureTextEntry={!showConfirmPassword}
            returnKeyType="done"
            onSubmitEditing={handleRegister}
          />
          <Pressable onPress={() => setShowConfirmPassword(!showConfirmPassword)} className="p-2 cursor-pointer min-w-[44px] min-h-[44px] items-center justify-center" accessibilityLabel={showConfirmPassword ? "Hide password" : "Show password"}>
            <Ionicons name={showConfirmPassword ? "eye-off" : "eye"} size={22} color="#9CA3AF" />
          </Pressable>
        </View>
      </View>


      <View className="mb-4">
        <Text className="text-sm font-semibold text-gray-700 mb-2">Role</Text>
        <View className="flex-row gap-2">
          {['client', 'supplier'].map((r) => (
            <Pressable
              key={r}
              onPress={() => setRole(r)}
              className={`flex-1 p-3 rounded-xl border ${role === r ? 'border-brand-orange bg-orange-50' : 'border-gray-300 bg-gray-50'} items-center`}
            >
              <Text className={`font-medium capitalize ${role === r ? 'text-brand-orange' : 'text-gray-500'}`}>
                {r.replace('_', ' ')}
              </Text>
            </Pressable>
          ))}
        </View>
      </View>


      <Pressable
        onPress={handleRegister}
        disabled={loading}
        className={`w-full bg-brand-orange py-4 rounded-xl items-center justify-center shadow-md hover:bg-orange-600 transition-colors ${loading ? 'opacity-70' : ''}`}
      >
        {loading ? (
          <ActivityIndicator color="white" />
        ) : (
          <Text className="text-white font-bold text-lg">Sign Up</Text>
        )}
      </Pressable>

      <View className="flex-row items-center justify-center my-6">
        <View className="flex-1 h-px bg-gray-200" />
        <Text className="px-4 text-gray-400 font-medium text-sm">Or Sign Up With</Text>
        <View className="flex-1 h-px bg-gray-200" />
      </View>

      <View className="flex-row mb-6">
        <Pressable onPress={handleGoogleAuth} className="w-full flex-row items-center justify-center py-3 border border-gray-300 rounded-xl hover:bg-gray-50 transition-colors">
          <Image
            source={{ uri: 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/c1/Google_%22G%22_logo.svg/120px-Google_%22G%22_logo.svg.png' }}
            style={{ width: 20, height: 20, marginRight: 10 }}
            resizeMode="contain"
          />
          <Text className="text-brand-text font-semibold text-base">Continue with Google</Text>
        </Pressable>
      </View>

      <View className="flex-row flex-wrap justify-center pb-8">
        <Text className="text-gray-500">Already have an account? </Text>
        <Link href="/partner-login" asChild>
          <Pressable>
            <Text className="text-brand-orange font-bold hover:underline">Sign In</Text>
          </Pressable>
        </Link>
      </View>
    </AuthPageLayout>
  );
}

import React, { useEffect, useState } from 'react';
import { View, ScrollView, ActivityIndicator, Pressable, Text } from 'react-native';
import { useRouter } from 'expo-router';
import { TopNav } from '@/components/common/TopNav';
import { StatCard } from '../../components/common/StatCard';
import { AttendanceTable } from '../../components/labour/AttendanceTable';
import { PayrollSummary } from '../../components/labour/PayrollSummary';
import { LabourDistributionChart } from '../../components/labour/LabourDistributionChart';
import { supabase } from '../../lib/supabase';

export default function PMLabourScreen() {
  const router = useRouter();
  const [stats, setStats] = useState({
    totalWorkers: 0,
    checkedInToday: 0,
    activeSites: 0,
    pendingPayroll: 0,
  });
  const [loading, setLoading] = useState(true);
  const [currentUserId, setCurrentUserId] = useState<string | undefined>();
  const [refreshTrigger, setRefreshTrigger] = useState(0);
  const [searchQuery, setSearchQuery] = useState('');

  useEffect(() => {
    let isMounted = true;
    const loadStats = async () => {
      try {
        const { data: sessionData } = await supabase.auth.getSession();
        if (!sessionData?.session) return;
        
        const pmId = sessionData.session.user.id;
        if (isMounted) setCurrentUserId(pmId);

        const today = new Date().toISOString().split('T')[0];

        // Fetch PM's projects
        const { data: projects } = await supabase.from('projects').select('id').eq('pm_id', pmId).eq('status', 'active');
        const activeProjectIds = projects?.map(p => p.id) || [];

        let workersCount = 0;
        let checkedInCount = 0;
        let overtimeTotal = 0;

        if (activeProjectIds.length > 0) {
          const [workersReq, labourReq] = await Promise.all([
            supabase.from('legacy_labour').select('id', { count: 'exact', head: true }).in('assigned_project_id', activeProjectIds),
            supabase.from('legacy_labour')
              .select('id, status, hours_worked')
              .eq('date', today)
              .in('assigned_project_id', activeProjectIds)
          ]);

          workersCount = workersReq.count || 0;
          if (labourReq.data) {
            checkedInCount = labourReq.data.filter(a => a.status === 'Present').length;
            overtimeTotal = labourReq.data.reduce((sum, a) => sum + Math.max(0, (Number(a.hours_worked) || 0) - 8), 0);
          }
        }

        if (isMounted) {
          setStats({
            totalWorkers: workersCount,
            checkedInToday: checkedInCount,
            activeSites: activeProjectIds.length,
            pendingPayroll: overtimeTotal
          });
        }
      } catch (error) {
        console.warn('Failed to load labour stats:', error);
      } finally {
        if (isMounted) setLoading(false);
      }
    };

    loadStats();
    return () => { isMounted = false; };
  }, [refreshTrigger]);

  return (
    <View className="flex-1 bg-brand-light">
      <TopNav 
        title="Labour Force (Your Projects)" 
        showAction={false}
        initialSearchQuery={searchQuery}
        onSearch={setSearchQuery}
      />
      
      {loading ? (
        <View className="flex-1 items-center justify-center">
          <ActivityIndicator size="large" color="#3B82F6" />
        </View>
      ) : (
        <ScrollView className="flex-1 p-6" showsVerticalScrollIndicator={false}>
          {/* Top Stat Cards Row */}
          <View className="flex-row justify-between mb-6 -mx-2">
            <StatCard 
              label="Total Workers" 
              value={stats.totalWorkers.toString()} 
              indicatorText="On your active sites" 
            />
            <StatCard 
              label="Checked In Today" 
              value={stats.checkedInToday.toString()} 
              indicatorText="Currently present" 
            />
            <StatCard 
              label="Today's Overtime" 
              value={`${stats.pendingPayroll} hrs`} 
              indicatorText="Additional hours" 
              indicatorType="warning" 
            />
            <StatCard 
              label="Active Sites" 
              value={stats.activeSites.toString()} 
              indicatorText="Managed by you" 
            />
          </View>

          {/* Main Content Layout */}
          <View className="flex-row">
            {/* Main Content Area (Attendance Table) */}
            <View className="flex-[2] mr-6">
              <AttendanceTable refreshTrigger={refreshTrigger} searchQuery={searchQuery} pmId={currentUserId} />
            </View>
            
            {/* Side Panel (Payroll & Chart) */}
            <View className="flex-[1] flex-col">
              <PayrollSummary refreshTrigger={refreshTrigger} pmId={currentUserId} />
              <View className="h-64">
                <LabourDistributionChart refreshTrigger={refreshTrigger} pmId={currentUserId} />
              </View>
            </View>
          </View>
        </ScrollView>
      )}
    </View>
  );
}

import { ModalViewport } from '@/components/common/ModalViewport';
import React, { useEffect, useState } from 'react';
import { View, Text, ScrollView, Pressable, ActivityIndicator, Alert, Modal, TextInput } from 'react-native';
import { useRouter } from 'expo-router';
import { Ionicons } from '@expo/vector-icons';
import { supabase } from '../../../lib/supabase';
import { useAuth } from '../../../context/AuthContext';
import { TopNav } from '@/components/common/TopNav';

export default function PMApprovalQueue() {
  const { user } = useAuth();
  const router = useRouter();
  const [requests, setRequests] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [actioningId, setActioningId] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');

  // Reject Modal State
  const [showRejectModal, setShowRejectModal] = useState(false);
  const [rejectReason, setRejectReason] = useState('');
  const [selectedReqId, setSelectedReqId] = useState<string | null>(null);

  const [activeTab, setActiveTab] = useState<'queue' | 'stock' | 'orders'>('queue');
  const [stockData, setStockData] = useState<any[]>([]);
  const [ordersData, setOrdersData] = useState<any[]>([]);

  const loadRequests = async () => {
    setLoading(true);
    try {
      const { data: sessionData } = await supabase.auth.getSession();
      if (!sessionData?.session) return;
      const pmId = sessionData.session.user.id;

      // 1. Fetch PM's projects directly (no pm_projects junction table)
      const { data: pmProjects } = await supabase.from('projects').select('id').eq('pm_id', pmId);
      const projectIds = pmProjects?.map(p => p.id) || [];

      if (projectIds.length === 0) {
        setRequests([]);
        setStockData([]);
        setLoading(false);
        return;
      }

      if (activeTab === 'queue') {
        let query = supabase
          .from('material_requests')
          .select('*, projects(name), profiles:requested_by(full_name)')
          .in('project_id', projectIds)
          .order('created_at', { ascending: false });

        if (searchQuery) query = query.ilike('item_name', `%${searchQuery}%`);
        const { data, error } = await query;
        if (error && error.code !== '42P01') throw error;
        setRequests(data || []);
      } else if (activeTab === 'stock') {
        // Fetch materials for PM's projects
        let query = supabase
          .from('materials')
          .select('*, projects(name)')
          .in('project_id', projectIds)
          .order('created_at', { ascending: false });
          
        if (searchQuery) query = query.ilike('item_name', `%${searchQuery}%`);
        const { data, error } = await query;
        if (error && error.code !== '42P01') throw error;
        setStockData(data || []);
      } else if (activeTab === 'orders') {
        let query = supabase
          .from('purchase_orders')
          .select('*, projects(name), suppliers(full_name)')
          .in('project_id', projectIds)
          .order('created_at', { ascending: false });

        if (searchQuery) query = query.ilike('po_number', `%${searchQuery}%`);
        const { data, error } = await query;
        if (error && error.code !== '42P01') throw error;
        setOrdersData(data || []);
      }
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadRequests();
  }, [searchQuery, activeTab]);

  const handleApprove = async (req: any) => {
    setActioningId(req.id);
    try {
      await supabase.from('material_requests').update({ status: 'Approved' }).eq('id', req.id);
      
      // Notify Supplier
      await supabase.from('notifications').insert({
        project_id: req.project_id,
        target_role: 'Supplier',
        title: 'New Approved Order',
        message: `Project Manager approved ${req.quantity} ${req.unit} of ${req.item_name}. Ready for fulfillment.`,
      });

      // Notify Site Manager
      if (req.requested_by) {
        await supabase.from('notifications').insert({
          target_user_id: req.requested_by,
          title: 'Material Request Approved',
          message: `Your request for ${req.item_name} was approved!`,
        });
      }

      Alert.alert('Approved', 'Request has been forwarded to the Supplier.');
      loadRequests();
    } catch (e: any) {
      Alert.alert('Error', e.message);
    } finally {
      setActioningId(null);
    }
  };

  const handleRejectConfirm = async () => {
    if (!selectedReqId || !rejectReason) {
      Alert.alert('Error', 'Please provide a reason for rejection.');
      return;
    }

    setActioningId(selectedReqId);
    try {
      const req = requests.find(r => r.id === selectedReqId);
      await supabase.from('material_requests').update({ status: 'Rejected', notes: rejectReason }).eq('id', selectedReqId);
      
      if (req?.requested_by) {
        await supabase.from('notifications').insert({
          target_user_id: req.requested_by,
          title: 'Material Request Rejected',
          message: `Your request for ${req.item_name} was rejected. Reason: ${rejectReason}`,
        });
      }

      setShowRejectModal(false);
      setRejectReason('');
      setSelectedReqId(null);
      loadRequests();
    } catch (e: any) {
      Alert.alert('Error', e.message);
    } finally {
      setActioningId(null);
    }
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'Pending Approval': return 'bg-yellow-100 text-yellow-800';
      case 'Approved': return 'bg-blue-100 text-blue-800';
      case 'Ordered': return 'bg-purple-100 text-purple-800';
      case 'Delivered': return 'bg-green-100 text-green-800';
      case 'Rejected': return 'bg-red-100 text-red-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  return (
    <View className="flex-1 bg-brand-light">
      <TopNav 
        title="Materials Management" 
        showAction={false} 
        initialSearchQuery={searchQuery}
        onSearch={setSearchQuery}
      />

      {/* Tabs */}
      <View className="flex-row px-8 mt-6">
        <Pressable 
          onPress={() => setActiveTab('queue')}
          className={`pb-3 mr-8 border-b-2 ${activeTab === 'queue' ? 'border-brand-orange' : 'border-transparent'}`}
        >
          <Text className={`font-bold text-base ${activeTab === 'queue' ? 'text-brand-orange' : 'text-gray-500'}`}>Approval Queue</Text>
        </Pressable>
        <Pressable 
          onPress={() => setActiveTab('stock')}
          className={`pb-3 mr-8 border-b-2 ${activeTab === 'stock' ? 'border-brand-orange' : 'border-transparent'}`}
        >
          <Text className={`font-bold text-base ${activeTab === 'stock' ? 'text-brand-orange' : 'text-gray-500'}`}>Site Stock</Text>
        </Pressable>
        <Pressable 
          onPress={() => setActiveTab('orders')}
          className={`pb-3 border-b-2 ${activeTab === 'orders' ? 'border-brand-orange' : 'border-transparent'}`}
        >
          <Text className={`font-bold text-base ${activeTab === 'orders' ? 'text-brand-orange' : 'text-gray-500'}`}>Purchase Orders</Text>
        </Pressable>
      </View>

      <View className="flex-1 p-8">
        {loading ? (
          <ActivityIndicator size="large" color="#F97316" className="mt-10" />
        ) : (
          <View className="bg-white rounded-2xl shadow-sm border border-gray-100 flex-1 overflow-hidden">
            <View className="flex-row py-4 px-6 border-b border-gray-100 bg-gray-50">
              <Text className="w-1/5 text-xs font-bold text-gray-500 uppercase">Item</Text>
              <Text className="w-1/6 text-xs font-bold text-gray-500 uppercase">{activeTab === 'queue' ? 'Project' : 'Site'}</Text>
              <Text className="w-1/6 text-xs font-bold text-gray-500 uppercase">Quantity</Text>
              <Text className="w-1/6 text-xs font-bold text-gray-500 uppercase">{activeTab === 'queue' ? 'Status' : 'Last Updated'}</Text>
              {activeTab === 'queue' && <Text className="w-1/4 text-xs font-bold text-gray-500 uppercase text-right">Actions</Text>}
            </View>

            <ScrollView showsVerticalScrollIndicator={false}>
              {activeTab === 'queue' ? (
                requests.length === 0 ? (
                  <View className="p-10 items-center justify-center">
                    <Ionicons name="checkmark-done-circle-outline" size={48} color="#D1D5DB" />
                    <Text className="text-gray-400 mt-4">No pending requests to approve.</Text>
                  </View>
                ) : (
                  requests.map(req => (
                    <View key={req.id} className="flex-row items-center py-4 px-6 border-b border-gray-50 hover:bg-gray-50 transition-colors">
                      <View className="w-1/5">
                        <Text className="font-bold text-brand-text">{req.item_name}</Text>
                        <Text className="text-xs text-gray-400 mt-1">By: {req.profiles?.full_name || 'Site Manager'}</Text>
                      </View>
                      <View className="w-1/6">
                        <Text className="text-gray-500 text-sm truncate">{req.projects?.name || 'Unknown'}</Text>
                      </View>
                      <View className="w-1/6">
                        <Text className="text-brand-text font-semibold">{req.quantity} {req.unit}</Text>
                      </View>
                      <View className="w-1/6">
                        <View className={`self-start px-2.5 py-1 rounded-md ${getStatusColor(req.status).split(' ')[0]}`}>
                          <Text className={`text-xs font-bold ${getStatusColor(req.status).split(' ')[1]}`}>{req.status}</Text>
                        </View>
                      </View>
                      <View className="w-1/4 flex-row justify-end space-x-2 gap-2">
                        {req.status === 'Pending Approval' ? (
                          <>
                            <Pressable 
                              onPress={() => {
                                setSelectedReqId(req.id);
                                setShowRejectModal(true);
                              }}
                              disabled={actioningId === req.id}
                              className="bg-white border border-red-200 px-4 py-2 rounded-lg hover:bg-red-50"
                            >
                              <Text className="text-red-600 font-semibold text-xs">Reject</Text>
                            </Pressable>
                            <Pressable 
                              onPress={() => handleApprove(req)}
                              disabled={actioningId === req.id}
                              className="bg-brand-orange px-4 py-2 rounded-lg hover:bg-orange-600 flex-row items-center"
                            >
                              {actioningId === req.id ? (
                                <ActivityIndicator size="small" color="white" />
                              ) : (
                                <Text className="text-white font-semibold text-xs">Approve</Text>
                              )}
                            </Pressable>
                          </>
                        ) : (
                          <Text className="text-gray-400 text-xs italic">{req.notes || 'Processed'}</Text>
                        )}
                      </View>
                    </View>
                  ))
                )
              ) : activeTab === 'stock' ? (
                stockData.length === 0 ? (
                  <View className="p-10 items-center justify-center">
                    <Ionicons name="cube-outline" size={48} color="#D1D5DB" />
                    <Text className="text-gray-400 mt-4">No site stock data found.</Text>
                  </View>
                ) : (
                  stockData.map(stock => (
                    <View key={stock.id} className="flex-row items-center py-4 px-6 border-b border-gray-50 hover:bg-gray-50 transition-colors">
                      <View className="w-1/5">
                        <Text className="font-bold text-brand-text">{stock.item_name}</Text>
                      </View>
                      <View className="w-1/6">
                        <Text className="text-gray-500 text-sm truncate">{stock.projects?.name || 'Unknown'}</Text>
                      </View>
                      <View className="w-1/6">
                        <Text className="text-brand-text font-semibold">{stock.current_stock ?? 0} {stock.unit}</Text>
                      </View>
                      <View className="w-1/6">
                        <Text className="text-gray-500 text-xs">
                          {stock.created_at ? new Date(stock.created_at).toLocaleDateString() : '—'}
                        </Text>
                      </View>
                    </View>
                  ))
                )
              ) : (
                <View>
                  <View className="flex-row justify-between items-center mb-4 mt-2 px-6">
                    <Text className="text-sm font-semibold text-gray-500">All Purchase Orders</Text>
                    <Pressable 
                      onPress={() => router.push('/pm/materials/orders/create' as any)}
                      className="bg-brand-orange px-4 py-2 rounded-lg flex-row items-center"
                    >
                      <Ionicons name="add" size={16} color="white" />
                      <Text className="text-white font-bold text-xs ml-1">Create PO</Text>
                    </Pressable>
                  </View>
                  {ordersData.length === 0 ? (
                    <View className="p-10 items-center justify-center">
                      <Ionicons name="document-text-outline" size={48} color="#D1D5DB" />
                      <Text className="text-gray-400 mt-4">No purchase orders found.</Text>
                    </View>
                  ) : (
                    ordersData.map(order => (
                    <View key={order.id} className="flex-row items-center py-4 px-6 border-b border-gray-50 hover:bg-gray-50 transition-colors">
                      <View className="w-1/5">
                        <Text className="font-bold text-brand-text">{order.po_number}</Text>
                        <Text className="text-xs text-gray-400 mt-1">Total: {order.total_price}</Text>
                      </View>
                      <View className="w-1/6">
                        <Text className="text-gray-500 text-sm truncate">{order.projects?.name || 'Unknown'}</Text>
                      </View>
                      <View className="w-1/6">
                        <Text className="text-brand-text font-semibold">{order.suppliers?.full_name || 'Supplier'}</Text>
                      </View>
                      <View className="w-1/6">
                        <View className={`self-start px-2.5 py-1 rounded-md ${getStatusColor(order.status).split(' ')[0]}`}>
                          <Text className={`text-xs font-bold ${getStatusColor(order.status).split(' ')[1]}`}>{order.status}</Text>
                        </View>
                        {order.actual_delivery && (
                          <Text className="text-xs text-gray-400 mt-1">Del: {order.actual_delivery}</Text>
                        )}
                      </View>
                    </View>
                  ))
                )}
                </View>
              )}
            </ScrollView>
          </View>
        )}
      </View>

      {/* Reject Modal */}
      <Modal visible={showRejectModal} transparent animationType="fade" onRequestClose={() => setShowRejectModal(false)}>
        <ModalViewport>
          <ScrollView keyboardShouldPersistTaps="handled" nestedScrollEnabled style={{ flexGrow: 0, flexShrink: 1 }} contentContainerStyle={{ padding: 0 }} className="bg-white w-full max-w-sm rounded-2xl overflow-hidden shadow-2xl max-h-full">
            <View className="p-4 border-b border-gray-100 flex-row justify-between items-center bg-gray-50">
              <Text className="text-lg font-bold text-red-600">Reject Request</Text>
              <Pressable onPress={() => !actioningId && setShowRejectModal(false)}>
                <Ionicons name="close" size={24} color="#6B7280" />
              </Pressable>
            </View>
            
            <View className="p-6">
              <Text className="text-sm font-semibold text-gray-700 mb-2">Reason for Rejection</Text>
              <TextInput
                className="border border-gray-200 rounded-xl p-3 text-brand-text bg-gray-50 mb-6"
                placeholder="E.g. Exceeds current budget."
                value={rejectReason}
                onChangeText={setRejectReason}
                multiline
                numberOfLines={3}
              />

              <Pressable 
                onPress={handleRejectConfirm}
                disabled={actioningId !== null || !rejectReason}
                className={`py-3 rounded-xl flex-row items-center justify-center ${actioningId !== null || !rejectReason ? 'bg-red-300' : 'bg-red-600 hover:bg-red-700'}`}
              >
                {actioningId !== null ? (
                  <ActivityIndicator size="small" color="white" />
                ) : (
                  <Text className="text-white font-bold text-sm">Confirm Rejection</Text>
                )}
              </Pressable>
            </View>
          </ScrollView>
        </ModalViewport>
      </Modal>

    </View>
  );
}

import { firstRelation } from '@/utils/relations';
import React, { useEffect, useState, useCallback } from 'react';
import { View, Text, ScrollView, ActivityIndicator, Pressable, Image } from 'react-native';
import { TopNav } from '@/components/common/TopNav';
import { Ionicons } from '@expo/vector-icons';
import { useLocalSearchParams } from 'expo-router';
import { supabase } from '../../../../lib/supabase';

type SiteReport = {
  id: string;
  project_id: string;
  date: string;
  work_completed: string;
  workers_present_count: number | null;
  blockers: string | null;
  photos: string[] | null;
  created_at: string;
  site_manager?: { full_name: string; avatar_url: string | null };
};

export default function PMProjectSiteReports() {
  const { id: projectId } = useLocalSearchParams<{ id: string }>();
  const [loading, setLoading] = useState(true);
  const [reports, setReports] = useState<SiteReport[]>([]);

  const loadData = useCallback(async () => {
    if (!projectId) return;
    try {
      setLoading(true);
      const { data: reportsData } = await supabase
        .from('site_reports')
        .select(`
          id, project_id, date, work_completed, workers_present_count, blockers, photos, created_at,
          site_manager:profiles!site_manager_id(full_name, avatar_url)
        `)
        .eq('project_id', projectId)
        .order('date', { ascending: false });
      setReports((reportsData || []).map(report => ({ ...report, site_manager: firstRelation(report.site_manager) })));
    } catch (error) {
      console.error('Failed to load site reports:', error);
    } finally {
      setLoading(false);
    }
  }, [projectId]);

  useEffect(() => { loadData(); }, [loadData]);

  // Realtime: refresh when a new report is submitted.
  useEffect(() => {
    if (!projectId) return;
    const channel = supabase
      .channel(`pm-site-reports:${projectId}`)
      .on('postgres_changes', {
        event: 'INSERT',
        schema: 'public',
        table: 'site_reports',
        filter: `project_id=eq.${projectId}`,
      }, () => loadData())
      .subscribe();
    return () => { supabase.removeChannel(channel); };
  }, [projectId, loadData]);

  const formatDate = (dateStr: string) =>
    new Date(dateStr).toLocaleDateString('en-LK', { weekday: 'short', year: 'numeric', month: 'short', day: 'numeric' });

  return (
    <View className="flex-1 bg-brand-light">
      <TopNav title="Daily Site Reports" showAction={false} />

      <ScrollView className="flex-1 p-6" showsVerticalScrollIndicator={false}>
        <Text className="text-2xl font-bold text-gray-800 mb-6">Site Reports History</Text>
        
        {loading ? (
          <View className="py-10 items-center justify-center">
            <ActivityIndicator color="#F97316" size="large" />
          </View>
        ) : reports.length === 0 ? (
          <View className="bg-white border border-gray-100 rounded-2xl p-10 items-center justify-center">
            <Ionicons name="document-text-outline" size={48} color="#D1D5DB" />
            <Text className="text-gray-400 font-bold mt-4 text-center">No reports yet</Text>
            <Text className="text-gray-400 text-sm mt-2 text-center">Your site manager hasn&apos;t submitted any daily reports.</Text>
          </View>
        ) : (
          reports.map(report => (
            <View key={report.id} className="bg-white border border-gray-100 rounded-2xl p-6 mb-6 shadow-sm">
              <View className="flex-row justify-between items-start border-b border-gray-50 pb-4 mb-4">
                <View>
                  <Text className="text-gray-800 font-bold text-lg">{formatDate(report.date)}</Text>
                  {report.site_manager && (
                    <Text className="text-gray-500 mt-1 text-xs">Submitted by: {report.site_manager.full_name}</Text>
                  )}
                </View>
                {report.workers_present_count !== null && (
                  <View className="bg-orange-50 px-3 py-1.5 rounded-lg flex-row items-center">
                    <Ionicons name="people" size={14} color="#F97316" />
                    <Text className="text-brand-orange font-bold text-xs ml-1.5">{report.workers_present_count} Workers</Text>
                  </View>
                )}
              </View>

              <View className="mb-4">
                <Text className="text-gray-400 text-xs font-bold uppercase mb-2 tracking-wider">Work Completed</Text>
                <Text className="text-gray-700 leading-relaxed">{report.work_completed}</Text>
              </View>

              {report.blockers ? (
                <View className="bg-red-50 p-4 rounded-xl border border-red-100 mb-4 flex-row">
                  <Ionicons name="warning" size={16} color="#DC2626" className="mt-0.5 mr-2" />
                  <View className="flex-1">
                    <Text className="text-red-800 font-bold text-xs uppercase mb-1">Blockers / Issues</Text>
                    <Text className="text-red-700 text-sm leading-relaxed">{report.blockers}</Text>
                  </View>
                </View>
              ) : null}

              {report.photos && report.photos.length > 0 && (
                <View>
                  <Text className="text-gray-400 text-xs font-bold uppercase mb-2 tracking-wider">Attachments</Text>
                  <ScrollView horizontal showsHorizontalScrollIndicator={false} className="flex-row">
                    {report.photos.map((photo, index) => (
                      <View key={index} className="w-24 h-24 mr-3 bg-gray-100 rounded-xl overflow-hidden border border-gray-200">
                        <Image source={{ uri: photo }} className="w-full h-full" resizeMode="cover" />
                      </View>
                    ))}
                  </ScrollView>
                </View>
              )}
            </View>
          ))
        )}
      </ScrollView>
    </View>
  );
}

import React, { useEffect, useState } from 'react';
