export default function SMAttendancePage() {
  const { user } = useAuth();
  const { assignedProjectIds, siteAssignmentIds, assignments, loading: sitesLoading } = useAssignedSites(user?.id);

  const [loading, setLoading] = useState(true);
  const [projects, setProjects] = useState<any[]>([]);
  const [activeProjectId, setActiveProjectId] = useState<string | null>(null);
  const [siteByProject, setSiteByProject] = useState<Record<string, string>>({});

  const [projectWorkers, setProjectWorkers] = useState<WorkerProfile[]>([]);
  const [todayAttendance, setTodayAttendance] = useState<AttendanceRecord[]>([]);
  const [scanResult, setScanResult] = useState<ScanResult | null>(null);

  // Scanner & Modal State
  const [isScanning, setIsScanning] = useState(false);
  const [showManualModal, setShowManualModal] = useState(false);
  const [manualWorkerId, setManualWorkerId] = useState<string | null>(null);
  const [manualSubmitting, setManualSubmitting] = useState(false);

  const isMounted = useRef(true);

  const getTodayDateString = () => new Date().toISOString().split('T')[0];

  const fetchAttendanceData = useCallback(async (skipLoadingState = false) => {
    try {
      if (!skipLoadingState) setLoading(true);
      if (!user?.id || sitesLoading || !isMounted.current) return;

      const siteMap = Object.fromEntries(
        assignments.map((a: any) => [a.projectId, a.assignmentId]),
      );
      if (isMounted.current) setSiteByProject(siteMap);

      const { data: projectsData } = assignedProjectIds.length
        ? await supabase.from('projects').select('id, name, location').in('id', assignedProjectIds).eq('status', 'active')
        : { data: [] };

      const parsedProjects = projectsData || [];
      if (isMounted.current) setProjects(parsedProjects);

      if (parsedProjects.length > 0) {
        const currentProject = activeProjectId || parsedProjects[0].id;
        if (!activeProjectId && isMounted.current) setActiveProjectId(currentProject);

        const siteId = siteMap[currentProject];
        if (!siteId) return;

        // 2. Fetch today's attendance from canonical attendance table (not legacy labour)
        const todayStr = getTodayDateString();
        const { data: attData } = await supabase
          .from('attendance')
          .select('id, worker_id, site_id, date, status, check_in_time, check_out_time, hours_worked')
          .eq('site_id', siteId)
          .eq('date', todayStr);

        if (isMounted.current) setTodayAttendance((attData || []) as AttendanceRecord[]);

        // 3. Fetch workers assigned to this project's site via site_workers
        const { data: siteWorkers } = await supabase
          .from('site_workers')
          .select('worker_id, profiles!inner(id, full_name, qr_code, avatar_url)')
          .eq('project_id', currentProject);

        if (isMounted.current) {
          const workerProfiles: WorkerProfile[] = (siteWorkers || []).map((sw: any) => {
            const profile = Array.isArray(sw.profiles) ? sw.profiles[0] : sw.profiles;
            return {
              id: sw.worker_id,
              full_name: profile?.full_name || null,
              qr_code: profile?.qr_code || null,
              avatar_url: profile?.avatar_url || null,
            };
          });
          setProjectWorkers(workerProfiles);
        }
      }
    } catch (error: any) {
      console.error('Error fetching attendance data', error);
    } finally {
      if (isMounted.current && !skipLoadingState) setLoading(false);
    }
  }, [user?.id, sitesLoading, assignedProjectIds, assignments, activeProjectId]);

  useEffect(() => {
    isMounted.current = true;
    fetchAttendanceData();
    return () => { isMounted.current = false; };
  }, [fetchAttendanceData]);

  // Realtime subscription: refresh attendance list when any attendance row changes.
  useEffect(() => {
    const siteId = activeProjectId ? siteByProject[activeProjectId] : null;
    if (!siteId) return;

    const channel = supabase
      .channel(`sm-attendance:${siteId}`)
      .on('postgres_changes', {
        event: '*',
        schema: 'public',
        table: 'attendance',
        filter: `site_id=eq.${siteId}`,
      }, () => { fetchAttendanceData(true); })
      .subscribe();

    return () => { supabase.removeChannel(channel); };
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [activeProjectId, siteByProject]);

  const markAttendance = async (qrCode: string) => {
    if (!activeProjectId) return;
    const siteId = siteByProject[activeProjectId];
    if (!siteId) {
      if (Platform.OS === 'web') {
        window.alert('No active site assignment was found for this project.');
      } else {
        Alert.alert('Site unavailable', 'No active site assignment was found for this project.');
      }
      return;
    }
    try {
      const session = await supabase.auth.getSession();
      const token = session.data.session?.access_token;

      const response = await fetch(`${process.env.EXPO_PUBLIC_API_URL}/labour/scan`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`,
        },
        body: JSON.stringify({ qr_code: qrCode, site_id: siteId }),
      });

      const result = await response.json();

      if (!response.ok) {
        throw new Error(result.detail || 'Scan failed');
      }

      // Show scan result card instead of just an alert
      setScanResult(result as ScanResult);
      if (isScanning) setIsScanning(false);
      // Attendance list will update via Realtime subscription above
    } catch (error: any) {
      if (Platform.OS === 'web') {
        window.alert(`Scan failed: ${error.message}`);
      } else {
        Alert.alert('Scan Error', error.message);
      }
    }
  };

  const handleManualCheckIn = async () => {
    if (!manualWorkerId || !activeProjectId) return;
    const siteId = siteByProject[activeProjectId];
    if (!siteId) return;

    setManualSubmitting(true);
    try {
      const todayStr = getTodayDateString();
      const existing = todayAttendance.find(a => a.worker_id === manualWorkerId);

      const now = new Date();
      const timeStr = now.toISOString();

      if (existing && !existing.check_out_time) {
        // Check out
        const { error } = await supabase
          .from('attendance')
          .update({ check_out_time: timeStr })
          .eq('id', existing.id);
        if (error) throw error;
        toast('Checked out successfully');
      } else if (!existing) {
        // Check in
        const { error } = await supabase
          .from('attendance')
          .insert({
            worker_id: manualWorkerId,
            site_id: siteId,
            date: todayStr,
            status: 'Present',
            check_in_time: timeStr
          });
        if (error) throw error;
        toast('Checked in successfully');
      }

      setShowManualModal(false);
      setManualWorkerId(null);
      // Realtime will update the list
    } catch (e: any) {
      Alert.alert('Error', e.message);
    } finally {
      setManualSubmitting(false);
    }
  };

  const getAttendanceForWorker = (workerId: string) => {
    return todayAttendance.find(a => a.worker_id === workerId) || null;
  };

  // Helper for web alert
  const toast = (msg: string) => {
    if (Platform.OS === 'web') window.alert(msg);
    else Alert.alert('Success', msg);
  };

  return (
    <View className="flex-1 bg-brand-light">
      <TopNav title="Daily Attendance" />

      {loading || sitesLoading ? (
        <View className="flex-1 items-center justify-center">
          <ActivityIndicator size="large" color="#F97316" />
        </View>
      ) : assignedProjectIds.length === 0 ? (
        <NoAssignedSites />
      ) : (
        <View className="flex-1">
            <>
              {/* Project Selector Tabs */}
              <View className="bg-white px-6 pt-4 border-b border-gray-200">
                <ScrollView horizontal showsHorizontalScrollIndicator={false} className="flex-row">
                  {projects.map(project => (
                    <Pressable
                      key={project.id}
                      onPress={() => setActiveProjectId(project.id)}
                      className={`mr-6 pb-3 border-b-2 ${activeProjectId === project.id ? 'border-brand-orange' : 'border-transparent'}`}
                    >
                      <Text className={`font-bold text-base ${activeProjectId === project.id ? 'text-brand-orange' : 'text-gray-500'}`}>
                        {project.name}
                      </Text>
                    </Pressable>
                  ))}
                </ScrollView>
              </View>

              <ScrollView className="flex-1 p-8" showsVerticalScrollIndicator={false}>

                {/* Scan Result Card */}
                {scanResult && (
                  <View className={`rounded-xl p-4 mb-6 flex-row items-center border ${scanResult.action === 'check_in' ? 'bg-green-50 border-green-200' : 'bg-blue-50 border-blue-200'}`}>
                    <View className={`w-11 h-11 rounded-full items-center justify-center mr-3 ${scanResult.action === 'check_in' ? 'bg-green-100' : 'bg-blue-100'}`}>
                      <Ionicons
                        name={scanResult.action === 'check_in' ? 'log-in-outline' : 'log-out-outline'}
                        size={22}
                        color={scanResult.action === 'check_in' ? '#22C55E' : '#3B82F6'}
                      />
                    </View>
                    <View className="flex-1">
                      <Text className="font-bold text-brand-text">{scanResult.worker_name}</Text>
                      <Text className="text-gray-500 text-sm">
                        {scanResult.action === 'check_in' ? 'Checked In' : `Checked Out · ${scanResult.hours_worked?.toFixed(1) || 0}h worked`}
                      </Text>
                    </View>
                    <Pressable onPress={() => setScanResult(null)} className="p-2">
                      <Ionicons name="close" size={18} color="#9CA3AF" />
                    </Pressable>
                  </View>
                )}

                <View className="flex-row justify-between items-center mb-6">
                  <View>
                    <Text className="text-2xl font-bold text-gray-800">Today&apos;s Attendance</Text>
                    <Text className="text-gray-500">{new Date().toDateString()}</Text>
                  </View>

                  <View className="flex-row gap-3">
                    <Pressable
                      onPress={() => setShowManualModal(true)}
                      className="bg-white border border-gray-200 px-5 py-3 rounded-xl flex-row items-center shadow-sm"
                    >
                      <Ionicons name="create-outline" size={20} color="#4B5563" style={{ marginRight: 8 }} />
                      <Text className="text-gray-700 font-bold text-base">Manual</Text>
                    </Pressable>
                    <Pressable
                      onPress={() => setIsScanning(true)}
                      className="bg-brand-orange px-5 py-3 rounded-xl flex-row items-center shadow-sm"
                    >
                      <Ionicons name="qr-code-outline" size={20} color="white" style={{ marginRight: 8 }} />
                      <Text className="text-white font-bold text-base">Scan QR</Text>
                    </Pressable>
                  </View>
                </View>

                <View className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
                  <View className="flex-row py-4 px-6 border-b border-gray-100 bg-gray-50">
                    <Text className="flex-1 text-xs font-bold text-gray-500 uppercase">Worker</Text>
                    <Text className="w-[22%] text-xs font-bold text-gray-500 uppercase">Status</Text>
                    <Text className="w-[22%] text-xs font-bold text-gray-500 uppercase text-right">Hours</Text>
                  </View>

                  {projectWorkers.length === 0 ? (
                    <View className="p-10 items-center justify-center">
                      <Ionicons name="people-outline" size={48} color="#E5E7EB" />
                      <Text className="text-gray-400 mt-4 font-medium">No workers assigned to this site yet.</Text>
                    </View>
                  ) : (
                    projectWorkers.map((worker) => {
                      const attRecord = getAttendanceForWorker(worker.id);
                      const status = attRecord?.status || 'Pending';
                      const hours = attRecord?.hours_worked;
                      const checkedIn = attRecord?.check_in_time && !attRecord?.check_out_time;

                      return (
                        <View key={worker.id} className="flex-row items-center py-4 px-6 border-b border-gray-50">
                          <View className="flex-1 flex-row items-center">
                            <View className="w-8 h-8 bg-blue-100 rounded-full items-center justify-center mr-3">
                              <Ionicons name="person" size={14} color="#3B82F6" />
                            </View>
                            <View>
                              <Text className="font-bold text-gray-800">{worker.full_name || 'Unknown Worker'}</Text>
                              {checkedIn && (
                                <Text className="text-xs text-green-600">
                                  In: {new Date(attRecord!.check_in_time!).toLocaleTimeString('en-LK', { hour: '2-digit', minute: '2-digit' })}
                                </Text>
                              )}
                            </View>
                          </View>

                          <View className="w-[22%]">
                            {status === 'Pending' ? (
                              <Text className="text-gray-400 font-semibold italic text-sm">Pending</Text>
                            ) : status === 'Present' ? (
                              <Text className="text-green-600 font-bold bg-green-100 px-2 py-1 rounded self-start text-xs">Present</Text>
                            ) : (
                              <Text className="text-red-600 font-bold bg-red-100 px-2 py-1 rounded self-start text-xs">Absent</Text>
                            )}
                          </View>

                          <View className="w-[22%] items-end">
                            {hours != null ? (
                              <Text className="text-brand-text font-bold text-sm">{hours.toFixed(1)}h</Text>
                            ) : checkedIn ? (
                              <Text className="text-brand-orange text-xs font-semibold">Active</Text>
                            ) : (
                              <Text className="text-gray-300 text-sm">—</Text>
                            )}
                          </View>
                        </View>
                      );
                    })
                  )}
                </View>
              </ScrollView>
            </>
        </View>
      )}

      {/* Manual Check-in Modal */}
      {showManualModal && (
        <View className="absolute inset-0 bg-black/50 items-center justify-center p-4 z-50">
          <View className="bg-white w-full max-w-md rounded-2xl p-6 shadow-xl">
            <View className="flex-row justify-between items-center mb-6">
              <Text className="text-xl font-bold text-brand-text">Manual Attendance</Text>
              <Pressable onPress={() => setShowManualModal(false)}>
                <Ionicons name="close" size={24} color="#6B7280" />
              </Pressable>
            </View>

            <View className="mb-6">
              <Text className="text-sm font-semibold text-gray-700 mb-2">Select Worker</Text>
              <ScrollView horizontal showsHorizontalScrollIndicator={false} className="flex-row gap-2 pb-2">
                {projectWorkers.map(w => {
                  const att = getAttendanceForWorker(w.id);
                  const isCheckedIn = att?.check_in_time && !att?.check_out_time;
                  return (
                    <Pressable
                      key={w.id}
                      onPress={() => setManualWorkerId(w.id)}
                      className={`px-4 py-3 rounded-xl border ${manualWorkerId === w.id ? 'bg-brand-orange border-brand-orange' : 'bg-gray-50 border-gray-200'}`}
                    >
                      <Text className={`text-sm font-semibold ${manualWorkerId === w.id ? 'text-white' : 'text-gray-600'}`}>
                        {w.full_name || 'Unknown'} {isCheckedIn ? '(Active)' : ''}
                      </Text>
                    </Pressable>
                  );
                })}
              </ScrollView>
            </View>

            <Pressable
              onPress={handleManualCheckIn}
              disabled={!manualWorkerId || manualSubmitting}
              className={`w-full py-4 rounded-xl items-center justify-center ${!manualWorkerId ? 'bg-gray-300' : 'bg-brand-orange'}`}
            >
              {manualSubmitting ? <ActivityIndicator color="white" /> : (
                <Text className="text-white font-bold text-base">
                  {manualWorkerId && getAttendanceForWorker(manualWorkerId)?.check_in_time && !getAttendanceForWorker(manualWorkerId)?.check_out_time ? 'Check Out' : 'Check In'}
                </Text>
              )}
            </Pressable>
          </View>
        </View>
      )}

      {isScanning && <QRScanner onScan={markAttendance} onClose={() => setIsScanning(false)} />}

    </View>
  );
}

import { ModalViewport } from '@/components/common/ModalViewport';
import React, { useEffect, useState } from 'react';
import { View, Text, ScrollView, Pressable, ActivityIndicator, Modal, TextInput, Alert } from 'react-native';
import { supabase } from '../../../lib/supabase';
import { Ionicons, MaterialIcons } from '@expo/vector-icons';
import { useAuth } from '../../../context/AuthContext';
import { TopNav } from '@/components/common/TopNav';
import { NoAssignedSites } from '@/components/common/NoAssignedSites';
import { useAssignedSites } from '@/hooks/useAssignedSites';

export default function SMIssuesPage() {
  const { user } = useAuth();
  const { assignedProjectIds, loading: sitesLoading } = useAssignedSites(user?.id);
  const [loading, setLoading] = useState(true);
  const [issues, setIssues] = useState<any[]>([]);
  const [activeProjectId, setActiveProjectId] = useState<string | null>(null);
  
  // Modal State
  const [showModal, setShowModal] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [severity, setSeverity] = useState<'Low' | 'Medium' | 'High'>('Medium');

  const loadIssues = async () => {
    if (!user?.id || sitesLoading) return;
    
    try {
      setLoading(true);
      if (assignedProjectIds.length === 0) return;

      const currentProjectId = activeProjectId || assignedProjectIds[0];
      if (!activeProjectId) setActiveProjectId(currentProjectId);

      const { data, error } = await supabase
        .from('site_issues')
        .select('*, projects(name)')
        .eq('project_id', currentProjectId)
        .order('created_at', { ascending: false });

      if (error) throw error;
      setIssues(data || []);
    } catch (error: any) {
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadIssues();
  }, [user?.id, sitesLoading, assignedProjectIds, activeProjectId]);

  const handleSubmitIssue = async () => {
    if (!title || !description || !activeProjectId) {
      Alert.alert('Validation Error', 'Please fill in all fields.');
      return;
    }

    setSubmitting(true);
    try {
      const { error } = await supabase.from('site_issues').insert({
        project_id: activeProjectId,
        reporter_name: user?.user_metadata?.full_name || 'Site Manager',
        title,
        description,
        severity,
        status: 'Open'
      });

      if (error) throw error;
      
      Alert.alert('Success', 'Issue reported successfully!');
      setShowModal(false);
      setTitle('');
      setDescription('');
      setSeverity('Medium');
      loadIssues();
    } catch (error: any) {
      Alert.alert('Error', error.message);
    } finally {
      setSubmitting(false);
    }
  };

  const handleResolveIssue = async (issueId: string) => {
    try {
      const { error } = await supabase
        .from('site_issues')
        .update({ status: 'Resolved' })
        .eq('id', issueId);

      if (error) throw error;
      Alert.alert('Success', 'Issue resolved successfully!');
      loadIssues();
    } catch (error: any) {
      Alert.alert('Error', error.message);
    }
  };

  const getSeverityColors = (sev: string) => {
    switch (sev) {
      case 'High': return 'bg-red-50 text-red-700 border-red-100';
      case 'Medium': return 'bg-orange-50 text-orange-700 border-orange-100';
      case 'Low': return 'bg-blue-50 text-blue-700 border-blue-100';
      default: return 'bg-gray-50 text-gray-700 border-gray-100';
    }
  };

  const getStatusColors = (status: string) => {
    switch (status) {
      case 'Resolved': return 'bg-green-50 text-green-700 border-green-100';
      case 'In Progress': return 'bg-blue-50 text-blue-700 border-blue-100';
      case 'Open': return 'bg-orange-50 text-orange-700 border-orange-100';
      default: return 'bg-gray-50 text-gray-700 border-gray-100';
    }
  };

  return (
    <View className="flex-1 bg-brand-light">
      <TopNav title="Site Issues" />

      {loading || sitesLoading ? (
        <View className="flex-1 items-center justify-center">
          <ActivityIndicator size="large" color="#F97316" />
        </View>
      ) : assignedProjectIds.length === 0 ? (
        <NoAssignedSites />
      ) : (
        <View className="flex-1 p-8">
          <View className="flex-row justify-between items-center mb-8">
            <View>
              <Text className="text-3xl font-bold text-brand-text mb-2">Issue Reporting</Text>
              <Text className="text-gray-500">Track and manage site incidents and blockers.</Text>
            </View>
            <Pressable 
              onPress={() => setShowModal(true)}
              className="flex-row items-center bg-brand-orange px-4 py-3 rounded-xl shadow-sm hover:bg-orange-600 transition-colors"
            >
              <Ionicons name="warning-outline" size={20} color="white" className="mr-2" />
              <Text className="text-white font-bold ml-2">Report Issue</Text>
            </Pressable>
          </View>

          <ScrollView showsVerticalScrollIndicator={false}>
            {issues.length === 0 ? (
              <View className="bg-white p-10 rounded-2xl items-center justify-center border border-gray-100">
                <Ionicons name="checkmark-circle-outline" size={48} color="#10B981" />
                <Text className="text-gray-500 mt-4 text-center">No active issues reported. Great job!</Text>
              </View>
            ) : (
              <View className="gap-4">
                {issues.map(issue => (
                  <View key={issue.id} className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100 flex-row justify-between">
                    <View className="flex-1 pr-6 border-r border-gray-100">
                      <Text className="text-lg font-bold text-brand-text mb-2">{issue.title}</Text>
                      <Text className="text-gray-500 text-sm mb-4">{issue.description}</Text>
                      <View className="flex-row items-center gap-3">
                        <View className="flex-row items-center">
                          <MaterialIcons name="person" size={14} color="#9CA3AF" />
                          <Text className="text-xs text-gray-500 ml-1">{issue.reporter_name}</Text>
                        </View>
                        <View className="flex-row items-center">
                          <MaterialIcons name="business" size={14} color="#9CA3AF" />
                          <Text className="text-xs text-gray-500 ml-1">{issue.projects?.name || 'Unknown Site'}</Text>
                        </View>
                      </View>
                    </View>
                    <View className="w-40 pl-6 justify-center gap-3">
                      <View>
                        <Text className="text-[10px] text-gray-400 font-bold uppercase tracking-wider mb-1">Severity</Text>
                        <View className={`px-3 py-1 rounded-full border self-start ${getSeverityColors(issue.severity)}`}>
                          <Text className="font-bold text-xs">{issue.severity}</Text>
                        </View>
                      </View>
                      <View>
                        <Text className="text-[10px] text-gray-400 font-bold uppercase tracking-wider mb-1">Status</Text>
                        <View className={`px-3 py-1 rounded-full border self-start ${getStatusColors(issue.status)}`}>
                          <Text className="font-bold text-xs">{issue.status}</Text>
                        </View>
                      </View>
                      
                      {issue.status !== 'Resolved' && (
                        <Pressable
                          onPress={() => handleResolveIssue(issue.id)}
                          className="mt-2 bg-brand-success px-3 py-2 rounded-lg items-center"
                        >
                          <Text className="text-white text-xs font-bold">Mark Resolved</Text>
                        </Pressable>
                      )}
                    </View>
                  </View>
                ))}
              </View>
            )}
          </ScrollView>
        </View>
      )}

      {/* Report Issue Modal */}
      <Modal visible={showModal} transparent={true} animationType="fade" onRequestClose={() => setShowModal(false)}>
        <ModalViewport>
          <ScrollView keyboardShouldPersistTaps="handled" nestedScrollEnabled style={{ flexGrow: 0, flexShrink: 1 }} contentContainerStyle={{ padding: 24 }} className="bg-white w-full max-w-lg rounded-3xl shadow-xl max-h-full">
            <View className="flex-row justify-between items-center mb-6 border-b border-gray-100 pb-4">
              <Text className="text-xl font-bold text-brand-text">Report New Issue</Text>
              <Pressable onPress={() => setShowModal(false)}>
                <Ionicons name="close" size={24} color="#6B7280" />
              </Pressable>
            </View>

            <View className="mb-4">
              <Text className="text-sm font-semibold text-gray-700 mb-2">Issue Title</Text>
              <TextInput 
                className="w-full border border-gray-300 rounded-xl p-4 text-brand-text focus:border-brand-orange"
                placeholder="e.g. Water leak on 2nd floor"
                value={title}
                onChangeText={setTitle}
              />
            </View>

            <View className="mb-4">
              <Text className="text-sm font-semibold text-gray-700 mb-2">Description</Text>
              <TextInput 
                className="w-full border border-gray-300 rounded-xl p-4 text-brand-text focus:border-brand-orange h-32"
                placeholder="Provide detailed information..."
                multiline
                textAlignVertical="top"
                value={description}
                onChangeText={setDescription}
              />
            </View>

            <View className="mb-8">
              <Text className="text-sm font-semibold text-gray-700 mb-2">Severity</Text>
              <View className="flex-row gap-2">
                {['Low', 'Medium', 'High'].map((s) => (
                  <Pressable 
                    key={s}
                    onPress={() => setSeverity(s as any)}
                    className={`flex-1 py-3 rounded-lg border items-center ${severity === s ? 'border-brand-orange bg-orange-50' : 'border-gray-200 bg-gray-50'}`}
                  >
                    <Text className={`font-bold ${severity === s ? 'text-brand-orange' : 'text-gray-500'}`}>{s}</Text>
                  </Pressable>
                ))}
              </View>
            </View>

            <Pressable 
              onPress={handleSubmitIssue}
              disabled={submitting}
              className={`w-full py-4 rounded-xl items-center justify-center ${submitting ? 'bg-orange-300' : 'bg-brand-orange hover:bg-orange-600 transition-colors'}`}
            >
              {submitting ? (
                <ActivityIndicator color="white" />
              ) : (
                <Text className="text-white font-bold text-lg">Submit Report</Text>
              )}
            </Pressable>
          </ScrollView>
        </ModalViewport>
      </Modal>

    </View>
  );
}

import React, { useEffect, useState } from 'react';
import { View, Text, ScrollView, ActivityIndicator, Pressable, Alert, TextInput } from 'react-native';
import { supabase } from '../../../lib/supabase';
import { TopNav } from '@/components/common/TopNav';
import { Ionicons } from '@expo/vector-icons';
import { NoAssignedSites } from '@/components/common/NoAssignedSites';
import { useAssignedSites } from '@/hooks/useAssignedSites';
import { useAuth } from '@/context/AuthContext';

export default function SMMaterialsPage() {
  const { user } = useAuth();
  const { assignedProjectIds, loading: sitesLoading } = useAssignedSites(user?.id);
  const [loading, setLoading] = useState(true);
  const [projects, setProjects] = useState<any[]>([]);
  const [activeProjectId, setActiveProjectId] = useState<string | null>(null);
  
  const [activeTab, setActiveTab] = useState<'stock' | 'request' | 'deliveries'>('stock');
  const [projectStock, setProjectStock] = useState<any[]>([]);
  const [myRequests, setMyRequests] = useState<any[]>([]);
  const [deliveries, setDeliveries] = useState<any[]>([]);

  // Form State
  const [itemName, setItemName] = useState('');
  const [quantity, setQuantity] = useState('');
  const [unit, setUnit] = useState('units');

  const fetchMaterialsData = async () => {
    if (!user?.id || sitesLoading) return;

    try {
      setLoading(true);

      const { data: projectsData } = assignedProjectIds.length
        ? await supabase.from('projects').select('id, name').in('id', assignedProjectIds).eq('status', 'active')
        : { data: [] };
        
      const parsedProjects = projectsData || [];
      setProjects(parsedProjects);

      if (parsedProjects.length > 0) {
        const currentProject = activeProjectId || parsedProjects[0].id;
        if (!activeProjectId) setActiveProjectId(currentProject);

        // 2. Fetch materials for the active project
        const { data: stockData } = await supabase
          .from('materials')
          .select('*')
          .eq('project_id', currentProject)
          .order('created_at', { ascending: false });
        
        setProjectStock(stockData || []);

        // 3. Fetch past requests by this user
        const { data: reqData } = await supabase
          .from('material_requests')
          .select('*, projects(name)')
          .eq('requested_by', user.id)
          .order('created_at', { ascending: false });

        setMyRequests(reqData || []);

        // 4. Fetch incoming deliveries for this project
        const { data: delData } = await supabase
          .from('purchase_orders')
          .select('*, materials(item_name, unit)')
          .eq('project_id', currentProject)
          .eq('status', 'Delivered')
          .order('actual_delivery', { ascending: false });
          
        setDeliveries(delData || []);
      }
    } catch (error: any) {
      console.error('Error fetching materials data', error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchMaterialsData();
  }, [activeProjectId, activeTab, user?.id, sitesLoading, assignedProjectIds]);

  const handleSubmitRequest = async () => {
    if (!itemName || !quantity || !activeProjectId || !user?.id) {
      Alert.alert('Error', 'Please fill in all fields.');
      return;
    }

    try {
      setLoading(true);
      const { error } = await supabase
        .from('material_requests')
        .insert({
          project_id: activeProjectId,
          requested_by: user.id,
          item_name: itemName,
          quantity: Number(quantity),
          unit: unit,
          status: 'Pending Approval'
        });

      if (error) throw error;
      
      Alert.alert('Success', 'Material request submitted to Project Manager!');
      setItemName('');
      setQuantity('');
      setActiveTab('stock');
      fetchMaterialsData();
    } catch (error: any) {
      Alert.alert('Error', error.message);
    } finally {
      setLoading(false);
    }
  };

  const handleReceiveDelivery = async (poId: string) => {
    try {
      setLoading(true);
      const res = await fetch(`${process.env.EXPO_PUBLIC_API_URL || 'http://localhost:8000/api'}/purchase-orders/${poId}/receive`, {
        method: 'PATCH',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${(await supabase.auth.getSession()).data.session?.access_token}`
        }
      });
      if (!res.ok) throw new Error('Failed to receive delivery');
      Alert.alert('Success', 'Goods received and stock updated!');
      fetchMaterialsData();
    } catch (e: any) {
      Alert.alert('Error', e.message);
    } finally {
      setLoading(false);
    }
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'Pending Approval': return 'bg-yellow-100 text-yellow-800';
      case 'Approved': return 'bg-blue-100 text-blue-800';
      case 'Ordered': return 'bg-purple-100 text-purple-800';
      case 'Delivered': return 'bg-green-100 text-green-800';
      case 'Rejected': return 'bg-red-100 text-red-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  return (
    <View className="flex-1 bg-brand-light">
      <TopNav title="Site Materials" />
      
      {projects.length > 0 && (
        <View className="bg-white px-6 pt-4 border-b border-gray-200">
          <ScrollView horizontal showsHorizontalScrollIndicator={false} className="flex-row">
            {projects.map(project => (
              <Pressable 
                key={project.id}
                onPress={() => setActiveProjectId(project.id)}
                className={`mr-6 pb-3 border-b-2 ${activeProjectId === project.id ? 'border-brand-orange' : 'border-transparent'}`}
              >
                <Text className={`font-bold text-base ${activeProjectId === project.id ? 'text-brand-orange' : 'text-gray-500'}`}>
                  {project.name}
                </Text>
              </Pressable>
            ))}
          </ScrollView>
        </View>
      )}

      {/* Tabs */}
      <View className="flex-row px-8 mt-6">
        <Pressable 
          onPress={() => setActiveTab('stock')}
          className={`pb-3 mr-8 border-b-2 ${activeTab === 'stock' ? 'border-brand-text' : 'border-transparent'}`}
        >
          <Text className={`font-bold text-base ${activeTab === 'stock' ? 'text-brand-text' : 'text-gray-500'}`}>Current Stock</Text>
        </Pressable>
        <Pressable 
          onPress={() => setActiveTab('request')}
          className={`pb-3 mr-8 border-b-2 ${activeTab === 'request' ? 'border-brand-text' : 'border-transparent'}`}
        >
          <Text className={`font-bold text-base ${activeTab === 'request' ? 'text-brand-text' : 'text-gray-500'}`}>Request Materials</Text>
        </Pressable>
        <Pressable 
          onPress={() => setActiveTab('deliveries')}
          className={`pb-3 border-b-2 ${activeTab === 'deliveries' ? 'border-brand-text' : 'border-transparent'}`}
        >
          <Text className={`font-bold text-base ${activeTab === 'deliveries' ? 'text-brand-text' : 'text-gray-500'}`}>Incoming Deliveries</Text>
        </Pressable>
      </View>

      <View className="flex-1 p-8">
        {loading || sitesLoading ? (
          <ActivityIndicator size="large" color="#F97316" style={{ marginTop: 40 }} />
        ) : assignedProjectIds.length === 0 ? (
          <NoAssignedSites />
        ) : activeTab === 'stock' ? (
          <View className="bg-white rounded-2xl shadow-sm border border-gray-100 flex-1 overflow-hidden">
            <View className="flex-row py-4 px-6 border-b border-gray-100 bg-gray-50">
              <Text className="flex-[2] text-xs font-bold text-gray-500 uppercase">Item Name</Text>
              <Text className="flex-1 text-xs font-bold text-gray-500 uppercase">Stock</Text>
              <Text className="flex-1 text-xs font-bold text-gray-500 uppercase">Status</Text>
            </View>

            <ScrollView showsVerticalScrollIndicator={false}>
              {projectStock.length === 0 ? (
                <View className="p-10 items-center justify-center">
                  <Ionicons name="cube-outline" size={48} color="#D1D5DB" />
                  <Text className="text-gray-400 mt-4">No materials recorded for this project yet.</Text>
                </View>
              ) : (
                projectStock.map(item => {
                  const isLow = (item.current_stock || 0) < (item.minimum_threshold || 0);
                  return (
                    <View key={item.id} className="flex-row items-center py-4 px-6 border-b border-gray-50">
                      <View className="flex-[2]">
                        <Text className="font-bold text-brand-text">{item.item_name}</Text>
                        <Text className="text-gray-400 text-xs">{item.unit}</Text>
                      </View>
                      <View className="flex-1">
                        <Text className={`font-bold ${isLow ? 'text-red-500' : 'text-brand-text'}`}>
                          {item.current_stock ?? 0}
                        </Text>
                      </View>
                      <View className="flex-1">
                        <View className={`self-start px-2 py-1 rounded ${isLow ? 'bg-red-100' : 'bg-green-100'}`}>
                          <Text className={`text-xs font-bold ${isLow ? 'text-red-700' : 'text-green-700'}`}>
                            {isLow ? 'Low Stock' : 'OK'}
                          </Text>
                        </View>
                      </View>
                    </View>
                  );
                })
              )}
            </ScrollView>
          </View>
        ) : activeTab === 'request' ? (
          <ScrollView showsVerticalScrollIndicator={false} className="flex-1">
            <View className="bg-white rounded-2xl shadow-sm border border-gray-100 p-8 mb-8">
              <Text className="text-xl font-bold text-gray-800 mb-6">New Material Request</Text>
              
              <View>
                <View className="mb-4">
                  <Text className="text-sm font-bold text-gray-700 mb-2">Item Name</Text>
                  <TextInput
                    value={itemName}
                    onChangeText={setItemName}
                    placeholder="e.g. Portland Cement"
                    className="border border-gray-200 rounded-xl p-4 bg-gray-50"
                  />
                </View>

                <View className="flex-row gap-4 mb-4">
                  <View className="flex-[2]">
                    <Text className="text-sm font-bold text-gray-700 mb-2">Quantity</Text>
                    <TextInput
                      value={quantity}
                      onChangeText={setQuantity}
                      placeholder="e.g. 50"
                      keyboardType="numeric"
                      className="border border-gray-200 rounded-xl p-4 bg-gray-50"
                    />
                  </View>
                  <View className="flex-1">
                    <Text className="text-sm font-bold text-gray-700 mb-2">Unit</Text>
                    <TextInput
                      value={unit}
                      onChangeText={setUnit}
                      placeholder="bags, tons..."
                      className="border border-gray-200 rounded-xl p-4 bg-gray-50"
                    />
                  </View>
                </View>

                <Pressable 
                  onPress={handleSubmitRequest}
                  className="bg-brand-orange py-4 rounded-xl mt-4 items-center"
                >
                  <Text className="text-white font-bold text-base">Submit Request to PM</Text>
                </Pressable>
              </View>
            </View>

            {/* Request History */}
            <Text className="text-lg font-bold text-gray-800 mb-4 px-2">My Recent Requests</Text>
            {myRequests.slice(0, 5).map(req => (
              <View key={req.id} className="bg-white p-4 rounded-xl border border-gray-200 mb-3 flex-row items-center justify-between shadow-sm">
                <View>
                  <Text className="font-bold text-gray-800">{req.item_name}</Text>
                  <Text className="text-gray-500 text-xs mt-1">{req.quantity} {req.unit} • {req.projects?.name}</Text>
                </View>
                <View className={`px-2.5 py-1 rounded-md ${getStatusColor(req.status).split(' ')[0]}`}>
                  <Text className={`text-xs font-bold ${getStatusColor(req.status).split(' ')[1]}`}>{req.status}</Text>
                </View>
              </View>
            ))}
          </ScrollView>
        ) : (
          <ScrollView showsVerticalScrollIndicator={false} className="flex-1">
            <Text className="text-xl font-bold text-brand-text mb-6">Incoming Deliveries</Text>
            {deliveries.length === 0 ? (
              <View className="p-10 items-center justify-center bg-white rounded-2xl border border-gray-100">
                <Ionicons name="checkmark-done-circle-outline" size={48} color="#D1D5DB" />
                <Text className="text-gray-400 mt-4 font-medium">No pending deliveries for this project.</Text>
              </View>
            ) : (
              deliveries.map(del => (
                <View key={del.id} className="bg-white p-6 rounded-2xl border border-gray-200 mb-4 flex-row items-center justify-between shadow-sm">
                  <View className="flex-1">
                    <Text className="font-bold text-lg text-brand-text">{del.po_number}</Text>
                    <Text className="text-gray-500 text-sm mt-1">{del.materials?.item_name} • {del.quantity_ordered} {del.materials?.unit}</Text>
                    <Text className="text-gray-400 text-xs mt-1">Dispatched: {del.actual_delivery}</Text>
                  </View>
                  <Pressable 
                    onPress={() => handleReceiveDelivery(del.id)}
                    className="bg-brand-success px-4 py-2 rounded-lg"
                  >
                    <Text className="text-white font-bold">Confirm Receipt</Text>
                  </Pressable>
                </View>
              ))
            )}
          </ScrollView>
        )}
      </View>
    </View>
  );
}

import React, { useEffect, useState } from 'react';
import {
  View, Text, ScrollView, TextInput, Pressable,
  ActivityIndicator, Platform, Alert,
} from 'react-native';
import { TopNav } from '@/components/common/TopNav';
import { Ionicons } from '@expo/vector-icons';
import { supabase } from '../../../lib/supabase';
import { api } from '../../../services/api';
import { useRouter } from 'expo-router';
import { NoAssignedSites } from '@/components/common/NoAssignedSites';
import { useAssignedSites } from '@/hooks/useAssignedSites';
import { useAuth } from '@/context/AuthContext';

type Project = { id: string; name: string; siteId: string };

export default function CreateSiteReportPage() {
  const router = useRouter();
  const { user } = useAuth();
  const { assignedProjectIds, assignments, loading: sitesLoading } = useAssignedSites(user?.id);
  const [loading, setLoading] = useState(false);
  const [projectsLoading, setProjectsLoading] = useState(true);
  const [projects, setProjects] = useState<Project[]>([]);
  const [selectedProjectId, setSelectedProjectId] = useState<string | null>(null);

  // Form state
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [workCompleted, setWorkCompleted] = useState('');
  const [workerCount, setWorkerCount] = useState('');
  const [blockers, setBlockers] = useState('');
  const [photoUrls, setPhotoUrls] = useState<string[]>([]);
  const [photoUploading, setPhotoUploading] = useState(false);
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [submitted, setSubmitted] = useState(false);

  useEffect(() => {
    const loadProjects = async () => {
      if (!user?.id || sitesLoading) return;

      try {
        if (!assignedProjectIds.length) {
          setProjectsLoading(false);
          return;
        }

        const { data: projectsData } = await supabase
          .from('projects')
          .select('id, name')
          .in('id', assignedProjectIds)
          .eq('status', 'active');

        const parsed: Project[] = (projectsData || []).map((p: any) => {
          const assignment = assignments.find((a: any) => a.projectId === p.id);
          return { id: p.id, name: p.name, siteId: assignment?.assignmentId || '' };
        });
        setProjects(parsed);
        if (parsed.length > 0) setSelectedProjectId(parsed[0].id);
      } catch (error) {
        console.error('Failed to load projects', error);
      } finally {
        setProjectsLoading(false);
      }
    };
    loadProjects();
  }, [user?.id, sitesLoading, assignedProjectIds, assignments]);

  const validate = () => {
    const errs: Record<string, string> = {};
    if (!selectedProjectId) errs.project = 'Please select a project';
    if (!workCompleted.trim()) errs.workCompleted = 'Work completed is required';
    if (!date) errs.date = 'Date is required';
    setErrors(errs);
    return Object.keys(errs).length === 0;
  };

  const uploadPhoto = async () => {
    // Placeholder: In a real implementation, use expo-image-picker + POST /api/media/upload.
    // For now we show a demo URL input prompt.
    if (Platform.OS === 'web') {
      const url = window.prompt('Paste a Cloudinary photo URL:');
      if (url) setPhotoUrls(prev => [...prev, url]);
    } else {
      Alert.alert('Photo Upload', 'Use the web interface to attach photos, or integrate expo-image-picker.', [{ text: 'OK' }]);
    }
  };

  const handleSubmit = async () => {
    if (!validate()) return;

    const selectedProject = projects.find(p => p.id === selectedProjectId);
    if (!selectedProject) return;

    setLoading(true);
    try {
      await api.siteReports.create({
        project_id: selectedProjectId,
        site_id: selectedProject.siteId || undefined,
        date,
        work_completed: workCompleted.trim(),
        workers_present_count: workerCount ? parseInt(workerCount, 10) : undefined,
        blockers: blockers.trim() || undefined,
        photos: photoUrls.length > 0 ? photoUrls : undefined,
        materials_used: undefined,
      });

      setSubmitted(true);
      setTimeout(() => router.back(), 1800);
    } catch (error: any) {
      const msg = error.message || 'Failed to submit report';
      if (Platform.OS === 'web') {
        window.alert(msg);
      } else {
        Alert.alert('Error', msg);
      }
    } finally {
      setLoading(false);
    }
  };

  if (submitted) {
    return (
      <View className="flex-1 bg-brand-light items-center justify-center p-8">
        <View className="bg-white rounded-2xl p-10 items-center shadow-sm border border-gray-100 w-full max-w-md">
          <View className="w-16 h-16 bg-green-100 rounded-full items-center justify-center mb-4">
            <Ionicons name="checkmark" size={36} color="#22C55E" />
          </View>
          <Text className="text-2xl font-bold text-brand-text mb-2">Report Submitted!</Text>
          <Text className="text-gray-500 text-center">Your daily site report has been submitted. The PM will be notified.</Text>
        </View>
      </View>
    );
  }

  return (
    <View className="flex-1 bg-brand-light">
      <TopNav title="New Site Report" showAction={false} />

      {projectsLoading || sitesLoading ? (
        <View className="flex-1 items-center justify-center">
          <ActivityIndicator size="large" color="#F97316" />
        </View>
      ) : assignedProjectIds.length === 0 ? (
        <NoAssignedSites />
      ) : (
        <ScrollView className="flex-1 p-6" showsVerticalScrollIndicator={false}>
          <View className="bg-white rounded-2xl shadow-sm border border-gray-100 p-6 mb-6">

            {/* Project picker */}
            <Text className="text-sm font-bold text-gray-700 mb-1">Project <Text className="text-red-500">*</Text></Text>
            <ScrollView horizontal showsHorizontalScrollIndicator={false} className="flex-row mb-5">
              {projects.map(p => (
                <Pressable
                  key={p.id}
                  onPress={() => setSelectedProjectId(p.id)}
                  className={`mr-3 px-4 py-2 rounded-full border ${selectedProjectId === p.id ? 'bg-brand-orange border-brand-orange' : 'border-gray-200 bg-gray-50'}`}
                >
                  <Text className={`font-semibold text-sm ${selectedProjectId === p.id ? 'text-white' : 'text-gray-600'}`}>{p.name}</Text>
                </Pressable>
              ))}
            </ScrollView>
            {errors.project && <Text className="text-red-500 text-xs mb-3">{errors.project}</Text>}

            {/* Date */}
            <Text className="text-sm font-bold text-gray-700 mb-1">Report Date <Text className="text-red-500">*</Text></Text>
            <TextInput
              className={`border ${errors.date ? 'border-red-400' : 'border-gray-300'} rounded-xl p-3 mb-5 text-brand-text bg-gray-50`}
              value={date}
              onChangeText={setDate}
              placeholder="YYYY-MM-DD"
            />
            {errors.date && <Text className="text-red-500 text-xs -mt-4 mb-3">{errors.date}</Text>}

            {/* Work completed */}
            <Text className="text-sm font-bold text-gray-700 mb-1">Work Completed Today <Text className="text-red-500">*</Text></Text>
            <TextInput
              className={`border ${errors.workCompleted ? 'border-red-400' : 'border-gray-300'} rounded-xl p-3 mb-5 text-brand-text bg-gray-50 min-h-[100px]`}
              multiline
              textAlignVertical="top"
              value={workCompleted}
              onChangeText={setWorkCompleted}
              placeholder="Describe the work completed today in detail..."
            />
            {errors.workCompleted && <Text className="text-red-500 text-xs -mt-4 mb-3">{errors.workCompleted}</Text>}

            {/* Worker count */}
            <Text className="text-sm font-bold text-gray-700 mb-1">Workers Present</Text>
            <TextInput
              className="border border-gray-300 rounded-xl p-3 mb-5 text-brand-text bg-gray-50"
              keyboardType="number-pad"
              value={workerCount}
              onChangeText={setWorkerCount}
              placeholder="Number of workers on site today"
            />

            {/* Blockers / Issues */}
            <Text className="text-sm font-bold text-gray-700 mb-1">Blockers / Issues</Text>
            <TextInput
              className="border border-gray-300 rounded-xl p-3 mb-5 text-brand-text bg-gray-50 min-h-[80px]"
              multiline
              textAlignVertical="top"
              value={blockers}
              onChangeText={setBlockers}
              placeholder="Any blockers, safety issues, or delays? Leave blank if none."
            />

            {/* Photos */}
            <Text className="text-sm font-bold text-gray-700 mb-1">Photos</Text>
            {photoUrls.map((url, i) => (
              <View key={i} className="flex-row items-center bg-blue-50 rounded-lg p-2 mb-2">
                <Ionicons name="image-outline" size={14} color="#3B82F6" />
                <Text className="text-blue-700 text-xs ml-2 flex-1" numberOfLines={1}>{url}</Text>
                <Pressable onPress={() => setPhotoUrls(prev => prev.filter((_, idx) => idx !== i))}>
                  <Ionicons name="close-circle" size={16} color="#9CA3AF" />
                </Pressable>
              </View>
            ))}
            <Pressable
              onPress={uploadPhoto}
              disabled={photoUploading}
              className="border border-dashed border-gray-300 rounded-xl py-4 items-center mb-6"
            >
              {photoUploading ? (
                <ActivityIndicator color="#F97316" />
              ) : (
                <>
                  <Ionicons name="cloud-upload-outline" size={24} color="#9CA3AF" />
                  <Text className="text-gray-500 text-sm mt-2">Tap to attach photo</Text>
                </>
              )}
            </Pressable>

            {/* Submit */}
            <Pressable
              onPress={handleSubmit}
              disabled={loading}
              className={`py-4 rounded-xl items-center ${loading ? 'bg-orange-300' : 'bg-brand-orange'}`}
            >
              {loading ? (
                <ActivityIndicator color="white" />
              ) : (
                <Text className="text-white font-bold text-base">Submit Report</Text>
              )}
            </Pressable>

          </View>
        </ScrollView>
      )}
    </View>
  );
}

import React, { useEffect, useState } from 'react';
import { View, Text, ScrollView, ActivityIndicator, Pressable, Alert } from 'react-native';
import { supabase } from '../../../lib/supabase';
import { TopNav } from '@/components/common/TopNav';
import { Ionicons } from '@expo/vector-icons';
import { QRScanner } from '@/components/worker/QRScanner';
import { NoAssignedSites } from '@/components/common/NoAssignedSites';
import { useAssignedSites } from '@/hooks/useAssignedSites';
import { useAuth } from '@/context/AuthContext';

export default function SMTeamPage() {
  const { user } = useAuth();
  const { assignedProjectIds, assignments, loading: sitesLoading } = useAssignedSites(user?.id);
  const [loading, setLoading] = useState(true);
  const [sites, setSites] = useState<any[]>([]);
  const [workers, setWorkers] = useState<any[]>([]);

  // Assignment Modal
  const [isAssigning, setIsAssigning] = useState(false);
  const [selectedSiteId, setSelectedSiteId] = useState<string | null>(null);

  const fetchTeamData = async () => {
    if (!user?.id || sitesLoading) return;

    try {
      setLoading(true);

      if (assignedProjectIds.length > 0) {
        const { data: projectsData } = await supabase
          .from('projects')
          .select('id, name, location')
          .in('id', assignedProjectIds);

        const parsedSites = projectsData?.map((p: any) => {
          const assignment = assignments.find((a: any) => a.projectId === p.id);
          return { id: p.id, siteId: assignment?.assignmentId, name: p.name, location: p.location };
        }) || [];
        setSites(parsedSites);
        
        // 2. Fetch workers assigned to these projects
        const { data: assignData, error: assignErr } = await supabase
          .from('site_workers')
          .select('*, profiles!inner(id, full_name)')
          .in('project_id', assignedProjectIds);
        if (assignErr) throw assignErr;
        setWorkers(assignData || []);
      }

    } catch (error: any) {
      console.error('Error fetching team data', error);
      Alert.alert('Error', error.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchTeamData();
  }, [user?.id, sitesLoading, assignedProjectIds, assignments]);

  const handleScanQR = async (qrCode: string) => {
    if (!selectedSiteId || !user?.id) return;
    try {
      const { data: worker, error: workerError } = await supabase
        .from('profiles')
        .select('id, full_name')
        .eq('role', 'worker')
        .eq('qr_code', qrCode)
        .single();
      if (workerError) throw workerError;

      const { error } = await supabase
        .from('site_workers')
        .insert({
          project_id: selectedSiteId,
          worker_id: worker.id,
          site_manager_id: user.id
        });

      if (error) {
        if (error.code === '23505') {
          Alert.alert('Notice', 'This Worker is already assigned to this site.');
        } else {
          throw error;
        }
      } else {
        Alert.alert('Success', `${worker.full_name || 'Worker'} assigned successfully!`);
        setIsAssigning(false);
        setSelectedSiteId(null);
        fetchTeamData();
      }
    } catch (error: any) {
      Alert.alert('Error', error.message);
    }
  };

  const handleRemoveWorker = async (assignmentId: string) => {
    try {
      const { error } = await supabase
        .from('site_workers')
        .delete()
        .eq('id', assignmentId);
      if (error) throw error;
      fetchTeamData();
    } catch (error: any) {
      Alert.alert('Error', error.message);
    }
  };

  return (
    <View className="flex-1 bg-gray-50">
      <TopNav title="Worker Management" />
      
      {loading || sitesLoading ? (
        <View className="flex-1 items-center justify-center">
          <ActivityIndicator size="large" color="#F97316" />
        </View>
      ) : assignedProjectIds.length === 0 ? (
        <NoAssignedSites />
      ) : (
        <ScrollView className="flex-1 p-8" showsVerticalScrollIndicator={false}>
          
          <View className="mb-6 flex-row justify-between items-center">
            <Text className="text-2xl font-bold text-gray-800">Assigned Site Workers</Text>
          </View>

          {sites.length === 0 ? (
            <View className="bg-white p-12 rounded-xl border border-gray-200 items-center justify-center shadow-sm">
              <Ionicons name="alert-circle-outline" size={48} color="#D1D5DB" className="mb-4" />
              <Text className="text-gray-400 text-lg font-medium text-center">You have no assigned sites.</Text>
              <Text className="text-gray-400 text-sm mt-2 text-center">Please contact your Project Manager for site assignments.</Text>
            </View>
          ) : (
          <View className="space-y-6">
              {sites.map(site => {
                const siteWorkers = workers.filter(w => w.project_id === site.id);

                return (
                  <View key={site.id} className="bg-white p-6 rounded-xl border border-gray-200 shadow-sm">
                    <View className="flex-row justify-between items-center mb-4 border-b border-gray-100 pb-4">
                      <View>
                        <Text className="text-xl font-bold text-gray-800">{site.name}</Text>
                        <Text className="text-gray-500 text-sm">{site.location || 'Unknown Location'}</Text>
                      </View>
                      
                      <Pressable 
                        onPress={() => {
                          setSelectedSiteId(site.id);
                          setIsAssigning(true);
                        }}
                        className="bg-brand-orange px-4 py-2 rounded-lg flex-row items-center"
                      >
                        <Ionicons name="qr-code-outline" size={16} color="white" className="mr-2" />
                        <Text className="text-white font-bold ml-2">Scan Worker QR</Text>
                      </Pressable>
                    </View>

                    {siteWorkers.length === 0 ? (
                      <View className="py-8 items-center justify-center bg-gray-50 rounded-lg border border-dashed border-gray-300">
                        <Ionicons name="construct-outline" size={32} color="#9CA3AF" />
                        <Text className="text-gray-400 mt-2 text-sm">No workers currently assigned to this site.</Text>
                      </View>
                    ) : (
                      <View className="space-y-3 mt-2">
                        <View className="flex-row py-2 px-4 border-b border-gray-100 bg-gray-50 rounded-t-lg">
                          <Text className="flex-[2] text-xs font-bold text-gray-500 uppercase">Worker Name</Text>
                          <Text className="flex-1 text-xs font-bold text-gray-500 uppercase">Status</Text>
                          <Text className="w-20 text-xs font-bold text-gray-500 uppercase text-right">Actions</Text>
                        </View>
                        {siteWorkers.map((worker) => (
                          <View key={worker.id} className="flex-row items-center p-4 bg-white border border-gray-100 rounded-lg hover:bg-gray-50">
                            <View className="flex-[2] flex-row items-center">
                              <View className="w-8 h-8 bg-orange-100 rounded-full items-center justify-center mr-3">
                                <Ionicons name="person" size={14} color="#F97316" />
                              </View>
                              <Text className="text-gray-800 font-bold">{worker.profiles?.full_name || 'Unknown Worker'}</Text>
                            </View>
                            
                            <View className="flex-1">
                              <Text className="text-green-600 text-xs font-bold bg-green-100 px-2 py-1 rounded self-start">Active</Text>
                            </View>

                            <View className="w-20 items-end">
                              <Pressable onPress={() => handleRemoveWorker(worker.id)}>
                                <Ionicons name="trash-outline" size={20} color="#EF4444" />
                              </Pressable>
                            </View>
                          </View>
                        ))}
                      </View>
                    )}
                  </View>
                );
              })}
            </View>
          )}
        </ScrollView>
      )}

      {isAssigning && <QRScanner onScan={handleScanQR} onClose={() => setIsAssigning(false)} />}

    </View>
  );
}

import { ModalViewport } from '@/components/common/ModalViewport';
import React, { useEffect, useState } from 'react';
import { View, Text, ScrollView, Pressable, ActivityIndicator, Alert, Modal, TextInput } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { supabase } from '../../lib/supabase';
import { useAuth } from '../../context/AuthContext';
import { TopNav } from '@/components/common/TopNav';

export default function SiteMaterials() {
  const { user } = useAuth();
  
  const [requests, setRequests] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  
  // New Request Modal State
  const [showModal, setShowModal] = useState(false);
  const [projects, setProjects] = useState<any[]>([]);
  const [selectedProjectId, setSelectedProjectId] = useState<string>('');
  const [itemName, setItemName] = useState('');
  const [quantity, setQuantity] = useState('');
  const [unit, setUnit] = useState('pcs');
  const [submitting, setSubmitting] = useState(false);

  const [searchQuery, setSearchQuery] = useState('');

  const loadData = async () => {
    setLoading(true);
    try {
      // Load user's requests
      let query = supabase
        .from('material_requests')
        .select('*, projects(name)')
        .eq('requested_by', user?.id)
        .order('created_at', { ascending: false });
        
      if (searchQuery) {
        query = query.ilike('item_name', `%${searchQuery}%`);
      }

      const { data: reqData } = await query;
      setRequests(reqData || []);

      // Load active projects for dropdown
      const { data: projData } = await supabase.from('projects').select('id, name').eq('status', 'active');
      if (projData) {
        setProjects(projData);
        if (projData.length > 0 && !selectedProjectId) {
          setSelectedProjectId(projData[0].id);
        }
      }
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (user) loadData();
  }, [user, searchQuery]);

  const handleSubmitRequest = async () => {
    if (!itemName || !quantity || !selectedProjectId) {
      Alert.alert('Error', 'Please fill all required fields');
      return;
    }

    setSubmitting(true);
    try {
      // 1. Insert request
      const { error } = await supabase.from('material_requests').insert({
        project_id: selectedProjectId,
        requested_by: user?.id,
        item_name: itemName,
        quantity: parseFloat(quantity),
        unit: unit,
        status: 'Pending Approval'
      });

      if (error) throw error;

      // 2. Trigger notification to PM
      await supabase.from('notifications').insert({
        project_id: selectedProjectId,
        target_role: 'Project Manager',
        title: 'New Material Request',
        message: `Site Manager requested ${quantity} ${unit} of ${itemName}. Pending your approval.`,
      });

      Alert.alert('Success', 'Material request submitted to Project Manager.');
      setShowModal(false);
      setItemName('');
      setQuantity('');
      loadData();
    } catch (e: any) {
      Alert.alert('Error', e.message);
    } finally {
      setSubmitting(false);
    }
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'Pending Approval': return 'bg-yellow-100 text-yellow-800';
      case 'Approved': return 'bg-blue-100 text-blue-800';
      case 'Ordered': return 'bg-purple-100 text-purple-800';
      case 'Delivered': return 'bg-green-100 text-green-800';
      case 'Rejected': return 'bg-red-100 text-red-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  return (
    <View className="flex-1 bg-brand-light">
      <TopNav 
        title="Material Requests" 
        actionLabel="+ Request Material" 
        onActionPress={() => setShowModal(true)} 
        initialSearchQuery={searchQuery}
        onSearch={setSearchQuery}
      />

      <View className="flex-1 p-8">
        {loading ? (
          <ActivityIndicator size="large" color="#F97316" className="mt-10" />
        ) : (
          <View className="bg-white rounded-2xl shadow-sm border border-gray-100 flex-1 overflow-hidden">
            <View className="flex-row py-4 px-6 border-b border-gray-100 bg-gray-50">
              <Text className="w-1/4 text-xs font-bold text-gray-500 uppercase">Item</Text>
              <Text className="w-1/4 text-xs font-bold text-gray-500 uppercase">Project</Text>
              <Text className="w-1/4 text-xs font-bold text-gray-500 uppercase">Quantity</Text>
              <Text className="w-1/4 text-xs font-bold text-gray-500 uppercase text-right">Status</Text>
            </View>

            <ScrollView showsVerticalScrollIndicator={false}>
              {requests.length === 0 ? (
                <View className="p-10 items-center justify-center">
                  <Ionicons name="cart-outline" size={48} color="#D1D5DB" />
                  <Text className="text-gray-400 mt-4">No material requests found.</Text>
                </View>
              ) : (
                requests.map(req => (
                  <View key={req.id} className="flex-row items-center py-4 px-6 border-b border-gray-50 hover:bg-gray-50 transition-colors">
                    <View className="w-1/4">
                      <Text className="font-bold text-brand-text">{req.item_name}</Text>
                      <Text className="text-xs text-gray-400 mt-1">{new Date(req.created_at).toLocaleDateString()}</Text>
                    </View>
                    <View className="w-1/4">
                      <Text className="text-gray-500 text-sm">{req.projects?.name || 'Unknown'}</Text>
                    </View>
                    <View className="w-1/4">
                      <Text className="text-brand-text font-semibold">{req.quantity} {req.unit}</Text>
                    </View>
                    <View className="w-1/4 flex-row justify-end">
                      <View className={`px-3 py-1 rounded-full ${getStatusColor(req.status).split(' ')[0]}`}>
                        <Text className={`text-xs font-bold ${getStatusColor(req.status).split(' ')[1]}`}>{req.status}</Text>
                      </View>
                    </View>
                  </View>
                ))
              )}
            </ScrollView>
          </View>
        )}
      </View>

      {/* New Request Modal */}
      <Modal visible={showModal} transparent animationType="slide" onRequestClose={() => setShowModal(false)}>
        <ModalViewport>
          <ScrollView keyboardShouldPersistTaps="handled" nestedScrollEnabled style={{ flexGrow: 0, flexShrink: 1 }} contentContainerStyle={{ padding: 0 }} className="bg-white w-full max-w-md rounded-2xl overflow-hidden shadow-2xl max-h-full">
            <View className="p-6 border-b border-gray-100 flex-row justify-between items-center bg-brand-light">
              <Text className="text-xl font-bold text-brand-text">Request Material</Text>
              <Pressable onPress={() => !submitting && setShowModal(false)}>
                <Ionicons name="close" size={24} color="#6B7280" />
              </Pressable>
            </View>
            
            <View className="p-6">
              <Text className="text-sm font-semibold text-gray-700 mb-2">Target Project</Text>
              <View className="border border-gray-200 rounded-xl mb-4 overflow-hidden max-h-32">
                <ScrollView nestedScrollEnabled>
                  {projects.map(p => (
                    <Pressable 
                      key={p.id}
                      onPress={() => setSelectedProjectId(p.id)}
                      className={`p-3 border-b border-gray-100 ${selectedProjectId === p.id ? 'bg-orange-50' : 'bg-white'}`}
                    >
                      <Text className={selectedProjectId === p.id ? 'text-brand-orange font-bold' : 'text-gray-600'}>
                        {p.name}
                      </Text>
                    </Pressable>
                  ))}
                </ScrollView>
              </View>

              <Text className="text-sm font-semibold text-gray-700 mb-2">Item Name</Text>
              <TextInput
                className="border border-gray-200 rounded-xl p-3 text-brand-text bg-gray-50 mb-4"
                placeholder="e.g. Steel Rebar 12mm"
                value={itemName}
                onChangeText={setItemName}
              />

              <View className="flex-row gap-4 mb-6">
                <View className="flex-1">
                  <Text className="text-sm font-semibold text-gray-700 mb-2">Quantity</Text>
                  <TextInput
                    className="border border-gray-200 rounded-xl p-3 text-brand-text bg-gray-50"
                    placeholder="0"
                    keyboardType="numeric"
                    value={quantity}
                    onChangeText={setQuantity}
                  />
                </View>
                <View className="flex-1">
                  <Text className="text-sm font-semibold text-gray-700 mb-2">Unit</Text>
                  <TextInput
                    className="border border-gray-200 rounded-xl p-3 text-brand-text bg-gray-50"
                    placeholder="Bags, Tons, Liters..."
                    value={unit}
                    onChangeText={setUnit}
                  />
                </View>
              </View>

              <Pressable 
                onPress={handleSubmitRequest}
                disabled={submitting}
                className={`py-3 rounded-xl flex-row items-center justify-center ${submitting ? 'bg-orange-300' : 'bg-brand-orange hover:bg-orange-600'}`}
              >
                {submitting ? (
                  <ActivityIndicator size="small" color="white" />
                ) : (
                  <Text className="text-white font-bold text-lg">Submit Request</Text>
                )}
              </Pressable>
            </View>
          </ScrollView>
        </ModalViewport>
      </Modal>

    </View>
  );
}

import { ModalViewport } from '@/components/common/ModalViewport';
import React, { useEffect, useState } from 'react';
import { View, Text, ScrollView, Pressable, ActivityIndicator, Image, Alert, TextInput, Modal, Platform } from 'react-native';
import { supabase } from '../../lib/supabase';
import { Ionicons } from '@expo/vector-icons';
import { useAuth } from '../../context/AuthContext';
import * as ImagePicker from 'expo-image-picker';
import { decode } from 'base64-arraybuffer';
import { useResponsive } from '../../hooks/useResponsive';

export default function SitePhotos() {
  const { user } = useAuth();
  const { isMobile } = useResponsive();
  const [loading, setLoading] = useState(true);
  const [photos, setPhotos] = useState<any[]>([]);
  
  // Upload Modal State
  const [uploading, setUploading] = useState(false);
  const [showUploadModal, setShowUploadModal] = useState(false);
  const [selectedImage, setSelectedImage] = useState<ImagePicker.ImagePickerAsset | null>(null);
  const [description, setDescription] = useState('');
  
  // Projects State for Dropdown
  const [projects, setProjects] = useState<any[]>([]);
  const [selectedProjectId, setSelectedProjectId] = useState<string | null>(null);

  const loadPhotos = async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase
        .from('site_photos')
        .select('*, projects(name)')
        .order('created_at', { ascending: false });

      if (error) throw error;
      setPhotos(data || []);
    } catch (error: any) {
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  const loadProjects = async () => {
    try {
      const { data, error } = await supabase.from('projects').select('id, name').eq('status', 'active');
      if (!error && data) setProjects(data);
    } catch (e) {}
  };

  useEffect(() => {
    loadPhotos();
    loadProjects();
  }, []);

  const handlePickPhoto = async () => {
    const permissionResult = await ImagePicker.requestMediaLibraryPermissionsAsync();
    
    if (permissionResult.granted === false) {
      Alert.alert('Permission to access camera roll is required!');
      return;
    }

    const pickerResult = await ImagePicker.launchImageLibraryAsync({
      mediaTypes: ['images'],
      allowsEditing: true,
      quality: 0.5,
      base64: true, // Request base64 for easy upload on React Native
    });

    if (!pickerResult.canceled && pickerResult.assets.length > 0) {
      setSelectedImage(pickerResult.assets[0]);
      setDescription('');
      setSelectedProjectId(projects.length > 0 ? projects[0].id : null);
      setShowUploadModal(true);
    }
  };

  const executeUpload = async () => {
    if (!selectedImage || !selectedProjectId) {
      Alert.alert('Error', 'Please select a project first.');
      return;
    }

    setUploading(true);
    try {
      // 1. Upload to Supabase Storage
      const fileExt = selectedImage.uri.split('.').pop() || 'jpeg';
      const fileName = `${Date.now()}_${Math.random().toString(36).substring(7)}.${fileExt}`;
      const filePath = `site_uploads/${fileName}`;

      let uploadError;
      
      if (Platform.OS === 'web') {
        // Web: Fetch Blob and upload
        const response = await fetch(selectedImage.uri);
        const blob = await response.blob();
        const { error } = await supabase.storage.from('project-images').upload(filePath, blob, {
          contentType: `image/${fileExt === 'png' ? 'png' : 'jpeg'}`
        });
        uploadError = error;
      } else {
        // React Native (iOS/Android): Use base64
        if (!selectedImage.base64) throw new Error("Could not read image data.");
        const { error } = await supabase.storage.from('project-images').upload(filePath, decode(selectedImage.base64), {
          contentType: `image/${fileExt === 'png' ? 'png' : 'jpeg'}`
        });
        uploadError = error;
      }

      if (uploadError) throw uploadError;

      // 2. Get Public URL
      const { data: publicUrlData } = supabase.storage.from('project-images').getPublicUrl(filePath);
      const publicUrl = publicUrlData.publicUrl;

      // 3. Save to Database
      const { error: dbError } = await supabase.from('site_photos').insert({
        project_id: selectedProjectId,
        uploader_name: user?.user_metadata?.full_name || 'Site Manager',
        photo_url: publicUrl,
        description: description || 'Progress Photo'
      });

      if (dbError) throw dbError;

      Alert.alert('Success', 'Photo uploaded and saved to cloud successfully!');
      setShowUploadModal(false);
      setSelectedImage(null);
      loadPhotos();
    } catch (error: any) {
      Alert.alert('Upload Error', error.message || 'Ensure the project-images bucket exists and RLS allows inserts.');
    } finally {
      setUploading(false);
    }
  };

  return (
    <View className="flex-1 bg-brand-light p-8">
      <View className="flex-row justify-between items-center mb-8">
        <View>
          <Text className="text-3xl font-bold text-brand-text mb-2">Site Photos</Text>
          <Text className="text-gray-500">Visual progress tracking across all active sites.</Text>
        </View>
        <Pressable 
          onPress={handlePickPhoto}
          className="flex-row items-center bg-brand-orange hover:bg-orange-600 transition-colors px-4 py-3 rounded-xl shadow-sm"
        >
          <Ionicons name="cloud-upload-outline" size={20} color="white" className="mr-2" />
          <Text className="text-white font-bold ml-2">Upload Photo</Text>
        </Pressable>
      </View>

      {/* Upload Modal */}
      <Modal visible={showUploadModal} transparent animationType="slide" onRequestClose={() => setShowUploadModal(false)}>
        <ModalViewport>
          <ScrollView keyboardShouldPersistTaps="handled" nestedScrollEnabled style={{ flexGrow: 0, flexShrink: 1 }} contentContainerStyle={{ padding: 0 }} className="bg-white w-full max-w-md rounded-3xl overflow-hidden shadow-2xl max-h-full">
            <View className="p-4 border-b border-gray-100 flex-row justify-between items-center bg-gray-50">
              <Text className="text-lg font-bold text-brand-text">Photo Details</Text>
              <Pressable onPress={() => !uploading && setShowUploadModal(false)}>
                <Ionicons name="close" size={24} color="#6B7280" />
              </Pressable>
            </View>
            
            <View className="p-6">
              {selectedImage && (
                <Image 
                  source={{ uri: selectedImage.uri }} 
                  className="w-full h-48 rounded-xl bg-gray-100 mb-6" 
                  resizeMode="cover"
                />
              )}

              <Text className="text-sm font-semibold text-gray-700 mb-2">Select Project</Text>
              <View className="border border-gray-200 rounded-xl mb-6 overflow-hidden max-h-32">
                <ScrollView nestedScrollEnabled>
                  {projects.map(p => (
                    <Pressable 
                      key={p.id}
                      onPress={() => setSelectedProjectId(p.id)}
                      className={`p-3 border-b border-gray-100 ${selectedProjectId === p.id ? 'bg-orange-50' : 'bg-white'}`}
                    >
                      <Text className={selectedProjectId === p.id ? 'text-brand-orange font-bold' : 'text-gray-600'}>
                        {p.name}
                      </Text>
                    </Pressable>
                  ))}
                  {projects.length === 0 && <Text className="p-4 text-gray-400">No active projects found.</Text>}
                </ScrollView>
              </View>

              <Text className="text-sm font-semibold text-gray-700 mb-2">Description</Text>
              <TextInput
                className="border border-gray-200 rounded-xl p-3 text-brand-text bg-gray-50 mb-6"
                placeholder="E.g. Foundation poured for Tower A"
                value={description}
                onChangeText={setDescription}
                multiline
                numberOfLines={2}
              />

              <Pressable 
                onPress={executeUpload}
                disabled={uploading || !selectedProjectId}
                className={`py-4 rounded-xl flex-row items-center justify-center ${uploading || !selectedProjectId ? 'bg-orange-300' : 'bg-brand-orange hover:bg-orange-600'}`}
              >
                {uploading ? (
                  <ActivityIndicator size="small" color="white" />
                ) : (
                  <Text className="text-white font-bold text-lg">Confirm Upload</Text>
                )}
              </Pressable>
            </View>
          </ScrollView>
        </ModalViewport>
      </Modal>

      {/* Grid */}
      {loading ? (
        <View className="flex-1 items-center justify-center">
          <ActivityIndicator size="large" color="#F97316" />
        </View>
      ) : (
        <ScrollView showsVerticalScrollIndicator={false}>
          {photos.length === 0 ? (
            <View className="bg-white p-10 rounded-2xl items-center justify-center border border-gray-100">
              <Ionicons name="images-outline" size={48} color="#9CA3AF" />
              <Text className="text-gray-500 mt-4 text-center">No photos have been uploaded yet.</Text>
            </View>
          ) : (
            <View className="flex-row flex-wrap justify-between">
              {photos.map(photo => (
                <View key={photo.id} style={{ width: isMobile ? '100%' : '48%', backgroundColor: '#fff', borderRadius: 16, overflow: 'hidden', marginBottom: 24, borderWidth: 1, borderColor: '#F3F4F6' }}>
                  <Image 
                    source={{ uri: photo.photo_url }} 
                    style={{ width: '100%', height: 200 }} 
                    resizeMode="cover" 
                  />
                  <View className="p-4">
                    <Text className="font-bold text-brand-text mb-1 truncate">{photo.projects?.name || 'Unknown Site'}</Text>
                    <Text className="text-gray-500 text-xs mb-3">{photo.description}</Text>
                    <View className="flex-row items-center justify-between">
                      <Text className="text-xs text-brand-orange font-semibold">{photo.uploader_name}</Text>
                      <Text className="text-xs text-gray-400">{new Date(photo.created_at).toLocaleDateString()}</Text>
                    </View>
                  </View>
                </View>
              ))}
            </View>
          )}
        </ScrollView>
      )}
    </View>
  );
}

