                          <TextInput 
                            placeholder="YYYY-MM-DD" 
                            className="bg-white border border-gray-300 rounded-lg p-3 text-sm"
                            value={ms.due_date}
                            onChangeText={(t) => updateMilestone(index, 'due_date', t)}
