              >
                {loading ? (
                  <ActivityIndicator color="white" />
                ) : (
                  <Text className="text-white font-bold text-base">Create Project</Text>
                )}
              </Pressable>
            </View>
          </ScrollView>

        </View>
      </ModalViewport>
    </Modal>
  );
};

import React, { useEffect, useState } from 'react';
import { View, Text, Pressable, ActivityIndicator } from 'react-native';
import { supabase } from '../../lib/supabase';
import { useRouter } from 'expo-router';

const AlertItem = ({ title, subtext, iconColor }: { title: string, subtext: string, iconColor: string }) => {
  return (
    <View className="flex-row items-start mb-4">
      {/* Icon Placeholder */}
      <View className={`w-8 h-8 rounded-full items-center justify-center mr-3 mt-0.5 ${iconColor.replace('text-', 'bg-').replace('-500', '-100')}`}>
         <View className={`w-3 h-3 rounded-sm ${iconColor.replace('text-', 'bg-')}`} />
      </View>
      
      {/* Content */}
      <View className="flex-1">
        <Text className="text-brand-text font-bold text-sm mb-0.5">{title}</Text>
        <Text className="text-gray-500 text-xs">{subtext}</Text>
      </View>
    </View>
  );
};

export const RecentAlertsPanel = ({ pmId }: { pmId?: string }) => {
  const [alerts, setAlerts] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const router = useRouter();

  useEffect(() => {
    let isMounted = true;
    
    let currentUserId: string | null = null;

    const setup = async () => {
      const { data: sessionData } = await supabase.auth.getSession();
      currentUserId = sessionData?.session?.user?.id || null;
      loadAlerts(sessionData);
    };

    const loadAlerts = async (sessionData: any) => {
      try {
        if (!sessionData?.session) {
          if (isMounted) setLoading(false);
          return;
        }

        let query = supabase
          .from('notifications')
          .select('*')
          .order('created_at', { ascending: false })
          .limit(4);
          
        if (pmId) {
          query = query.or(`target_user_id.eq.${pmId},target_role.eq.pm`);
        } else {
          // If no pmId, assume admin dashboard
          // Since we don't have role here natively, we hardcode super_admin aliases or just fetch it
          query = query.or(`target_user_id.eq.${currentUserId},and(target_user_id.is.null,or(target_role.eq.All,target_role.eq.super_admin))`);
        }

        const { data, error } = await query;

        if (error) throw error;
        
        if (isMounted) setAlerts(data || []);
      } catch (error) {
        console.warn('Failed to load alerts:', error);
      } finally {
        if (isMounted) setLoading(false);
      }
    };
    
    setup();

    // Supabase Realtime subscribe
    const channel = supabase
      .channel('dashboard_alerts')
      .on('postgres_changes', {
        event: 'INSERT',
        schema: 'public',
        table: 'notifications'
      }, (payload) => {
        if (isMounted) {
          const targetUser = payload.new.target_user_id;
          const targetRole = payload.new.target_role;
          
          const isForMe = pmId 
            ? (targetUser === pmId || targetRole === 'pm')
            : (targetUser === currentUserId || targetRole === 'super_admin');
            
          if (isForMe) {
            setAlerts(prev => [payload.new, ...prev].slice(0, 4));
          }
        }
      })
      .subscribe();
    
    return () => { 
      isMounted = false; 
      supabase.removeChannel(channel);
    };
  }, []);

  const getIconColor = (type: string) => {
    switch(type) {
      case 'Alert': return 'text-brand-orange';
      case 'Warning': return 'text-brand-danger'; // fallback if warning
      case 'Success': return 'text-brand-success';
      case 'Info':
      default: return 'text-blue-500';
    }
  };

  const getTimeAgo = (dateString: string) => {
    const date = new Date(dateString);
    const now = new Date();
    const diffInMinutes = Math.floor((now.getTime() - date.getTime()) / 60000);
    
    if (diffInMinutes < 60) return `${diffInMinutes} mins ago`;
    const diffInHours = Math.floor(diffInMinutes / 60);
    if (diffInHours < 24) return `${diffInHours} hr${diffInHours > 1 ? 's' : ''} ago`;
    return date.toLocaleDateString();
  };

  return (
    <View className="bg-white rounded-lg p-6 shadow-sm border border-gray-100 flex-1 min-h-[300px]">
      <View className="flex-row justify-between items-center mb-6">
        <Text className="text-lg font-bold text-brand-text">Recent Alerts</Text>
        {alerts.filter(a => a.is_unread).length > 0 && (
          <View className="bg-brand-orange px-2 py-1 rounded-full">
            <Text className="text-white text-[10px] font-bold">{alerts.filter(a => a.is_unread).length} new</Text>
          </View>
        )}
      </View>

      <View className="flex-1">
        {loading ? (
          <View className="flex-1 justify-center items-center">
            <ActivityIndicator color="#F97316" />
          </View>
        ) : alerts.length === 0 ? (
          <View className="flex-1 justify-center items-center">
            <Text className="text-gray-400">No new alerts.</Text>
          </View>
        ) : (
          alerts.map(a => (
            <AlertItem 
              key={a.id}
              title={a.title} 
              subtext={getTimeAgo(a.created_at)} 
              iconColor={getIconColor(a.type)} 
            />
          ))
        )}
      </View>

      <Pressable 
        className="mt-auto pt-4 border-t border-gray-50 items-center"
        onPress={() => router.push('/admin/notifications')}
      >
        <Text className="text-brand-orange text-sm font-semibold">View all notifications →</Text>
      </Pressable>
    </View>
  );
};

import React, { useEffect, useState } from 'react';
import { View, Text, Pressable, ActivityIndicator } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { supabase } from '../../lib/supabase';

/**
 * CostBreakdown
 *
 * Shows the most recent estimation from the `estimations` table,
 * along with per-prediction feature contributions returned by
 * /api/ai/predict-cost (stored on the estimation record) and
 * a real confidence score.
 *
 * Props:
 *   refreshTrigger  — increment to re-fetch after a new estimate is created
 *   featureContributions — optional array from the predict-cost response
 *   confidence       — optional 0-100 confidence from the predict-cost response
 */

type FeatureContrib = { name: string; value: number };

const SEGMENT_COLORS = [
  '#F97316', // brand-orange
  '#0F1117', // brand-dark
  '#EF4444', // brand-danger
  '#6B7280', // gray-500
  '#3B82F6', // blue
];

export const CostBreakdown = ({
  refreshTrigger = 0,
  featureContributions,
  confidence,
}: {
  refreshTrigger?: number;
  featureContributions?: FeatureContrib[];
  confidence?: number | null;
}) => {
  const [latestEstimate, setLatestEstimate] = useState<any>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let isMounted = true;
    const fetchLatest = async () => {
      try {
        const { data, error } = await supabase
          .from('estimations')
          .select('*')
          .order('created_at', { ascending: false })
          .limit(1);

        if (error) throw error;
        if (isMounted) setLatestEstimate(data?.[0] || null);
      } catch (err) {
        console.warn('Failed to load latest estimate', err);
      } finally {
        if (isMounted) setLoading(false);
      }
    };
    fetchLatest();
    return () => { isMounted = false; };
  }, [refreshTrigger]);

  const formatCurrency = (amount: number) => {
    if (!amount) return 'Rs. 0';
    if (amount >= 1_000_000) return `Rs. ${(amount / 1_000_000).toFixed(1)}M`;
    if (amount >= 1_000) return `Rs. ${(amount / 1_000).toFixed(1)}K`;
    return `Rs. ${amount}`;
  };

  const cost = latestEstimate?.estimated_cost || 0;
  // Prefer prop (freshest prediction) over stored value
  const confidenceVal = confidence ?? latestEstimate?.confidence_score ?? null;

  // Feature contributions: prefer live prop, fall back to parsed JSON from project_name if available
  let parsedContribs: FeatureContrib[] | null = null;
  let explanation = "Illustrative split — generate a new estimate to see model-specific contributions";
  
  try {
    if (latestEstimate?.project_name) {
      const parsed = JSON.parse(latestEstimate.project_name);
      if (parsed.contributions) {
        parsedContribs = parsed.contributions;
      }
    }
  } catch (e) {
    // Not valid JSON, keep as null
  }
  
  const contribs: FeatureContrib[] = featureContributions || parsedContribs || [];

  if (contribs.length > 0) {
    explanation = `${contribs[0]?.name} weighted highest due to project size and quality tier`;
  }

  if (loading) {
    return (
      <View className="bg-white rounded-lg p-6 shadow-sm border border-gray-100 flex-1 items-center justify-center min-h-[300px]">
        <ActivityIndicator color="#F97316" />
      </View>
    );
  }

  if (!latestEstimate) {
    return (
      <View className="bg-white rounded-lg p-6 shadow-sm border border-gray-100 flex-1 items-center justify-center min-h-[300px]">
        <Ionicons name="calculator-outline" size={40} color="#E5E7EB" />
        <Text className="text-gray-400 mt-3 text-sm text-center">
          No estimates generated yet.{'\n'}Use the AI Estimator to create one.
        </Text>
      </View>
    );
  }

  const confidenceLabel =
    confidenceVal == null
      ? 'Not validated'
      : confidenceVal >= 75
      ? 'High'
      : confidenceVal >= 50
      ? 'Medium'
      : 'Low';

  const confidenceBg =
    confidenceVal == null
      ? 'bg-gray-100'
      : confidenceVal >= 75
      ? 'bg-green-50'
      : confidenceVal >= 50
      ? 'bg-yellow-50'
      : 'bg-red-50';

  const confidenceText =
    confidenceVal == null
      ? 'text-gray-500'
      : confidenceVal >= 75
      ? 'text-brand-success'
      : confidenceVal >= 50
      ? 'text-yellow-700'
      : 'text-brand-danger';

  return (
    <View className="bg-white rounded-lg p-6 shadow-sm border border-gray-100 flex-1">
      {/* Header */}
      <View className="flex-row justify-between items-center mb-1">
        <Text className="text-lg font-bold text-brand-text">
          {contribs.length > 0 ? 'Feature Contributions' : 'Cost Breakdown'}
        </Text>
        <Pressable className="flex-row items-center border border-gray-200 px-3 py-1.5 rounded-full">
          <Ionicons name="time-outline" size={14} color="#6B7280" />
          <Text className="text-gray-600 text-xs font-semibold ml-1.5">Live Estimate</Text>
        </Pressable>
      </View>

      {contribs.length > 0 ? (
        <Text className="text-gray-400 text-xs mb-4">
          Which factors drove this specific prediction, ranked by contribution
        </Text>
      ) : (
        <Text className="text-gray-400 text-xs mb-4">
          Latest model estimate from saved history
        </Text>
      )}

      {/* Total Cost + Confidence */}
      <View className="flex-row items-center mb-6">
        <View className="flex-1">
          <Text className="text-gray-500 text-xs font-semibold uppercase mb-1">
            Estimated Total Cost
          </Text>
          <Text className="text-3xl font-bold text-brand-orange">
            {formatCurrency(cost)}
          </Text>
          <Text className="text-gray-400 text-[10px] mt-1">
            This is an estimate — confirm with a quantity surveyor.
          </Text>
        </View>

        <View className={`px-3 py-2 rounded-xl ${confidenceBg} ml-4 items-center`}>
          <Text className="text-gray-400 text-[10px] uppercase mb-0.5">Confidence</Text>
          <Text className={`font-bold text-sm ${confidenceText}`}>
            {confidenceVal != null ? `${Math.round(confidenceVal)}%` : '—'}
          </Text>
          <Text className={`text-[10px] font-semibold ${confidenceText}`}>
            {confidenceLabel}
          </Text>
        </View>
      </View>

      {/* Feature bar chart */}
      {contribs.length > 0 ? (
        <View className="border-t border-gray-100 pt-4">
          {contribs.slice(0, 5).map((feat, i) => (
            <View key={feat.name} className="mb-3">
              <View className="flex-row justify-between mb-1">
                <Text className="text-sm text-gray-700">{feat.name}</Text>
                <Text className="text-sm font-bold text-brand-text">{feat.value}%</Text>
              </View>
              <View className="w-full h-2 bg-gray-100 rounded-full overflow-hidden">
                <View
                  style={{
                    width: `${feat.value}%`,
                    height: '100%',
                    backgroundColor: SEGMENT_COLORS[i % SEGMENT_COLORS.length],
                    borderRadius: 4,
                  }}
                />
              </View>
            </View>
          ))}
          <Text className="text-gray-400 text-[10px] mt-2">
            Contribution percentages reflect this prediction&apos;s feature weights from the trained RandomForest.
          </Text>
        </View>
      ) : (
        /* Legacy static legend when no contribution data is available */
        <View className="flex-row flex-wrap justify-between pt-4 border-t border-gray-100">
          {[
            { label: 'Materials', pct: '42%', color: '#6B7280' },
            { label: 'Labour',    pct: '26%', color: '#0F1117' },
            { label: 'Equipment', pct: '16%', color: '#EF4444' },
            { label: 'Overhead',  pct: '16%', color: '#000' },
          ].map(item => (
            <View key={item.label} className="flex-row items-center w-[48%] mb-2">
              <View className="w-3 h-3 rounded-sm mr-2" style={{ backgroundColor: item.color }} />
              <Text className="text-xs text-gray-600 flex-1">{item.label}</Text>
              <Text className="text-xs font-bold text-brand-text">{item.pct}</Text>
            </View>
          ))}
          <Text className="text-gray-400 text-[10px] mt-2 w-full">
            Illustrative split — generate a new estimate to see model-specific contributions.
          </Text>
        </View>
      )}
    </View>
  );
};

import React, { useState } from 'react';
import { View, Text, TextInput, Pressable, ActivityIndicator, Alert } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { supabase } from '../../lib/supabase';
import { api } from '../../lib/api';
import { toast } from '../../lib/toast';
import { sendSystemNotification } from '../../utils/notifications';

export const QuotationForm = ({ onEstimateCreated = () => {} }: { onEstimateCreated?: () => void }) => {
  const [projectType, setProjectType] = useState('Residential');
  const [squareFootage, setSquareFootage] = useState('');
  const [numFloors, setNumFloors] = useState('');
  const [location, setLocation] = useState('Colombo');
  const [qualityTier, setQualityTier] = useState('Standard');
  const [siteCondition, setSiteCondition] = useState('Flat');
  const [structureType, setStructureType] = useState('RCC frame');
  const [flooringTier, setFlooringTier] = useState('Standard');
  const [sanitaryTier, setSanitaryTier] = useState('Standard');
  const [electricalTier, setElectricalTier] = useState('Standard');
  const [timeline, setTimeline] = useState('Standard');
  const [isGenerating, setIsGenerating] = useState(false);

  const cycleOption = (current: string, options: string[], setter: (v: string) => void) => {
    const idx = options.indexOf(current);
    setter(options[(idx + 1) % options.length]);
  };

  const handleGenerate = async () => {
    if (!squareFootage || !Number.isFinite(Number(squareFootage)) || Number(squareFootage) <= 0) {
      toast.error('Please enter a valid square footage.');
      return;
    }
    if (!numFloors || !Number.isInteger(Number(numFloors)) || Number(numFloors) <= 0) {
      toast.error('Please enter a valid number of floors.');
      return;
    }

    setIsGenerating(true);

    try {
      const { data: sessionData } = await supabase.auth.getSession();
      if (!sessionData?.session) throw new Error('Not logged in');

      // Call the real ML model
      const aiData = await api.post('/ai/predict-cost', {
        square_footage: Number(squareFootage),
        num_floors: Number(numFloors),
        location,
        project_type: projectType,
        quality_tier: qualityTier,
        site_condition: siteCondition,
        structure_type: structureType,
        finishing_flooring: flooringTier,
        finishing_sanitary: sanitaryTier,
        finishing_electrical: electricalTier,
        target_timeline: timeline
      });

      const estimatedCost = aiData.estimated_cost;
      const confidence = aiData.confidence_score;
      const contributions = aiData.feature_contributions;

      // Save estimation to DB using the generic CRUD route, storing context in project_name
      const projectNamePayload = JSON.stringify({
        title: `${projectType} in ${location}`,
        inputs: aiData.features_used,
        contributions: contributions
      });

      await api.post('/estimations', {
        project_name: projectNamePayload,
        estimated_cost: estimatedCost,
        status: 'Pending',
        confidence_score: confidence
      });

      toast.success(`AI Estimate Generated: Rs. ${(estimatedCost / 1000000).toFixed(2)}M\nConfidence: ${confidence == null ? 'Not validated' : `${confidence}%`}`);
      
      // Real-time Notification Dispatch
      await sendSystemNotification(
        'AI Estimate Generated',
        `A new ${projectType} project estimate for Rs. ${(estimatedCost / 1000000).toFixed(2)}M was generated and is pending review.`,
        'Admin'
      );

      setSquareFootage('');
      setNumFloors('');
      onEstimateCreated();
    } catch (error: any) {
      toast.error(error.message || 'Failed to generate estimate');
    } finally {
      setIsGenerating(false);
    }
  };
  return (
    <View className="bg-white rounded-lg p-6 shadow-sm border border-gray-100 mb-6">
      <View className="flex-row justify-between items-start mb-6">
        <View>
          <Text className="text-lg font-bold text-brand-text mb-1">Project Estimate Generator</Text>
          <Text className="text-brand-text-muted text-xs">Configure parameters for the AI model</Text>
        </View>
        <View className="flex-row items-center bg-orange-100 px-3 py-1.5 rounded-full">
          <Ionicons name="flash" size={14} color="#F97316" className="mr-1" />
          <Text className="text-brand-orange text-xs font-bold">AI Assisted</Text>
        </View>
      </View>

      <View className="flex-row flex-wrap -mx-3">
        <View className="w-full md:w-1/3 px-3 mb-4">
          <Text className="text-gray-500 text-xs font-semibold mb-2">Project Type</Text>
          <Pressable onPress={() => cycleOption(projectType, ['Residential House', 'Commercial Building', 'Apartment Complex', 'Warehouse', 'Road Construction', 'Renovation'], setProjectType)} className="border border-gray-200 rounded-lg bg-gray-50 px-4 py-3 flex-row justify-between items-center">
            <Text className="text-brand-text text-sm truncate flex-1">{projectType}</Text>
            <Ionicons name="swap-vertical" size={16} color="#9CA3AF" />
          </Pressable>
        </View>

        <View className="w-full md:w-1/3 px-3 mb-4">
          <Text className="text-gray-500 text-xs font-semibold mb-2">Location</Text>
          <Pressable onPress={() => cycleOption(location, ['Colombo', 'Gampaha', 'Kandy', 'Galle', 'Matara', 'Kurunegala', 'Ratnapura', 'Anuradhapura', 'Jaffna', 'Trincomalee'], setLocation)} className="border border-gray-200 rounded-lg bg-gray-50 px-4 py-3 flex-row justify-between items-center">
            <Text className="text-brand-text text-sm truncate flex-1">{location}</Text>
            <Ionicons name="swap-vertical" size={16} color="#9CA3AF" />
          </Pressable>
        </View>

        <View className="w-full md:w-1/3 px-3 mb-4">
          <Text className="text-gray-500 text-xs font-semibold mb-2">Square Footage (sq.ft)</Text>
          <View className="border border-gray-200 rounded-lg px-4 py-2.5">
            <TextInput placeholder="e.g. 2400" placeholderTextColor="#9CA3AF" className="text-brand-text text-sm" keyboardType="numeric" value={squareFootage} onChangeText={setSquareFootage} />
          </View>
        </View>

        <View className="w-full md:w-1/4 px-3 mb-4">
          <Text className="text-gray-500 text-xs font-semibold mb-2">Num Floors</Text>
          <View className="border border-gray-200 rounded-lg px-4 py-2.5">
            <TextInput placeholder="e.g. 2" placeholderTextColor="#9CA3AF" className="text-brand-text text-sm" keyboardType="numeric" value={numFloors} onChangeText={setNumFloors} />
          </View>
        </View>

        <View className="w-full md:w-1/4 px-3 mb-4">
          <Text className="text-gray-500 text-xs font-semibold mb-2">Site Condition</Text>
          <Pressable onPress={() => cycleOption(siteCondition, ['Flat', 'Sloped', 'Requires Excavation/Piling'], setSiteCondition)} className="border border-gray-200 rounded-lg bg-gray-50 px-4 py-3 flex-row justify-between items-center">
            <Text className="text-brand-text text-xs truncate flex-1">{siteCondition}</Text>
            <Ionicons name="swap-vertical" size={16} color="#9CA3AF" />
          </Pressable>
        </View>

        <View className="w-full md:w-1/4 px-3 mb-4">
          <Text className="text-gray-500 text-xs font-semibold mb-2">Structure Type</Text>
          <Pressable onPress={() => cycleOption(structureType, ['RCC frame', 'Load-bearing', 'Steel'], setStructureType)} className="border border-gray-200 rounded-lg bg-gray-50 px-4 py-3 flex-row justify-between items-center">
            <Text className="text-brand-text text-xs truncate flex-1">{structureType}</Text>
            <Ionicons name="swap-vertical" size={16} color="#9CA3AF" />
          </Pressable>
        </View>

        <View className="w-full md:w-1/4 px-3 mb-4">
          <Text className="text-gray-500 text-xs font-semibold mb-2">Target Timeline</Text>
          <Pressable onPress={() => cycleOption(timeline, ['Standard', 'Rushed'], setTimeline)} className="border border-gray-200 rounded-lg bg-gray-50 px-4 py-3 flex-row justify-between items-center">
            <Text className="text-brand-text text-xs truncate flex-1">{timeline}</Text>
            <Ionicons name="swap-vertical" size={16} color="#9CA3AF" />
          </Pressable>
        </View>

        {/* Finishes section */}
        <View className="w-full mt-2 mb-2 px-3">
          <Text className="text-gray-700 font-bold text-sm">Finishing Quality Levels</Text>
          <View className="h-[1px] bg-gray-100 my-2" />
        </View>

        <View className="w-full md:w-1/4 px-3 mb-4">
          <Text className="text-gray-500 text-xs font-semibold mb-2">Overall Quality</Text>
          <Pressable onPress={() => cycleOption(qualityTier, ['Standard', 'Premium', 'Luxury'], setQualityTier)} className="border border-gray-200 rounded-lg bg-gray-50 px-4 py-3 flex-row justify-between items-center">
            <Text className="text-brand-text text-xs truncate flex-1">{qualityTier}</Text>
            <Ionicons name="swap-vertical" size={16} color="#9CA3AF" />
          </Pressable>
        </View>
        <View className="w-full md:w-1/4 px-3 mb-4">
          <Text className="text-gray-500 text-xs font-semibold mb-2">Flooring</Text>
          <Pressable onPress={() => cycleOption(flooringTier, ['Standard', 'Premium', 'Luxury'], setFlooringTier)} className="border border-gray-200 rounded-lg bg-gray-50 px-4 py-3 flex-row justify-between items-center">
            <Text className="text-brand-text text-xs truncate flex-1">{flooringTier}</Text>
            <Ionicons name="swap-vertical" size={16} color="#9CA3AF" />
          </Pressable>
        </View>
        <View className="w-full md:w-1/4 px-3 mb-4">
          <Text className="text-gray-500 text-xs font-semibold mb-2">Sanitaryware</Text>
          <Pressable onPress={() => cycleOption(sanitaryTier, ['Standard', 'Premium', 'Luxury'], setSanitaryTier)} className="border border-gray-200 rounded-lg bg-gray-50 px-4 py-3 flex-row justify-between items-center">
            <Text className="text-brand-text text-xs truncate flex-1">{sanitaryTier}</Text>
            <Ionicons name="swap-vertical" size={16} color="#9CA3AF" />
          </Pressable>
        </View>
        <View className="w-full md:w-1/4 px-3 mb-4">
          <Text className="text-gray-500 text-xs font-semibold mb-2">Electrical</Text>
          <Pressable onPress={() => cycleOption(electricalTier, ['Standard', 'Premium', 'Luxury'], setElectricalTier)} className="border border-gray-200 rounded-lg bg-gray-50 px-4 py-3 flex-row justify-between items-center">
            <Text className="text-brand-text text-xs truncate flex-1">{electricalTier}</Text>
            <Ionicons name="swap-vertical" size={16} color="#9CA3AF" />
          </Pressable>
        </View>
      </View>

      <View className="flex-row justify-end mt-2">
        <Pressable 
          onPress={handleGenerate}
          disabled={isGenerating}
          className={`px-6 py-3 rounded-lg flex-row items-center ${isGenerating ? 'bg-gray-400' : 'bg-brand-orange'}`}
        >
          {isGenerating ? (
            <ActivityIndicator size="small" color="#ffffff" className="mr-2" />
          ) : (
            <Ionicons name="settings-sharp" size={16} color="#ffffff" className="mr-2" />
          )}
          <Text className="text-white font-semibold text-sm">
            {isGenerating ? 'Generating...' : 'Generate Estimate'}
          </Text>
        </Pressable>
      </View>
    </View>
  );
};

import React, { useEffect, useState } from 'react';
import { View, Text, Pressable, ActivityIndicator, ScrollView } from 'react-native';
import { supabase } from '../../lib/supabase';
import { sendSystemNotification } from '../../utils/notifications';

const EstimateRow = ({ 
  id,
  projectName, 
  date, 
  cost, 
  status,
  onApprove,
  onReject
}: { 
  id: string,
  projectName: string, 
  date: string, 
  cost: string, 
  status: 'Approved' | 'Draft' | 'Pending' | 'Rejected',
  onApprove: (id: string) => void,
  onReject: (id: string) => void
}) => {
  let statusBadgeColor = '';
  let statusTextColor = '';

  let title = projectName;
  let inputs: any = null;
  try {
    const parsed = JSON.parse(projectName);
    if (parsed.title) {
      title = parsed.title;
      inputs = parsed.inputs;
    }
  } catch (e) {
    // legacy format, keep as is
  }

  switch (status) {
    case 'Approved':
      statusBadgeColor = 'bg-[#DCFCE7]';
      statusTextColor = 'text-brand-success';
      break;
    case 'Rejected':
      statusBadgeColor = 'bg-red-100';
      statusTextColor = 'text-red-700';
      break;
    case 'Draft':
      statusBadgeColor = 'bg-gray-100';
      statusTextColor = 'text-gray-600';
      break;
    case 'Pending':
      statusBadgeColor = 'bg-orange-100';
      statusTextColor = 'text-brand-orange';
      break;
  }

  return (
    <View className="flex-col py-4 border-b border-gray-50">
      <View className="flex-row items-center w-full">
        <View className="w-1/4">
          <Text className="text-brand-text font-bold text-sm">{title}</Text>
        </View>
        <View className="w-1/4">
          <Text className="text-gray-500 text-xs">{date}</Text>
        </View>
        <View className="w-1/5">
          <Text className="text-brand-text font-bold text-sm">{cost}</Text>
        </View>
        <View className="w-1/5">
          <View className={`px-2 py-1 rounded self-start ${statusBadgeColor}`}>
            <Text className={`text-[10px] font-bold uppercase ${statusTextColor}`}>{status}</Text>
          </View>
        </View>
        <View className="flex-1 items-end flex-row justify-end gap-2">
          {status === 'Pending' && (
            <>
              <Pressable onPress={() => onApprove(id)} className="bg-brand-success px-2 py-1 rounded">
                <Text className="text-white text-xs font-semibold">Approve</Text>
              </Pressable>
              <Pressable onPress={() => onReject(id)} className="bg-red-500 px-2 py-1 rounded">
                <Text className="text-white text-xs font-semibold">Reject</Text>
              </Pressable>
            </>
          )}
          <Pressable onPress={async () => {
            try {
              const { data: sessionData } = await supabase.auth.getSession();
              const token = sessionData?.session?.access_token;
              if (!token) {
                alert('Please log in to view PDF');
                return;
              }
              const response = await fetch(`http://localhost:8000/api/documents/estimation/${id}/pdf`, {
                headers: {
                  'Authorization': `Bearer ${token}`
                }
              });
              if (!response.ok) {
                alert('Failed to generate PDF');
                return;
              }
              const blob = await response.blob();
              const url = window.URL.createObjectURL(blob);
              const a = document.createElement('a');
              a.href = url;
              a.download = `Estimate_${id.substring(0, 8)}.pdf`;
              document.body.appendChild(a);
              a.click();
              a.remove();
              window.URL.revokeObjectURL(url);
            } catch (err) {
              console.error(err);
              alert('An error occurred while generating the PDF.');
            }
          }}>
            <Text className="text-brand-orange text-xs font-semibold pl-2">View PDF</Text>
          </Pressable>
        </View>
      </View>
      {inputs && (
        <View className="flex-row mt-2 items-center">
          <Text className="text-[10px] text-gray-400 font-medium">Context: </Text>
          <Text className="text-[10px] text-gray-500">
            {inputs.sq_ft} sq.ft • {inputs.floors} floors • {inputs.site} • {inputs.timeline} Schedule
          </Text>
        </View>
      )}
    </View>
  );
};

export const RecentEstimates = ({ refreshTrigger = 0 }: { refreshTrigger?: number }) => {
  const [estimations, setEstimations] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let isMounted = true;
    
    const loadEstimates = async () => {
      try {
        const { data: sessionData } = await supabase.auth.getSession();
        if (!sessionData?.session) {
          if (isMounted) setLoading(false);
          return;
        }

        const { data, error } = await supabase
          .from('estimations')
          .select('*')
          .order('created_at', { ascending: false })
          .limit(10);

        if (error) throw error;
        
        if (isMounted) setEstimations(data || []);
      } catch (error) {
        console.warn('Failed to load estimates:', error);
      } finally {
        if (isMounted) setLoading(false);
      }
    };
    
    loadEstimates();
    
    return () => { isMounted = false; };
  }, [refreshTrigger]);

  const handleApprove = async (id: string) => {
    try {
      setLoading(true);
      
      // Get the estimation
      const estToApprove = estimations.find(e => e.id === id);
      if (!estToApprove) return;

      const { error } = await supabase.from('estimations').update({ status: 'Approved' }).eq('id', id);
      if (error) throw error;
      
      // Update UI
      setEstimations(prev => prev.map(e => e.id === id ? { ...e, status: 'Approved' } : e));
      
      // Now automatically create a project budget record based on this estimation!
      let title = estToApprove.project_name;
      try {
        title = JSON.parse(estToApprove.project_name).title || title;
      } catch(e) {}
      
      const { data: projData, error: projError } = await supabase.from('projects').insert({
        name: title,
        total_budget: estToApprove.estimated_cost,
        status: 'active',
        start_date: new Date().toISOString().split('T')[0]
      });
      if (projError) console.warn('Failed to seed project from estimation', projError);
      
      // Real-time Notification Dispatch
      await sendSystemNotification(
        'Estimate Approved',
        `The estimate for ${title} was approved and a project baseline was created.`,
        'Admin'
      );
      
    } catch (err) {
      console.warn('Failed to approve', err);
    } finally {
      setLoading(false);
    }
  };

  const handleReject = async (id: string) => {
    try {
      setLoading(true);
      const { error } = await supabase.from('estimations').update({ status: 'Rejected' }).eq('id', id);
      if (error) throw error;
      setEstimations(prev => prev.map(e => e.id === id ? { ...e, status: 'Rejected' } : e));
      
      const estToReject = estimations.find(e => e.id === id);
      if (estToReject) {
        let title = estToReject.project_name;
        try { title = JSON.parse(estToReject.project_name).title || title; } catch(e) {}
        await sendSystemNotification(
          'Estimate Rejected',
          `The estimate for ${title} was rejected.`,
          'Admin'
        );
      }
    } catch (err) {
      console.warn('Failed to reject', err);
    } finally {
      setLoading(false);
    }
  };

  const formatCurrency = (amount: number) => {
    if (!amount) return 'Rs. 0';
    if (amount >= 1000000) return `Rs. ${(amount / 1000000).toFixed(1)}M`;
    if (amount >= 1000) return `Rs. ${(amount / 1000).toFixed(1)}K`;
    return `Rs. ${amount}`;
  };

  return (
    <View className="bg-white rounded-lg p-6 shadow-sm border border-gray-100 flex-1 ml-6 min-h-[300px]">
      <View className="flex-row justify-between items-center mb-4">
        <Text className="text-lg font-bold text-brand-text">Recent Estimates</Text>
        <Pressable>
          <Text className="text-brand-orange text-sm font-semibold">View all {'>'}</Text>
        </Pressable>
      </View>

      <View className="flex-row py-2 border-b border-gray-100 mb-2">
        <Text className="w-1/4 text-xs font-semibold text-gray-400 uppercase">Project Name</Text>
        <Text className="w-1/4 text-xs font-semibold text-gray-400 uppercase">Date</Text>
        <Text className="w-1/5 text-xs font-semibold text-gray-400 uppercase">Estimated Cost</Text>
        <Text className="w-1/5 text-xs font-semibold text-gray-400 uppercase">Status</Text>
        <Text className="flex-1 text-xs font-semibold text-gray-400 uppercase text-right"></Text>
      </View>

      <ScrollView showsVerticalScrollIndicator={false}>
        {loading ? (
          <View className="py-10 items-center">
            <ActivityIndicator color="#F97316" />
          </View>
        ) : estimations.length === 0 ? (
          <View className="py-10 items-center">
            <Text className="text-gray-400">No estimations generated yet.</Text>
          </View>
        ) : (
          estimations.map((est) => (
            <EstimateRow 
              key={est.id}
              id={est.id}
              projectName={est.project_name || `Estimation #${est.id.toString().substring(0, 4)}`} 
              date={new Date(est.created_at).toLocaleDateString()} 
              cost={formatCurrency(est.estimated_cost)} 
              status={est.status || 'Pending'} 
              onApprove={handleApprove}
              onReject={handleReject}
            />
          ))
        )}
      </ScrollView>
    </View>
  );
};

import React, { useEffect, useState } from 'react';
import { View, Text, ScrollView, ActivityIndicator } from 'react-native';
import { supabase } from '../../lib/supabase';
import { useResponsive } from '../../hooks/useResponsive';
import { Ionicons } from '@expo/vector-icons';

const AttendanceRow = ({ 
  name, 
  role, 
  project, 
  checkIn, 
  hours, 
  status 
}: { 
  name: string, 
  role: string, 
  project: string, 
  checkIn: string, 
  hours: string | number, 
  status: 'Present' | 'Absent' | 'On Leave' 
}) => {
  const { isMobile } = useResponsive();

  if (isMobile) {
    const getMobileStatusColor = () => {
      if (status === 'Present') return { bg: '#D1FAE5', text: '#065F46' };
      if (status === 'Absent') return { bg: '#FEE2E2', text: '#991B1B' };
      return { bg: '#FEF9C3', text: '#A16207' };
    };
    const mobileStatus = getMobileStatusColor();
    const initials = name.split(' ').map(n => n[0]).join('').substring(0, 2).toUpperCase() || '?';

    return (
      <View style={{ backgroundColor: '#fff', borderRadius: 12, borderWidth: 0.5, borderColor: '#E5E7EB', padding: 12, marginBottom: 12 }}>
        <View style={{ flexDirection: 'row', alignItems: 'center', gap: 12, marginBottom: 12 }}>
          <View style={{ width: 40, height: 40, borderRadius: 20, backgroundColor: '#EFF6FF', justifyContent: 'center', alignItems: 'center' }}>
            <Text style={{ color: '#1D4ED8', fontWeight: 'bold', fontSize: 16 }}>{initials}</Text>
          </View>
          <View style={{ flex: 1 }}>
            <Text style={{ fontSize: 15, fontWeight: '700', color: '#111827' }} numberOfLines={1} ellipsizeMode="tail">
              {name}
            </Text>
            <Text style={{ fontSize: 12, color: '#6B7280' }} numberOfLines={1} ellipsizeMode="tail">
              {role}
            </Text>
          </View>
          <View style={{ backgroundColor: mobileStatus.bg, paddingHorizontal: 8, paddingVertical: 4, borderRadius: 12 }}>
            <Text style={{ color: mobileStatus.text, fontSize: 10, fontWeight: 'bold', textTransform: 'uppercase' }}>
              {status}
            </Text>
          </View>
        </View>

        <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center' }}>
          <View style={{ flexDirection: 'row', alignItems: 'center', gap: 4 }}>
            <Ionicons name="location-outline" size={14} color="#6B7280" />
            <Text style={{ fontSize: 13, color: '#6B7280' }}>{project}</Text>
          </View>
          <View style={{ flexDirection: 'row', alignItems: 'center', gap: 12 }}>
            <View style={{ flexDirection: 'row', alignItems: 'center', gap: 4 }}>
              <Ionicons name="log-in-outline" size={14} color="#6B7280" />
              <Text style={{ fontSize: 13, color: '#6B7280' }}>{checkIn}</Text>
            </View>
            <View style={{ flexDirection: 'row', alignItems: 'center', gap: 4 }}>
              <Ionicons name="time-outline" size={14} color="#6B7280" />
              <Text style={{ fontSize: 13, color: '#6B7280' }}>{hours}h</Text>
            </View>
          </View>
        </View>
      </View>
    );
  }
  
  let statusBadgeColor = '';
  let statusTextColor = '';

  switch (status) {
    case 'Present':
      statusBadgeColor = 'bg-[#DCFCE7]';
      statusTextColor = 'text-brand-success';
      break;
    case 'Absent':
      statusBadgeColor = 'bg-[#FEE2E2]';
      statusTextColor = 'text-brand-danger';
      break;
    case 'On Leave':
      statusBadgeColor = 'bg-[#FEF9C3]'; // yellow-100
      statusTextColor = 'text-[#A16207]'; // yellow-700
      break;
  }
  
  return (
    <View className="flex-row items-center py-4 border-b border-gray-100">
      {/* Worker Name & Role */}
      <View className="w-1/4">
        <Text className="text-brand-text font-semibold text-sm">{name}</Text>
        <Text className="text-gray-500 text-xs">{role}</Text>
      </View>

      {/* Project/Site */}
      <View className="w-1/4">
        <Text className="text-brand-text text-sm">{project}</Text>
      </View>

      {/* Check-in Time */}
      <View className="w-1/6">
        <Text className="text-gray-600 text-sm">{checkIn}</Text>
      </View>

      {/* Hours Worked */}
      <View className="w-1/6">
        <Text className="text-brand-text text-sm font-medium">{hours}</Text>
      </View>

      {/* Status Badge */}
      <View className="flex-1 flex-row justify-end">
        <View className={`${statusBadgeColor} px-2 py-1 rounded`}>
          <Text className={`${statusTextColor} text-xs font-semibold`}>{status}</Text>
        </View>
      </View>
    </View>
  );
};

export const AttendanceTable = ({ refreshTrigger = 0, searchQuery = '', pmId }: { refreshTrigger?: number, searchQuery?: string, pmId?: string }) => {
  const { isMobile } = useResponsive();
  const [labour, setLabour] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let isMounted = true;
    
    const loadLabour = async () => {
      try {
        const { data: sessionData } = await supabase.auth.getSession();
        if (!sessionData?.session) {
          if (isMounted) setLoading(false);
          return;
        }

        const today = new Date().toISOString().split('T')[0];

        // Fetch attendance for today from labour table
        let query = supabase
          .from('legacy_labour')
          .select(`
            id, check_in_time, hours_worked, status, worker_name, role,
            project:projects!inner(name, pm_id)
          `)
          .eq('date', today)
          .order('check_in_time', { ascending: false });

        if (pmId) {
          query = query.eq('project.pm_id', pmId);
        }

        const { data, error } = await query;
        if (error) throw error;
        
        if (isMounted) setLabour(data || []);
      } catch (error) {
        console.warn('Failed to load attendance:', error);
      } finally {
        if (isMounted) setLoading(false);
      }
    };
    
    loadLabour();
    
    return () => { isMounted = false; };
  }, [refreshTrigger, pmId]);

  const filteredLabour = labour.filter(item => {
    if (!searchQuery) return true;
    const s = searchQuery.toLowerCase();
    const workerName = item.worker_name?.toLowerCase() || '';
    const projectName = item.project?.name?.toLowerCase() || '';
    return workerName.includes(s) || projectName.includes(s);
  });
  const formatTime = (isoString: string) => {
    if (!isoString) return '—';
    const date = new Date(isoString);
    return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  };

  return (
    <View className="bg-white rounded-lg p-6 shadow-sm border border-gray-100 flex-1 min-h-[400px]">
      <View className="mb-6">
        <Text className="text-lg font-bold text-brand-text mb-1">Worker Attendance</Text>
        <Text className="text-brand-text-muted text-xs">Daily check-in status across sites</Text>
      </View>

      {/* Table Header */}
      {!isMobile && (
        <View className="flex-row py-3 border-b border-gray-200">
          <Text className="w-1/4 text-xs font-semibold text-gray-500 uppercase">Worker</Text>
          <Text className="w-1/4 text-xs font-semibold text-gray-500 uppercase">Project / Site</Text>
          <Text className="w-1/6 text-xs font-semibold text-gray-500 uppercase">Check-in</Text>
          <Text className="w-1/6 text-xs font-semibold text-gray-500 uppercase">Hours</Text>
          <Text className="w-1/6 text-xs font-semibold text-gray-500 uppercase text-right pr-2">Status</Text>
        </View>
      )}

      {loading ? (
        <View className="flex-1 items-center justify-center py-10">
          <ActivityIndicator size="large" color="#3B82F6" />
        </View>
      ) : (
        <ScrollView showsVerticalScrollIndicator={false}>
          {filteredLabour.length === 0 ? (
            <View className="py-10 items-center">
              <Text className="text-gray-400">No workers found.</Text>
            </View>
          ) : (
            filteredLabour.map(l => {
              const pName = l.project?.name || 'Unknown Site';
              
              // Format check-in time
              let checkInFormatted = '--:--';
              if (l.check_in_time) {
                const dt = new Date(l.check_in_time);
                const hh = String(dt.getHours()).padStart(2, '0');
                const mm = String(dt.getMinutes()).padStart(2, '0');
                checkInFormatted = `${hh}:${mm}`;
              } else if (l.status === 'Absent' || l.status === 'On Leave') {
                checkInFormatted = l.status;
              }

              return (
                <AttendanceRow 
                  key={l.id}
                  name={l.worker_name || 'Unknown'} 
                  role={l.role || 'Worker'} 
                  project={pName} 
                  checkIn={checkInFormatted} 
                  hours={l.hours_worked || 0} 
                  status={l.status as any} 
                />
              );
            })
          )}
        </ScrollView>
      )}
    </View>
  );
};

import { ModalViewport } from '../common/ModalViewport';
import React, { useState, useEffect } from 'react';
import { View, Text, TextInput, Pressable, ActivityIndicator, Modal, ScrollView, Platform } from 'react-native';
import { supabase } from '../../lib/supabase';
import { api } from '../../lib/api';
import { Ionicons } from '@expo/vector-icons';
import { toast } from '../../lib/toast';

type CheckInWorkerModalProps = {
  visible: boolean;
  onClose: () => void;
  onSuccess: () => void;
};

export const CheckInWorkerModal = ({ visible, onClose, onSuccess }: CheckInWorkerModalProps) => {
  const [workerId, setWorkerId] = useState<string | null>(null);
  const [projectId, setProjectId] = useState<string | null>(null);
  const [status, setStatus] = useState<'Present' | 'On Leave' | 'Absent'>('Present');
  const [checkInTime, setCheckInTime] = useState('');
  const [hoursWorked, setHoursWorked] = useState('8');
  const [overtime, setOvertime] = useState('0');
  
  const [workers, setWorkers] = useState<any[]>([]);
  const [projects, setProjects] = useState<any[]>([]);
  
  const [loading, setLoading] = useState(false);
  const [fetchingData, setFetchingData] = useState(true);
  const [errorMsg, setErrorMsg] = useState('');

  // Fetch active projects and workers
  useEffect(() => {
    if (!visible) return;

    let isMounted = true;
    const fetchData = async () => {
      setFetchingData(true);
      try {
        const [projectsReq, workersReq] = await Promise.all([
          supabase.from('projects').select('id, name').eq('status', 'Active'),
          supabase.from('profiles').select('id, full_name').eq('role', 'worker')
        ]);
        
        if (projectsReq.error) throw projectsReq.error;
        if (workersReq.error) throw workersReq.error;
        
        if (isMounted) {
          setProjects(projectsReq.data || []);
          setWorkers(workersReq.data || []);
          
          // Auto-set time to now in HH:mm format
          const now = new Date();
          const hh = String(now.getHours()).padStart(2, '0');
          const mm = String(now.getMinutes()).padStart(2, '0');
          setCheckInTime(`${hh}:${mm}`);
        }
      } catch (err) {
        console.warn('Could not load lookup data for check-in modal', err);
      } finally {
        if (isMounted) setFetchingData(false);
      }
    };
    fetchData();
    return () => { isMounted = false; };
  }, [visible]);

  const handleCreate = async () => {
    if (!workerId || !projectId || !status) {
      setErrorMsg('Please select a worker, project, and status.');
      return;
    }
    if (status === 'Present' && !checkInTime) {
      setErrorMsg('Check in time is required when Present.');
      return;
    }

    setLoading(true);
    setErrorMsg('');

    try {
      const selectedWorker = workers.find(w => w.id === workerId);
      const workerName = selectedWorker ? selectedWorker.full_name : 'Unknown Worker';
      
      const now = new Date();
      // Format checkInTime to a full timestamp if they are present
      let checkInTimestamp = null;
      if (status === 'Present' && checkInTime) {
        const [hh, mm] = checkInTime.split(':');
        const dt = new Date();
        dt.setHours(Number(hh), Number(mm), 0, 0);
        checkInTimestamp = dt.toISOString();
      }

      const totalHours = status === 'Present' ? Number(hoursWorked) + Number(overtime) : 0;

      const { data: sessionData } = await supabase.auth.getSession();
      const token = sessionData?.session?.access_token;
      
      const response = await fetch(`${process.env.EXPO_PUBLIC_API_URL}/labour`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({
          project_id: projectId,
          worker_name: workerName,
          role: 'Labourer',
          hours_worked: totalHours,
          status: status
        })
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.detail || 'Failed to record attendance');
      }

      // Reset form
      setWorkerId(null);
      setProjectId(null);
      setStatus('Present');
      setHoursWorked('8');
      setOvertime('0');
      
      toast.success('Attendance recorded!');
      onSuccess();
    } catch (e: any) {
      setErrorMsg(e.message || 'Failed to record attendance');
    } finally {
      setLoading(false);
    }
  };

  return (
    <Modal visible={visible} transparent animationType="fade" onRequestClose={onClose}>
      <ModalViewport>
        <View className="bg-white max-h-full w-full max-w-lg rounded-2xl shadow-xl overflow-hidden">
          
          {/* Header */}
          <View className="flex-row justify-between items-center p-6 border-b border-gray-100 bg-brand-light">
            <Text className="text-xl font-bold text-brand-text">Check In Worker</Text>
            <Pressable onPress={onClose} className="p-2 rounded-full hover:bg-gray-200 transition-colors">
              <Ionicons name="close" size={24} color="#6B7280" />
            </Pressable>
          </View>

          <ScrollView keyboardShouldPersistTaps="handled" contentContainerStyle={{ padding: 24 }} style={{ flexShrink: 1 }}>
            {errorMsg ? (
              <View className="bg-red-50 p-3 rounded-lg border border-red-200 mb-6">
                <Text className="text-red-600 text-sm text-center">{errorMsg}</Text>
              </View>
            ) : null}

            {fetchingData ? (
              <View className="py-10 items-center justify-center">
                <ActivityIndicator color="#F97316" />
              </View>
            ) : (
              <>
                <View className="mb-4">
                  <Text className="text-sm font-semibold text-gray-700 mb-2">Select Worker</Text>
                  <ScrollView horizontal showsHorizontalScrollIndicator={false} className="flex-row gap-2">
                    {workers.map(w => (
                      <Pressable
                        key={w.id}
                        onPress={() => setWorkerId(w.id)}
                        className={`px-4 py-2 rounded-full border ${workerId === w.id ? 'bg-brand-orange border-brand-orange' : 'bg-gray-50 border-gray-200'}`}
                      >
                        <Text className={`text-sm font-semibold ${workerId === w.id ? 'text-white' : 'text-gray-600'}`}>
                          {w.full_name}
                        </Text>
                      </Pressable>
                    ))}
                    {workers.length === 0 && (
                       <Text className="text-gray-400 text-sm italic">No active workers found.</Text>
                    )}
                  </ScrollView>
                </View>

                <View className="mb-4">
                  <Text className="text-sm font-semibold text-gray-700 mb-2">Assign to Project</Text>
                  <ScrollView horizontal showsHorizontalScrollIndicator={false} className="flex-row gap-2">
                    {projects.map(p => (
                      <Pressable
                        key={p.id}
                        onPress={() => setProjectId(p.id)}
                        className={`px-4 py-2 rounded-full border ${projectId === p.id ? 'bg-brand-orange border-brand-orange' : 'bg-gray-50 border-gray-200'}`}
                      >
                        <Text className={`text-sm font-semibold ${projectId === p.id ? 'text-white' : 'text-gray-600'}`}>
                          {p.name}
                        </Text>
                      </Pressable>
                    ))}
                    {projects.length === 0 && (
                       <Text className="text-gray-400 text-sm italic">No active projects found.</Text>
                    )}
                  </ScrollView>
                </View>

                <View className="mb-4">
                  <Text className="text-sm font-semibold text-gray-700 mb-2">Status</Text>
                  <View className="flex-row gap-2">
                    {['Present', 'On Leave', 'Absent'].map(s => (
                      <Pressable
                        key={s}
                        onPress={() => setStatus(s as any)}
                        className={`flex-1 py-3 rounded-xl border items-center justify-center ${status === s ? 'bg-brand-dark border-brand-dark' : 'bg-gray-50 border-gray-200'}`}
                      >
                        <Text className={`text-sm font-semibold ${status === s ? 'text-white' : 'text-gray-600'}`}>
                          {s}
                        </Text>
                      </Pressable>
                    ))}
                  </View>
                </View>

                {status === 'Present' && (
                  <>
                    <View className="mb-4">
                      <Text className="text-sm font-semibold text-gray-700 mb-2">Check In Time</Text>
                      {Platform.OS === 'web' ? (
                        // @ts-ignore
                        <input 
                          type="time"
                          className="w-full border border-gray-300 rounded-xl p-4 text-brand-text bg-gray-50 focus:border-brand-orange focus:bg-white transition-colors outline-none"
                          value={checkInTime}
                          onChange={(e) => setCheckInTime(e.target.value)}
                        />
                      ) : (
                        <TextInput
                          className="w-full border border-gray-300 rounded-xl p-4 text-brand-text bg-gray-50 focus:border-brand-orange focus:bg-white transition-colors"
                          placeholder="HH:mm"
                          value={checkInTime}
                          onChangeText={setCheckInTime}
                        />
                      )}
                    </View>

                    <View className="flex-row gap-4 mb-4">
                      <View className="flex-1">
                        <Text className="text-sm font-semibold text-gray-700 mb-2">Hours Worked</Text>
                        <TextInput
                          className="w-full border border-gray-300 rounded-xl p-4 text-brand-text bg-gray-50 focus:border-brand-orange focus:bg-white transition-colors"
                          placeholder="8"
                          keyboardType="numeric"
                          value={hoursWorked}
                          onChangeText={setHoursWorked}
                        />
                      </View>
                      <View className="flex-1">
                        <Text className="text-sm font-semibold text-gray-700 mb-2">Overtime (hrs)</Text>
                        <TextInput
                          className="w-full border border-gray-300 rounded-xl p-4 text-brand-text bg-gray-50 focus:border-brand-orange focus:bg-white transition-colors"
                          placeholder="0"
                          keyboardType="numeric"
                          value={overtime}
                          onChangeText={setOvertime}
                        />
                      </View>
                    </View>
                  </>
                )}
              </>
            )}

            {/* Footer Buttons */}
            <View className="flex-row gap-4 pt-4 border-t border-gray-100 pb-2">
              <Pressable 
                onPress={onClose}
                disabled={loading}
                className="flex-1 bg-gray-100 py-4 rounded-xl items-center justify-center hover:bg-gray-200 transition-colors"
              >
                <Text className="text-gray-600 font-bold text-base">Cancel</Text>
              </Pressable>
              <Pressable 
                onPress={handleCreate}
                disabled={loading || fetchingData}
                className={`flex-1 bg-brand-orange py-4 rounded-xl items-center justify-center shadow-sm hover:bg-orange-600 transition-colors ${loading || fetchingData ? 'opacity-70' : ''}`}
              >
                {loading ? (
                  <ActivityIndicator color="white" />
                ) : (
                  <Text className="text-white font-bold text-base">Check In</Text>
                )}
              </Pressable>
            </View>
          </ScrollView>

        </View>
      </ModalViewport>
    </Modal>
  );
};

import React, { useEffect, useState } from 'react';
import { View, Text, ActivityIndicator } from 'react-native';
import { supabase } from '../../lib/supabase';

const Bar = ({ label, percentage, count }: { label: string, percentage: number, count: number }) => (
  <View className="items-center justify-end flex-1 mx-2 h-full">
    {/* Label at top */}
    <Text className="text-brand-text font-semibold text-xs mb-1">{count}</Text>
    
    {/* The Bar */}
    <View 
      className="w-full bg-brand-orange rounded-t-sm" 
      style={{ height: `${percentage}%`, minHeight: '5%' }} 
    />
    
    {/* X-axis Label */}
    <Text className="text-gray-500 text-[10px] text-center mt-2 h-8 leading-tight">
      {label}
    </Text>
  </View>
);

export const LabourDistributionChart = ({ refreshTrigger = 0, pmId }: { refreshTrigger?: number, pmId?: string }) => {
  const [data, setData] = useState<{label: string, count: number}[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let isMounted = true;
    
    const loadData = async () => {
      try {
        const { data: sessionData } = await supabase.auth.getSession();
        if (!sessionData?.session) {
          if (isMounted) setLoading(false);
          return;
        }

        // Fetch all active projects
        let query = supabase.from('projects').select('id, name').eq('status', 'active');
        if (pmId) {
          query = query.eq('pm_id', pmId);
        }
        const { data: projects } = await query;
        
        // Fetch all attendance for today
        const today = new Date().toISOString().split('T')[0];
        const { data: todayLabour } = await supabase.from('legacy_labour').select('project_id, worker_name').eq('date', today);
        
        if (projects && todayLabour) {
          const counts = projects.map(p => {
            const count = todayLabour.filter(l => l.project_id === p.id).length;
            return { label: p.name, count };
          });
          
          if (isMounted) setData(counts);
        }
      } catch (error) {
        console.warn('Failed to load chart data:', error);
      } finally {
        if (isMounted) setLoading(false);
      }
    };
    
    loadData();
    return () => { isMounted = false; };
  }, [refreshTrigger]);

  const maxCount = Math.max(...data.map(d => d.count), 1); // Avoid division by zero

  return (
    <View className="bg-white rounded-lg p-6 shadow-sm border border-gray-100 flex-1">
      <View className="mb-4">
        <Text className="text-lg font-bold text-brand-text">Labour Distribution</Text>
        <Text className="text-brand-text-muted text-xs">Total assigned workers per project site</Text>
      </View>

      <View className="flex-1 flex-row items-end justify-around pt-4 pb-2 border-b border-gray-100">
        {loading ? (
          <ActivityIndicator color="#F97316" className="self-center flex-1" />
        ) : data.length === 0 ? (
          <Text className="text-gray-400 self-center flex-1 text-center">No projects.</Text>
        ) : (
          data.slice(0, 4).map((d, i) => (
            <Bar key={i} label={d.label} count={d.count} percentage={(d.count / maxCount) * 90} />
          ))
        )}
      </View>
    </View>
  );
};

import React, { useEffect, useState } from 'react';
import { View, Text, Pressable, ActivityIndicator, Alert } from 'react-native';
import { supabase } from '../../lib/supabase';
import { useRouter } from 'expo-router';

const PayrollRow = ({ name, role, total }: { name: string, role: string, total: number }) => (
  <View className="flex-row justify-between items-center py-2 border-b border-gray-50">
    <View className="w-2/3">
      <Text className="text-gray-600 text-sm truncate" numberOfLines={1}>{name}</Text>
      <Text className="text-gray-400 text-xs">{role}</Text>
    </View>
    <Text className="text-brand-text font-semibold text-sm">
      {total >= 1000 ? `Rs. ${(total/1000).toFixed(1)}K` : `Rs. ${total.toFixed(0)}`}
    </Text>
  </View>
);

export const PayrollSummary = ({ refreshTrigger = 0, pmId }: { refreshTrigger?: number, pmId?: string }) => {
  const router = useRouter();
  const [data, setData] = useState<{name: string, role: string, total: number}[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let isMounted = true;
    
    const loadPayroll = async () => {
      try {
        const { data: sessionData } = await supabase.auth.getSession();
        if (!sessionData?.session) {
          if (isMounted) setLoading(false);
          return;
        }

        const today = new Date().toISOString().split('T')[0];
        
        // Fetch attendance from backend API
        const response = await fetch(`${process.env.EXPO_PUBLIC_API_URL}/labour/payroll`, {
          headers: {
            'Authorization': `Bearer ${sessionData.session.access_token}`
          }
        });
        
        if (!response.ok) {
          throw new Error('Failed to fetch payroll data');
        }
        
        const attendance = await response.json();
        
        if (attendance) {
          // Filter by pmId if provided (the backend could ideally do this, but doing it here for now)
          // The backend payroll response might need to include pm_id if we want to filter on frontend, 
          // but since this is an admin dashboard, we can just show all for now or filter if the backend provides it.
          const payrolls = attendance.map((a: any) => {
            const dailyRate = a.daily_rate || 3500;
            const hourlyRate = dailyRate / 8;
            
            const hours = Number(a.total_hours) || 0;
            const baseHours = Math.min(hours, 8 * a.days_present);
            const overtimeHours = Math.max(0, hours - (8 * a.days_present));
            
            const basePay = baseHours * hourlyRate;
            const overtimePay = overtimeHours * hourlyRate * 1.5;
            const total = basePay + overtimePay;
            
            return {
              name: a.worker_name || 'Unknown',
              role: a.role || 'Worker',
              total
            };
          });
          
          if (isMounted) {
            const activePayrolls = payrolls.filter((p: any) => p.total > 0).sort((a: any, b: any) => b.total - a.total);
            setData(activePayrolls);
          }
        }
      } catch (error) {
        console.warn('Failed to load payroll data:', error);
      } finally {
        if (isMounted) setLoading(false);
      }
    };
    
    loadPayroll();
    return () => { isMounted = false; };
  }, [refreshTrigger]);

  const totalAmount = data.reduce((sum, item) => sum + item.total, 0);

  const formatCurrency = (val: number) => {
    if (val >= 1000000) return `Rs. ${(val / 1000000).toFixed(1)}M`;
    if (val >= 1000) return `Rs. ${(val / 1000).toFixed(1)}K`;
    return `Rs. ${val}`;
  };

  const handleApprove = () => {
    if (totalAmount === 0) {
      Alert.alert("No Payroll", "There are no workers checked in today to approve payroll for.");
    } else {
      router.push('/admin/payroll/generate');
    }
  };

  return (
    <View className="bg-white rounded-lg p-6 shadow-sm border border-gray-100 mb-6">
      <View className="mb-4">
        <Text className="text-lg font-bold text-brand-text">Payroll Summary</Text>
        <Text className="text-brand-text-muted text-xs">Estimated daily wages by worker</Text>
      </View>

      <View className="mb-2 min-h-[100px]">
        {loading ? (
          <ActivityIndicator color="#F97316" className="mt-4" />
        ) : data.length === 0 || totalAmount === 0 ? (
          <Text className="text-gray-400 text-sm mt-4 text-center">No active workers today.</Text>
        ) : (
          data.slice(0, 4).map((d, i) => (
            <PayrollRow key={i} name={d.name} role={d.role} total={d.total} />
          ))
        )}
      </View>
      
      <View className="flex-row justify-between items-center py-3 border-t border-gray-200 mb-4 mt-auto">
        <Text className="text-brand-text font-bold text-base">Total Pending</Text>
        <Text className="text-brand-text font-bold text-base">{formatCurrency(totalAmount)}</Text>
      </View>

      <Pressable 
        onPress={handleApprove}
        className="bg-brand-orange w-full py-3 rounded-lg items-center justify-center hover:bg-orange-600 transition-colors"
      >
        <Text className="text-white font-semibold text-sm">Generate Salary Slips</Text>
      </Pressable>
    </View>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { View, Text, TextInput, Pressable, ScrollView, ActivityIndicator, KeyboardAvoidingView, Platform } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { supabase } from '@/lib/supabase';
import { format } from 'date-fns';

export function ChatWidget({ projectId, currentUserId, currentUserRole, targetRole, targetUserId }: {
  projectId: string;
  currentUserId: string;
  currentUserRole: string;
  targetRole?: string;
  targetUserId?: string;
}) {
  const [messages, setMessages] = useState<any[]>([]);
  const [newMessage, setNewMessage] = useState('');
  const [loading, setLoading] = useState(true);
  const scrollViewRef = useRef<ScrollView>(null);

  useEffect(() => {
    fetchMessages();

    // Subscribe to realtime messages
    const subscription = supabase
      .channel(`chat_${projectId}`)
      .on('postgres_changes', { 
        event: 'INSERT', 
        schema: 'public', 
        table: 'messages',
        filter: `project_id=eq.${projectId}`
      }, (payload) => {
        const msg = payload.new;
        // Basic filtering for this channel
        if ((msg.sender_role === currentUserRole && msg.receiver_role === targetRole) ||
            (msg.sender_role === targetRole && msg.receiver_role === currentUserRole) ||
            (targetUserId && msg.sender_id === targetUserId) ||
            (msg.sender_id === currentUserId)) {
          setMessages(prev => [...prev, msg]);
          setTimeout(() => scrollViewRef.current?.scrollToEnd({ animated: true }), 100);
        }
      })
      .subscribe();

    return () => {
      subscription.unsubscribe();
    };
  }, [projectId]);

  const fetchMessages = async () => {
    try {
      let query = supabase
        .from('messages')
        .select('*')
        .eq('project_id', projectId)
        .order('created_at', { ascending: true });

      const { data, error } = await query;
      if (error) throw error;

      // Filter locally for now
      const filtered = data.filter(m => 
        (m.sender_role === currentUserRole && m.receiver_role === targetRole) ||
        (m.sender_role === targetRole && m.receiver_role === currentUserRole) ||
        (targetUserId && (m.sender_id === targetUserId || m.receiver_id === targetUserId)) ||
        (m.sender_role === 'site_manager' && m.receiver_role === 'supplier') ||
        (m.sender_role === 'supplier' && m.receiver_role === 'site_manager')
      );

      setMessages(filtered);
      setTimeout(() => scrollViewRef.current?.scrollToEnd({ animated: false }), 300);
    } catch (err) {
      console.error('Failed to fetch messages:', err);
    } finally {
      setLoading(false);
    }
  };

  const sendMessage = async () => {
    if (!newMessage.trim()) return;
    try {
      const { error } = await supabase.from('messages').insert([{
        project_id: projectId,
        sender_id: currentUserId,
        sender_role: currentUserRole,
        receiver_role: targetRole,
        receiver_id: targetUserId || null,
        content: newMessage.trim(),
      }]);
      if (error) throw error;
      setNewMessage('');
    } catch (err) {
      console.error('Failed to send message:', err);
    }
  };

  if (loading) return <ActivityIndicator color="#F97316" />;

  return (
    <View className="flex-1 bg-white rounded-2xl shadow-sm border border-gray-100 flex-col overflow-hidden min-h-[400px] max-h-[500px]">
      <View className="p-4 border-b border-gray-100 bg-gray-50 flex-row items-center">
        <Ionicons name="chatbubbles" size={20} color="#F97316" className="mr-2" />
        <Text className="font-bold text-gray-800 ml-2">Chat with {targetRole ? targetRole.replace('_', ' ') : 'Team'}</Text>
      </View>

      <ScrollView 
        ref={scrollViewRef}
        className="flex-1 p-4"
        contentContainerStyle={{ paddingBottom: 16 }}
      >
        {messages.length === 0 ? (
          <Text className="text-gray-400 text-center mt-4">No messages yet. Say hello!</Text>
        ) : (
          messages.map(m => {
            const isMe = m.sender_id === currentUserId;
            return (
              <View key={m.id} className={`mb-3 max-w-[80%] ${isMe ? 'self-end' : 'self-start'}`}>
                <View className={`p-3 rounded-2xl ${isMe ? 'bg-brand-orange rounded-tr-none' : 'bg-gray-100 rounded-tl-none'}`}>
                  <Text className={isMe ? 'text-white' : 'text-gray-800'}>{m.content}</Text>
                </View>
                <Text className={`text-[10px] text-gray-400 mt-1 ${isMe ? 'text-right' : 'text-left'}`}>
                  {format(new Date(m.created_at), 'HH:mm')}
                </Text>
              </View>
            );
          })
        )}
      </ScrollView>

      <KeyboardAvoidingView behavior={Platform.OS === 'ios' ? 'padding' : undefined} className="p-3 border-t border-gray-100 flex-row items-center bg-gray-50">
        <TextInput 
          className="flex-1 bg-white border border-gray-200 rounded-full px-4 py-2 text-sm text-gray-800"
          placeholder="Type a message..."
          value={newMessage}
          onChangeText={setNewMessage}
          onSubmitEditing={sendMessage}
        />
        <Pressable 
          onPress={sendMessage}
          className={`ml-2 w-11 h-11 rounded-full items-center justify-center ${newMessage.trim() ? 'bg-brand-orange' : 'bg-gray-300'}`}
          disabled={!newMessage.trim()}
        >
          <Ionicons name="send" size={16} color="white" style={{ marginLeft: 2 }} />
        </Pressable>
      </KeyboardAvoidingView>
    </View>
  );
}

import React, { useEffect, useState, useRef } from 'react';
