      <ScrollView showsVerticalScrollIndicator={false}>
        <View style={{ maxWidth: 580, width: '100%', alignSelf: 'center', paddingHorizontal: 24, paddingTop: 28, paddingBottom: 48 }}>

          {/* Account Hero */}
