            <View style={{ padding: 24, flexDirection: 'row', alignItems: 'center' }}>
              <View style={{
                width: 60, height: 60, borderRadius: 30,
                backgroundColor: rc.color + '25', borderWidth: 2, borderColor: rc.color + '50',
